function totalAssets() public view override returns (uint256) {
        address[] memory assets = AssetRegistry(assetRegistry).getAssets(bitFlag);
        uint256 usdAmount;
        uint256 assetsLength = assets.length;

        BasketManager bm = BasketManager(basketManager);
        EulerRouter eulerRouter = EulerRouter(bm.eulerRouter());

        for (uint256 i = 0; i < assetsLength;) {
            // slither-disable-start calls-loop
            uint256 assetBalance = bm.basketBalanceOf(address(this), assets[i]);
            // Rounding direction: down
            usdAmount += eulerRouter.getQuote(assetBalance, assets[i], _USD_ISO_4217_CODE);
            // slither-disable-end calls-loop

            unchecked {
                // Overflow not possible: i is less than assetsLength
                ++i;
            }
        }

        return eulerRouter.getQuote(usdAmount, _USD_ISO_4217_CODE, asset());
    }

function getTargetWeights() public view returns (uint64[] memory) {
        return WeightStrategy(strategy).getTargetWeights(bitFlag);
    }

function requestRedeem(uint256 shares, address controller, address owner) public returns (uint256 requestId) {
        // Checks
        if (shares == 0) {
            revert Errors.ZeroAmount();
        }
        requestId = nextRedeemRequestId;
        // If the user has a pending redeem request in the past, they must wait for it to be fulfilled before making a
        // new one
        uint256 userLastRedeemRequestId = lastRedeemRequestId[controller];
        if (userLastRedeemRequestId != requestId) {
            if (pendingRedeemRequest(userLastRedeemRequestId, controller) > 0) {
                revert MustClaimOutstandingRedeem();
            }
        }
        // If the user has a claimable redeem request, they must claim it before making a new one
        if (claimableRedeemRequest(userLastRedeemRequestId, controller) > 0 || claimableFallbackShares(controller) > 0)
        {
            revert MustClaimOutstandingRedeem();
        }
        if (msg.sender != owner) {
            if (!isOperator[owner][msg.sender]) {
                _spendAllowance(owner, msg.sender, shares);
            }
        }
        if (AssetRegistry(assetRegistry).hasPausedAssets(bitFlag)) {
            revert AssetPaused();
        }

        // Effects
        RedeemRequestStruct storage redeemRequest = _redeemRequests[requestId];
        // update total pending redemptions for the current requestId
        redeemRequest.totalRedeemShares += shares;
        // update controllers latest redeem request id
        lastRedeemRequestId[controller] = requestId;
        // update controllers balance of assets pending deposit
        redeemRequest.redeemShares[controller] += shares;
        _transfer(owner, address(this), shares);
        emit RedeemRequest(controller, owner, requestId, msg.sender, shares);
    }

function fulfillDeposit(uint256 shares) public {
        // Checks
        _onlyBasketManager();
        // currentRequestId was advanced by 2 to prepare for rebalance
        uint256 currentRequestId = nextDepositRequestId - 2;
        DepositRequestStruct storage depositRequest = _depositRequests[currentRequestId];
        uint256 assets = depositRequest.totalDepositAssets;
        if (assets == 0) {
            revert ZeroPendingDeposits();
        }
        if (shares == 0) {
            revert CannotFulfillWithZeroShares();
        }
        if (depositRequest.fulfilledShares > 0) {
            revert DepositRequestAlreadyFulfilled();
        }
        // Effects
        depositRequest.fulfilledShares = shares;
        emit DepositFulfilled(currentRequestId, assets, shares);
        _mint(address(this), shares);
        // Interactions
        // transfer the assets to the basket manager
        IERC20(asset()).safeTransfer(msg.sender, assets);
    }

function fulfillRedeem(uint256 assets) public {
        // Checks
        _onlyBasketManager();
        uint256 currentRequestId = nextRedeemRequestId - 2;
        RedeemRequestStruct storage redeemRequest = _redeemRequests[currentRequestId];
        uint256 sharesPendingRedemption = redeemRequest.totalRedeemShares;
        if (sharesPendingRedemption == 0) {
            revert ZeroPendingRedeems();
        }
        if (assets == 0) {
            revert CannotFulfillWithZeroAssets();
        }
        if (redeemRequest.fulfilledAssets > 0) {
            revert RedeemRequestAlreadyFulfilled();
        }
        // Effects
        redeemRequest.fulfilledAssets = assets;
        emit RedeemFulfilled(currentRequestId, sharesPendingRedemption, assets);
        _burn(address(this), sharesPendingRedemption);
        // Interactions
        // slither-disable-next-line arbitrary-send-erc20
        IERC20(asset()).safeTransferFrom(msg.sender, address(this), assets);
    }

function cancelDepositRequest() public {
        // Checks
        uint256 nextDepositRequestId_ = nextDepositRequestId;
        uint256 pendingDeposit = pendingDepositRequest(nextDepositRequestId_, msg.sender);
        if (pendingDeposit == 0) {
            revert ZeroPendingDeposits();
        }
        // Effects
        DepositRequestStruct storage depositRequest = _depositRequests[nextDepositRequestId_];
        depositRequest.depositAssets[msg.sender] = 0;
        depositRequest.totalDepositAssets -= pendingDeposit;
        // Interactions
        IERC20(asset()).safeTransfer(msg.sender, pendingDeposit);
    }

function proRataRedeem(uint256 shares, address to, address from) public {
        // Effects
        uint16 feeBps = BasketManager(basketManager).managementFee(address(this));
        address feeCollector = BasketManager(basketManager).feeCollector();
        _harvestManagementFee(feeBps, feeCollector);
        if (msg.sender != from) {
            _spendAllowance(from, msg.sender, shares);
        }
        uint256 totalSupplyBefore = totalSupply();
        _burn(from, shares);
        // Interactions
        BasketManager(basketManager).proRataRedeem(totalSupplyBefore, shares, to);
    }

function claimableRedeemRequest(uint256 requestId, address controller) public view returns (uint256 shares) {
        RedeemRequestStruct storage redeemRequest = _redeemRequests[requestId];
        shares = _claimableRedeemRequest(redeemRequest.fulfilledAssets, redeemRequest.redeemShares[controller]);
    }

function pendingRedeemRequest(uint256 requestId, address controller) public view returns (uint256 shares) {
        RedeemRequestStruct storage redeemRequest = _redeemRequests[requestId];
        shares = redeemRequest.fulfilledAssets == 0 && !redeemRequest.fallbackTriggered
            ? redeemRequest.redeemShares[controller]
            : 0;
    }

function claimableFallbackShares(address controller) public view returns (uint256 shares) {
        RedeemRequestStruct storage redeemRequest = _redeemRequests[lastRedeemRequestId[controller]];
        if (redeemRequest.fallbackTriggered) {
            return redeemRequest.redeemShares[controller];
        }
        return 0;
    }

function _onlyBasketManager() internal view {
        if (basketManager != msg.sender) {
            revert NotBasketManager();
        }
    }

function pendingDepositRequest(uint256 requestId, address controller) public view returns (uint256 assets) {
        DepositRequestStruct storage depositRequest = _depositRequests[requestId];
        assets = depositRequest.fulfilledShares == 0 ? depositRequest.depositAssets[controller] : 0;
    }

function _harvestManagementFee(uint16 feeBps, address feeCollector) internal {
        // Checks
        if (feeBps > _MAX_MANAGEMENT_FEE) {
            revert InvalidManagementFee();
        }
        uint256 timeSinceLastHarvest = block.timestamp - lastManagementFeeHarvestTimestamp;

        // Effects
        lastManagementFeeHarvestTimestamp = uint40(block.timestamp);
        if (feeBps != 0) {
            if (timeSinceLastHarvest != 0) {
                if (timeSinceLastHarvest != block.timestamp) {
                    // remove shares held by the treasury or currently pending redemption from calculation
                    uint256 currentTotalSupply = totalSupply() - balanceOf(feeCollector)
                        - pendingRedeemRequest(lastRedeemRequestId[feeCollector], feeCollector);
                    uint256 fee = FixedPointMathLib.fullMulDiv(
                        currentTotalSupply, feeBps * timeSinceLastHarvest, _MANAGEMENT_FEE_DECIMALS * uint256(365 days)
                    );
                    if (fee != 0) {
                        emit ManagementFeeHarvested(fee);
                        _mint(feeCollector, fee);
                        // Interactions
                        FeeCollector(feeCollector).notifyHarvestFee(fee);
                    }
                }
            }
        }
    }

function emergencyCancel(bytes32 orderId, address recipient) external onlyOwner {
        require(orderStatus[orderId] == IAori.OrderStatus.Active, "Can only cancel active orders");
        require(recipient != address(0), "Invalid recipient address");

        Order memory order = orders[orderId];
        require(order.srcEid == ENDPOINT_ID, "Emergency cancel only allowed on source chain");

        address tokenAddress = order.inputToken;
        uint128 amountToReturn = uint128(order.inputAmount);

        // Validate sufficient balance
        tokenAddress.validateSufficientBalance(amountToReturn);

        orderStatus[orderId] = IAori.OrderStatus.Cancelled;
        bool success = balances[order.offerer][tokenAddress].decreaseLockedNoRevert(amountToReturn);
        require(success, "Failed to decrease locked balance");

        // Transfer tokens to recipient
        tokenAddress.safeTransfer(recipient, amountToReturn);

        emit Cancel(orderId);
        emit Withdraw(recipient, tokenAddress, amountToReturn);
    }

function emergencyWithdraw(
        address token, 
        uint256 amount, 
        address user, 
        bool isLocked,
        address recipient
    ) external onlyOwner {
        require(amount > 0, "Amount must be greater than zero");
        require(user != address(0), "Invalid user address");
        require(recipient != address(0), "Invalid recipient address");

        if (isLocked) {
            bool success = balances[user][token].decreaseLockedNoRevert(uint128(amount));
            require(success, "Failed to decrease locked balance");
        } else {
            uint256 unlockedBalance = balances[user][token].unlocked;
            require(unlockedBalance >= amount, "Insufficient unlocked balance");
            balances[user][token].unlocked = uint128(unlockedBalance - amount);
        }

        // Validate sufficient balance and transfer
        token.validateSufficientBalance(amount);
        token.safeTransfer(recipient, amount);

        emit Withdraw(user, token, amount);
    }

function deposit(
        Order calldata order,
        bytes calldata signature,
        SrcHook calldata hook
    ) external nonReentrant whenNotPaused onlySolver {
        require(hook.isSome(), "Missing hook");
        bytes32 orderId = order.validateDeposit(
            signature,
            _hashOrder712(order),
            ENDPOINT_ID,
            this.orderStatus,
            this.isSupportedChain
        );

        // Execute hook and handle single-chain or cross-chain logic
        (uint256 amountReceived, address tokenReceived) = 
            _executeSrcHook(order, hook);

        emit SrcHookExecuted(orderId, tokenReceived, amountReceived);

        if (order.isSingleChainSwap()) {
            // Save the order details
            orders[orderId] = order;

            // Update order status directly 
            orderStatus[orderId] = IAori.OrderStatus.Settled;
            emit Settle(orderId);
        } else {
            // Process the cross-chain deposit
            _postDeposit(tokenReceived, amountReceived, order, orderId);
        }
    }

function _postDeposit(
        address depositToken,
        uint256 depositAmount,
        Order calldata order,
        bytes32 orderId
    ) internal {
        balances[order.offerer][depositToken].lock(SafeCast.toUint128(depositAmount));
        orderStatus[orderId] = IAori.OrderStatus.Active;
        orders[orderId] = order;
        orders[orderId].inputToken = depositToken;
        orders[orderId].inputAmount = SafeCast.toUint128(depositAmount);

        emit Deposit(orderId, order);
    }

function depositNative(
        Order calldata order,
        bytes calldata signature
    ) external payable nonReentrant whenNotPaused {
        require(order.inputToken.isNativeToken(), "Order must specify native token");
        require(msg.value == order.inputAmount, "Incorrect native amount");
        require(msg.sender == order.offerer, "Only offerer can deposit native tokens");

        bytes32 orderId = order.validateDeposit(
            signature,
            _hashOrder712(order),
            ENDPOINT_ID,
            this.orderStatus,
            this.isSupportedChain
        );

        _postDeposit(order.inputToken, order.inputAmount, order, orderId);
    }

function fill(
        Order calldata order,
        IAori.DstHook calldata hook
    ) external payable nonReentrant whenNotPaused onlySolver {

        bytes32 orderId = order.validateFill(
            ENDPOINT_ID,
            this.orderStatus
        );
        uint256 amountReceived = _executeDstHook(order, hook);

        emit DstHookExecuted(orderId, hook.preferredToken, amountReceived);

        uint256 surplus = amountReceived - order.outputAmount;

        // Handle native or ERC20 output with surplus
        if (order.outputToken.isNativeToken()) {
            order.outputToken.safeTransfer(order.recipient, order.outputAmount);

            if (surplus > 0) {
                order.outputToken.safeTransfer(msg.sender, surplus);
            }
        } else {
            IERC20(order.outputToken).safeTransfer(order.recipient, order.outputAmount);

            if (surplus > 0) {
                IERC20(order.outputToken).safeTransfer(msg.sender, surplus);
            }
        }

        // Handle settlement based on chain type
        if (order.isSingleChainSwap()) {
            // For single-chain swaps, settle immediately with proper balance accounting
            _settleSingleChainSwap(orderId, order, msg.sender);
        } else {
            // For cross-chain swaps, use normal fill processing
            _postFill(orderId, order);
        }
    }

function _settleSingleChainSwap(
        bytes32 orderId,
        Order memory order,
        address solver
    ) internal {
        // Capture initial balance state for validation
        uint128 initialOffererLocked = balances[order.offerer][order.inputToken].locked;
        uint128 initialSolverUnlocked = balances[solver][order.inputToken].unlocked;

        // Move tokens from offerer's locked balance to solver's unlocked balance
        if (balances[order.offerer][order.inputToken].locked >= order.inputAmount) {
            bool successLock = balances[order.offerer][order.inputToken].decreaseLockedNoRevert(
                uint128(order.inputAmount)
            );

            bool successUnlock = balances[solver][order.inputToken].increaseUnlockedNoRevert(
                uint128(order.inputAmount)
            );

            require(successLock && successUnlock, "Balance operation failed");
        }

        // Validate balance transfer
        uint128 finalOffererLocked = balances[order.offerer][order.inputToken].locked;
        uint128 finalSolverUnlocked = balances[solver][order.inputToken].unlocked;

        balances[order.offerer][order.inputToken].validateBalanceTransferOrRevert(
            initialOffererLocked,
            finalOffererLocked,
            initialSolverUnlocked,
            finalSolverUnlocked,
            uint128(order.inputAmount)
        );

        // Order is immediately settled
        orderStatus[orderId] = IAori.OrderStatus.Settled;
        emit Settle(orderId);
    }

function cancel(
        bytes32 orderId,
        Order calldata orderToCancel,
        bytes calldata extraOptions
    ) external payable nonReentrant whenNotPaused {
        require(hash(orderToCancel) == orderId, "Submitted order data doesn't match orderId");

        orderToCancel.validateCancel(
            orderId,
            ENDPOINT_ID,
            this.orderStatus,
            msg.sender,
            this.isAllowedSolver
        );
        bytes memory payload = PayloadPackUtils.packCancellation(orderId);
        MessagingReceipt memory receipt = __lzSend(orderToCancel.srcEid, payload, extraOptions);
        orderStatus[orderId] = IAori.OrderStatus.Cancelled;
        emit CancelSent(orderId, receipt.guid, receipt.nonce, receipt.fee.nativeFee);
    }

function _cancel(bytes32 orderId) internal {
        require(orderStatus[orderId] == IAori.OrderStatus.Active, "Can only cancel active orders");

        // Get order details and amount before changing state
        Order memory order = orders[orderId];
        uint128 amountToReturn = uint128(order.inputAmount);
        address tokenAddress = order.inputToken;
        address recipient = order.offerer;

        // Validate contract has sufficient tokens before any state changes
        tokenAddress.validateSufficientBalance(amountToReturn);

        // Update state first (checks-effects)
        orderStatus[orderId] = IAori.OrderStatus.Cancelled;

        // Decrease locked balance
        bool success = balances[recipient][tokenAddress].decreaseLockedNoRevert(amountToReturn);
        require(success, "Failed to decrease locked balance");

        // Transfer tokens directly to offerer (interactions)
        tokenAddress.safeTransfer(recipient, amountToReturn);

        // Emit the Cancel event from IAori interface
        emit Cancel(orderId);
    }

function withdraw(address token, uint256 amount) external nonReentrant whenNotPaused {
        address holder = msg.sender;
        uint256 unlockedBalance = balances[holder][token].unlocked;
        require(unlockedBalance > 0, "Non-zero balance required");

        if (amount == 0) {
            amount = unlockedBalance;
        } else {
            require(unlockedBalance >= amount, "Insufficient unlocked balance");
        }

        // Validate sufficient contract balance and transfer
        token.validateSufficientBalance(amount);
        token.safeTransfer(holder, amount);

        balances[holder][token].unlocked = uint128(unlockedBalance - amount);
        emit Withdraw(holder, token, amount);
    }

function _hashOrder712(Order calldata order) internal view returns (bytes32) {
        return
            _hashTypedDataSansChainId(
                keccak256(
                    abi.encode(
                        _ORDER_TYPEHASH,
                        order.inputAmount,
                        order.outputAmount,
                        order.inputToken,
                        order.outputToken,
                        order.startTime,
                        order.endTime,
                        order.srcEid,
                        order.dstEid,
                        order.offerer,
                        order.recipient
                    )
                )
            );
    }

function _postFill(bytes32 orderId, Order calldata order) internal {
        orderStatus[orderId] = IAori.OrderStatus.Filled;
        srcEidToFillerFills[order.srcEid][msg.sender].push(orderId);
        emit Fill(orderId, order);
    }

function initialize(
        address _token,
        address _stakingPool,
        address _stakeManager,
        address _vaultImplementation,
        uint256 _validatorMEVRewardsPercentage,
        Fee[] memory _fees
    ) public initializer {
        __Strategy_init(_token, _stakingPool);

        stakeManager = _stakeManager;
        vaultImplementation = _vaultImplementation;

        if (_validatorMEVRewardsPercentage > 5000) revert FeesTooLarge();
        validatorMEVRewardsPercentage = _validatorMEVRewardsPercentage;

        for (uint256 i = 0; i < _fees.length; ++i) {
            fees.push(_fees[i]);
        }
        if (_totalFeesBasisPoints() > 3000) revert FeesTooLarge();
    }

function deposit(uint256 _amount, bytes calldata) external onlyStakingPool {
        token.safeTransferFrom(msg.sender, address(this), _amount);
        totalDeposits += _amount;
        totalQueued += _amount;
    }

function withdraw(uint256 _amount, bytes calldata) external onlyStakingPool {
        token.safeTransfer(msg.sender, _amount);
        totalDeposits -= _amount;
        totalQueued -= _amount;
    }

function depositQueuedTokens(
        uint256[] calldata _vaultIds,
        uint256[] calldata _amounts
    ) external onlyFundFlowController {
        if (numVaultsUnbonding != 0) revert UnbondingInProgress();

        uint256 preBalance = token.balanceOf(address(this));
        uint256 skipIndex = validatorRemoval.isActive
            ? validatorRemoval.validatorId
            : type(uint256).max;

        for (uint256 i = 0; i < _vaultIds.length; ++i) {
            if (_vaultIds[i] == skipIndex) revert InvalidVaultIds();

            uint256 amount = _amounts[i];
            if (amount == 0) revert InvalidAmount();

            vaults[_vaultIds[i]].deposit(amount);
        }

        // balance change could be positive if many rewards are claimed while depositing
        int256 balanceChange = int256(token.balanceOf(address(this))) - int256(preBalance);
        if (balanceChange < 0) {
            totalQueued -= uint256(-1 * balanceChange);
        } else if (balanceChange > 0) {
            totalQueued += uint256(balanceChange);
        }

        emit DepositQueuedTokens(balanceChange);
    }

function unbond(uint256 _toUnbond) external onlyFundFlowController {
        if (numVaultsUnbonding != 0) revert UnbondingInProgress();
        if (_toUnbond == 0) revert InvalidAmount();

        uint256 toUnbondRemaining = _toUnbond;

        uint256 i = validatorWithdrawalIndex;
        uint256 skipIndex = validatorRemoval.isActive
            ? validatorRemoval.validatorId
            : type(uint256).max;
        uint256 numVaultsUnbonded;
        uint256 preBalance = token.balanceOf(address(this));

        while (toUnbondRemaining != 0) {
            if (i != skipIndex) {
                IPolygonVault vault = vaults[i];
                uint256 deposits = vault.getTotalDeposits();

                if (deposits != 0) {
                    uint256 principalDeposits = vault.getPrincipalDeposits();
                    uint256 rewards = deposits - principalDeposits;

                    if (rewards >= toUnbondRemaining && rewards >= vault.minRewardClaimAmount()) {
                        vault.withdrawRewards();
                        toUnbondRemaining = 0;
                        break;
                    } else if (principalDeposits != 0) {
                        if (toUnbondRemaining > rewards) {
                            toUnbondRemaining -= rewards;
                        }

                        uint256 vaultToUnbond = principalDeposits >= toUnbondRemaining
                            ? toUnbondRemaining
                            : principalDeposits;

                        vault.unbond(vaultToUnbond);

                        toUnbondRemaining -= vaultToUnbond;
                        ++numVaultsUnbonded;
                    }
                }
            }

            ++i;
            if (i >= vaults.length) i = 0;
            if (i == validatorWithdrawalIndex) break;
        }

        if (numVaultsUnbonded != 0) {
            validatorWithdrawalIndex = i;
            numVaultsUnbonding = numVaultsUnbonded;
        }

        uint256 rewardsClaimed = token.balanceOf(address(this)) - preBalance;
        if (rewardsClaimed != 0) totalQueued += rewardsClaimed;

        emit Unbond(_toUnbond);
    }

function forceUnbond(
        uint256[] calldata _vaultIds,
        uint256[] calldata _amounts
    ) external onlyFundFlowController {
        if (numVaultsUnbonding != 0) revert UnbondingInProgress();

        uint256 skipIndex = validatorRemoval.isActive
            ? validatorRemoval.validatorId
            : type(uint256).max;
        uint256 totalUnbonded;
        uint256 preBalance = token.balanceOf(address(this));

        for (uint256 i = 0; i < _vaultIds.length; ++i) {
            if (_vaultIds[i] == skipIndex) revert InvalidVaultIds();
            if (i > 0 && _vaultIds[i] <= _vaultIds[i - 1]) revert InvalidVaultIds();
            if (_amounts[i] == 0) revert InvalidAmount();

            vaults[_vaultIds[i]].unbond(_amounts[i]);
            totalUnbonded += _amounts[i];
        }

        numVaultsUnbonding = _vaultIds.length;

        uint256 rewardsClaimed = token.balanceOf(address(this)) - preBalance;
        if (rewardsClaimed != 0) totalQueued += rewardsClaimed;

        emit ForceUnbond(totalUnbonded);
    }

function unstakeClaim(uint256[] calldata _vaultIds) external onlyFundFlowController {
        if (numVaultsUnbonding == 0) revert NoVaultsUnbonding();

        uint256 preBalance = token.balanceOf(address(this));
        uint256 skipIndex = validatorRemoval.isActive
            ? validatorRemoval.validatorId
            : type(uint256).max;
        uint256 vaultsWithdrawn;

        for (uint256 i = 0; i < _vaultIds.length; ++i) {
            if (_vaultIds[i] == skipIndex) revert InvalidVaultIds();

            vaults[_vaultIds[i]].withdraw();
            ++vaultsWithdrawn;
        }

        if (vaultsWithdrawn != numVaultsUnbonding) revert MustWithdrawAllVaults();
        numVaultsUnbonding = 0;

        uint256 amountWithdrawn = token.balanceOf(address(this)) - preBalance;
        totalQueued += amountWithdrawn;

        emit UnstakeClaim(amountWithdrawn);
    }

function getDepositChange() public view returns (int) {
        uint256 totalBalance = token.balanceOf(address(this));

        for (uint256 i = 0; i < vaults.length; ++i) {
            totalBalance += vaults[i].getTotalDeposits();
        }
        return int(totalBalance) - int(totalDeposits);
    }

function updateDeposits(
        bytes calldata
    )
        external
        onlyStakingPool
        returns (int256 depositChange, address[] memory receivers, uint256[] memory amounts)
    {
        depositChange = getDepositChange();
        uint256 balance = token.balanceOf(address(this));

        if (depositChange > 0) {
            totalDeposits += uint256(depositChange);

            uint256 validatorMEVRewards = ((balance - totalQueued) *
                validatorMEVRewardsPercentage) / 10000;

            receivers = new address[](fees.length + (validatorMEVRewards != 0 ? 1 : 0));
            amounts = new uint256[](receivers.length);

            for (uint256 i = 0; i < fees.length; ++i) {
                receivers[i] = fees[i].receiver;
                amounts[i] = (uint256(depositChange) * fees[i].basisPoints) / 10000;
            }

            if (validatorMEVRewards != 0) {
                receivers[receivers.length - 1] = address(validatorMEVRewardsPool);
                amounts[amounts.length - 1] = validatorMEVRewards;
            }
        } else if (depositChange < 0) {
            totalDeposits -= uint256(depositChange * -1);
        }

        totalQueued = balance;
    }

function restakeRewards(uint256[] calldata _vaultIds) external {
        for (uint256 i = 0; i < _vaultIds.length; ++i) {
            vaults[_vaultIds[i]].restakeRewards();
        }

        emit RestakeRewards();
    }

function addValidator(address _pool, address _rewardsReceiver) external onlyOwner {
        for (uint256 i = 0; i < validators.length; ++i) {
            if (validators[i].pool == _pool) revert ValidatorAlreadyAdded();
        }
        validatorMEVRewardsPool.updateReward(_rewardsReceiver);
        validators.push(Validator(_pool, _rewardsReceiver));

        address vault = address(
            new ERC1967Proxy(
                vaultImplementation,
                abi.encodeWithSignature(
                    "initialize(address,address,address,address)",
                    address(token),
                    address(this),
                    stakeManager,
                    _pool
                )
            )
        );
        token.safeApprove(vault, type(uint256).max);
        vaults.push(IPolygonVault(vault));

        emit AddValidator(_pool, _rewardsReceiver);
    }

function queueValidatorRemoval(uint256 _validatorId) external onlyOwner {
        if (validatorRemoval.isActive) revert RemovalAlreadyQueued();

        IPolygonVault vault = vaults[_validatorId];
        uint256 principalDeposits = vault.getPrincipalDeposits();

        if (vault.isUnbonding() || vault.isWithdrawable()) {
            --numVaultsUnbonding;
        }

        if (principalDeposits != 0) {
            uint256 preBalance = token.balanceOf(address(this));
            vault.unbond(principalDeposits);
            uint256 rewardsClaimed = token.balanceOf(address(this)) - preBalance;
            if (rewardsClaimed != 0) totalQueued += rewardsClaimed;
        }

        validatorMEVRewardsPool.updateReward(validators[_validatorId].rewardsReceiver);

        uint256 queuedWithdrawals = vault.getQueuedWithdrawals();
        validatorRemoval = ValidatorRemoval(true, uint64(_validatorId), uint128(queuedWithdrawals));

        emit QueueValidatorRemoval(
            validators[_validatorId].pool,
            validators[_validatorId].rewardsReceiver
        );

        delete validators[_validatorId].rewardsReceiver;
    }

function finalizeValidatorRemoval() external onlyOwner {
        if (!validatorRemoval.isActive) revert NoRemovalQueued();

        uint256 validatorId = validatorRemoval.validatorId;
        uint256 preBalance = token.balanceOf(address(this));

        IPolygonVault vault = vaults[validatorId];
        if (vault.getQueuedWithdrawals() != 0) {
            vault.withdraw();
        }

        uint256 amountWithdrawn = token.balanceOf(address(this)) - preBalance;
        totalQueued += amountWithdrawn;

        token.safeApprove(address(vault), 0);

        emit FinalizeValidatorRemoval(validators[validatorId].pool);

        if (
            validatorId == validators.length - 1 &&
            validatorWithdrawalIndex == validators.length - 1
        ) {
            validatorWithdrawalIndex = 0;
        } else if (validatorWithdrawalIndex > validatorId) {
            --validatorWithdrawalIndex;
        }

        for (uint256 i = validatorId; i < validators.length - 1; ++i) {
            validators[i] = validators[i + 1];
            vaults[i] = vaults[i + 1];
        }

        validators.pop();
        vaults.pop();

        delete validatorRemoval;
    }

function upgradeVaults(address[] calldata _vaults, bytes[] memory _data) external onlyOwner {
        for (uint256 i = 0; i < _vaults.length; ++i) {
            if (_data.length == 0 || _data[i].length == 0) {
                IPolygonVault(_vaults[i]).upgradeTo(vaultImplementation);
            } else {
                IPolygonVault(_vaults[i]).upgradeToAndCall(vaultImplementation, _data[i]);
            }
        }
        emit UpgradedVaults(_vaults);
    }

function addFee(address _receiver, uint256 _feeBasisPoints) external onlyOwner {
        _updateStrategyRewards();
        fees.push(Fee(_receiver, _feeBasisPoints));
        if (_totalFeesBasisPoints() > 3000) revert FeesTooLarge();
        emit AddFee(_receiver, _feeBasisPoints);
    }

function updateFee(
        uint256 _index,
        address _receiver,
        uint256 _feeBasisPoints
    ) external onlyOwner {
        _updateStrategyRewards();

        if (_feeBasisPoints == 0) {
            Fee memory toRemove = fees[_index];
            fees[_index] = fees[fees.length - 1];
            fees.pop();
            emit RemoveFee(_index, toRemove.receiver, toRemove.basisPoints);
        } else {
            fees[_index].receiver = _receiver;
            fees[_index].basisPoints = _feeBasisPoints;
            if (_totalFeesBasisPoints() > 3000) revert FeesTooLarge();
            emit UpdateFee(_index, _receiver, _feeBasisPoints);
        }
    }

function _totalFeesBasisPoints() private view returns (uint256) {
        uint256 totalFees;
        for (uint i = 0; i < fees.length; ++i) {
            totalFees += fees[i].basisPoints;
        }
        return totalFees;
    }

function addLiquidity(AddLiquidityParams calldata params)
        external
        payable
        virtual
        ensure(params.deadline)
        returns (BalanceDelta delta)
    {
        (uint160 sqrtPriceX96,,,) = poolManager.getSlot0(poolKey.toId());

        if (sqrtPriceX96 == 0) revert PoolNotInitialized();

        // Revert if msg.value is non-zero but currency0 is not native
        bool isNative = poolKey.currency0.isAddressZero();
        if (!isNative && msg.value > 0) revert InvalidNativeValue();

        // Get the liquidity modification parameters and the amount of liquidity shares to mint
        (bytes memory modifyParams, uint256 shares) = _getAddLiquidity(sqrtPriceX96, params);

        // Apply the liquidity modification
        (BalanceDelta callerDelta, BalanceDelta feesAccrued) = _modifyLiquidity(modifyParams);

        // Mint the liquidity shares to sender
        _mint(params, callerDelta, feesAccrued, shares);

        // Get the principal delta by subtracting the fee delta from the caller delta (-= is not supported)
        delta = callerDelta - feesAccrued;

        // Check for slippage on principal delta
        uint128 amount0 = uint128(-delta.amount0());
        if (amount0 < params.amount0Min || uint128(-delta.amount1()) < params.amount1Min) {
            revert TooMuchSlippage();
        }

        // If the currency0 is native, refund any remaining msg.value that wasn't used based on the principal delta
        if (isNative) {
            // Check that delta amount was covered by msg.value given that settle would be valid if hook can pay for difference
            // It also allows users to provide more native value than the desired amount
            if (msg.value < amount0) revert InvalidNativeValue();

            // Previous check prevents underflow revert
            poolKey.currency0.transfer(msg.sender, msg.value - amount0);
        }
    }

function removeLiquidity(RemoveLiquidityParams calldata params)
        external
        virtual
        ensure(params.deadline)
        returns (BalanceDelta delta)
    {
        (uint160 sqrtPriceX96,,,) = poolManager.getSlot0(poolKey.toId());

        if (sqrtPriceX96 == 0) revert PoolNotInitialized();

        // Get the liquidity modification parameters and the amount of liquidity shares to burn
        (bytes memory modifyParams, uint256 shares) = _getRemoveLiquidity(params);

        // Apply the liquidity modification
        (BalanceDelta callerDelta, BalanceDelta feesAccrued) = _modifyLiquidity(modifyParams);

        // Burn the liquidity shares from the sender
        _burn(params, callerDelta, feesAccrued, shares);

        // Get the principal delta by subtracting the fee delta from the caller delta (-= is not supported)
        delta = callerDelta - feesAccrued;

        // Check for slippage
        if (uint128(delta.amount0()) < params.amount0Min || uint128(delta.amount1()) < params.amount1Min) {
            revert TooMuchSlippage();
        }
    }

function unlockCallback(bytes calldata rawData)
        external
        virtual
        override
        onlyPoolManager
        returns (bytes memory returnData)
    {
        CallbackData memory data = abi.decode(rawData, (CallbackData));
        PoolKey memory key = poolKey;

        // Set the salt value of the liquidity position, which is the keccak256 hash of the sender and salt from the callback data
        // This ensures that each liquidity position is unique and cannot be accessed by other users
        data.params.salt = keccak256(abi.encode(data.sender, data.params.salt));

        // Get liquidity modification deltas
        (BalanceDelta callerDelta, BalanceDelta feesAccrued) = poolManager.modifyLiquidity(key, data.params, "");

        // Calculate the principal delta
        BalanceDelta principalDelta = callerDelta - feesAccrued;

        // Handle each currency amount based on its sign after applying the liquidity modification
        if (principalDelta.amount0() < 0) {
            // If amount0 is negative, send tokens from the sender to the pool
            key.currency0.settle(poolManager, data.sender, uint256(int256(-principalDelta.amount0())), false);
        } else {
            // If amount0 is positive, send tokens from the pool to the sender
            key.currency0.take(poolManager, data.sender, uint256(int256(principalDelta.amount0())), false);
        }

        if (principalDelta.amount1() < 0) {
            // If amount1 is negative, send tokens from the sender to the pool
            key.currency1.settle(poolManager, data.sender, uint256(int256(-principalDelta.amount1())), false);
        } else {
            // If amount1 is positive, send tokens from the pool to the sender
            key.currency1.take(poolManager, data.sender, uint256(int256(principalDelta.amount1())), false);
        }

        // Handle any accrued fees (by default, transfer all fees to the sender)
        _handleAccruedFees(data, callerDelta, feesAccrued);

        // Return both deltas so that slippage checks can be done on the principal delta
        return abi.encode(callerDelta, feesAccrued);
    }

function _handleAccruedFees(CallbackData memory data, BalanceDelta callerDelta, BalanceDelta feesAccrued)
        internal
        virtual
    {
        // Send any accrued fees to the sender
        poolKey.currency0.take(poolManager, data.sender, uint256(int256(feesAccrued.amount0())), false);
        poolKey.currency1.take(poolManager, data.sender, uint256(int256(feesAccrued.amount1())), false);
    }

function initialize(
        FolioBasicDetails calldata _basicDetails,
        FolioAdditionalDetails calldata _additionalDetails,
        address _creator,
        address _daoFeeRegistry,
        address _trustedFillerRegistry,
        bool _trustedFillerEnabled
    ) external initializer {
        __ERC20_init(_basicDetails.name, _basicDetails.symbol);
        __AccessControlEnumerable_init();
        __AccessControl_init();
        __ReentrancyGuard_init();

        _setFeeRecipients(_additionalDetails.feeRecipients);
        _setTVLFee(_additionalDetails.tvlFee);
        _setMintFee(_additionalDetails.mintFee);
        _setAuctionLength(_additionalDetails.auctionLength);
        _setMandate(_additionalDetails.mandate);
        _setTrustedFillerRegistry(_trustedFillerRegistry, _trustedFillerEnabled);

        daoFeeRegistry = IFolioDAOFeeRegistry(_daoFeeRegistry);

        require(_basicDetails.initialShares != 0, Folio__ZeroInitialShares());

        uint256 assetLength = _basicDetails.assets.length;
        require(assetLength != 0, Folio__EmptyAssets());

        for (uint256 i; i < assetLength; i++) {
            require(_basicDetails.assets[i] != address(0), Folio__InvalidAsset());

            uint256 assetBalance = IERC20(_basicDetails.assets[i]).balanceOf(address(this));
            require(assetBalance != 0, Folio__InvalidAssetAmount(_basicDetails.assets[i]));

            _addToBasket(_basicDetails.assets[i]);
        }

        lastPoke = block.timestamp;

        _mint(_creator, _basicDetails.initialShares);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

function mint(
        uint256 shares,
        address receiver,
        uint256 minSharesOut
    ) external nonReentrant notDeprecated sync returns (address[] memory _assets, uint256[] memory _amounts) {
        // === Calculate fee shares ===

        (, uint256 daoFeeNumerator, uint256 daoFeeDenominator, uint256 daoFeeFloor) = daoFeeRegistry.getFeeDetails(
            address(this)
        );

        // ensure DAO fee floor is at least 3 bps (set just above daily MAX_TVL_FEE)
        daoFeeFloor = Math.max(daoFeeFloor, MIN_MINT_FEE);

        // {share} = {share} * D18{1} / D18
        uint256 totalFeeShares = (shares * mintFee + D18 - 1) / D18;
        uint256 daoFeeShares = (totalFeeShares * daoFeeNumerator + daoFeeDenominator - 1) / daoFeeDenominator;

        // ensure DAO's portion of fees is at least the DAO feeFloor
        uint256 minDaoShares = (shares * daoFeeFloor + D18 - 1) / D18;
        daoFeeShares = daoFeeShares < minDaoShares ? minDaoShares : daoFeeShares;

        // 100% to DAO, if necessary
        totalFeeShares = totalFeeShares < daoFeeShares ? daoFeeShares : totalFeeShares;

        // {share}
        uint256 sharesOut = shares - totalFeeShares;
        require(sharesOut != 0 && sharesOut >= minSharesOut, Folio__InsufficientSharesOut());

        // === Transfer assets in ===

        (_assets, _amounts) = _toAssets(shares, Math.Rounding.Ceil);

        uint256 assetLength = _assets.length;
        for (uint256 i; i < assetLength; i++) {
            if (_amounts[i] != 0) {
                SafeERC20.safeTransferFrom(IERC20(_assets[i]), msg.sender, address(this), _amounts[i]);
            }
        }

        // === Mint shares ===

        _mint(receiver, sharesOut);

        // defer fee handouts until distributeFees()
        daoPendingFeeShares += daoFeeShares;
        feeRecipientsPendingFeeShares += totalFeeShares - daoFeeShares;
    }

function distributeFees() public nonReentrant sync {
        // daoPendingFeeShares and feeRecipientsPendingFeeShares are up-to-date

        // === Fee recipients ===

        uint256 _feeRecipientsPendingFeeShares = feeRecipientsPendingFeeShares;
        feeRecipientsPendingFeeShares = 0;
        uint256 feeRecipientsTotal;

        uint256 len = feeRecipients.length;
        for (uint256 i; i < len; i++) {
            // {share} = {share} * D18{1} / D18
            uint256 shares = (_feeRecipientsPendingFeeShares * feeRecipients[i].portion) / D18;
            feeRecipientsTotal += shares;

            _mint(feeRecipients[i].recipient, shares);

            emit FolioFeePaid(feeRecipients[i].recipient, shares);
        }

        // === DAO ===

        // {share}
        uint256 daoShares = daoPendingFeeShares + _feeRecipientsPendingFeeShares - feeRecipientsTotal;

        (address daoRecipient, , , ) = daoFeeRegistry.getFeeDetails(address(this));
        _mint(daoRecipient, daoShares);
        emit ProtocolFeePaid(daoRecipient, daoShares);

        daoPendingFeeShares = 0;
    }

function getRebalance()
        external
        view
        returns (
            address[] memory tokens,
            BasketRange[] memory limits,
            Prices[] memory prices,
            bool[] memory inRebalance
        )
    {
        tokens = basket.values();
        uint256 len = tokens.length;
        limits = new BasketRange[](len);
        prices = new Prices[](len);
        inRebalance = new bool[](len);

        for (uint256 i; i < len; i++) {
            RebalanceDetails storage details = rebalance.details[tokens[i]];
            limits[i] = details.limits;
            prices[i] = details.prices;
            inRebalance[i] = details.inRebalance;
        }
    }

function startRebalance(
        address[] calldata newTokens,
        BasketRange[] calldata newLimits,
        Prices[] calldata newPrices,
        uint256 auctionLauncherWindow,
        uint256 ttl
    ) external onlyRole(REBALANCE_MANAGER) nonReentrant notDeprecated sync {
        require(ttl >= auctionLauncherWindow && ttl <= MAX_TTL, Folio__InvalidTTL());

        // keep old tokens in the basket for mint/redeem, but remove from rebalance
        address[] memory oldTokens = basket.values();
        uint256 len = oldTokens.length;
        for (uint256 i; i < len; i++) {
            delete rebalance.details[oldTokens[i]];
        }

        len = newTokens.length;
        require(len != 0 && len == newLimits.length && len == newPrices.length, Folio__InvalidArrayLengths());

        // enforce that if one price is 0, all prices are 0
        bool deferPrices = newPrices[0].low == 0;

        // set new basket
        for (uint256 i; i < len; i++) {
            address token = newTokens[i];

            require(!rebalance.details[token].inRebalance, Folio__DuplicateAsset());

            require(
                newLimits[i].low <= newLimits[i].spot &&
                    newLimits[i].spot <= newLimits[i].high &&
                    newLimits[i].high <= MAX_LIMIT,
                Folio__InvalidLimits()
            );

            require(newLimits[i].spot != 0 || newLimits[i].high == 0, Folio__InvalidLimits());

            require(
                deferPrices == (newPrices[i].low == 0) && deferPrices == (newPrices[i].high == 0),
                Folio__InvalidPrices()
            );

            if (!deferPrices) {
                require(
                    newPrices[i].low <= newPrices[i].high &&
                        newPrices[i].high <= MAX_TOKEN_PRICE &&
                        newPrices[i].high / newPrices[i].low <= MAX_TOKEN_PRICE_RANGE,
                    Folio__InvalidPrices()
                );
            }

            _addToBasket(token);
            rebalance.details[token] = RebalanceDetails({
                inRebalance: true,
                limits: newLimits[i],
                prices: newPrices[i]
            });
        }

        rebalance.nonce++;
        rebalance.startedAt = block.timestamp;
        rebalance.restrictedUntil = block.timestamp + auctionLauncherWindow;
        rebalance.availableUntil = block.timestamp + ttl;

        emit RebalanceStarted(
            rebalance.nonce,
            newTokens,
            newLimits,
            newPrices,
            block.timestamp + auctionLauncherWindow,
            block.timestamp + ttl
        );
    }

function openAuction(
        IERC20 sellToken,
        IERC20 buyToken,
        uint256 sellLimit,
        uint256 buyLimit,
        uint256 startPrice,
        uint256 endPrice
    ) external onlyRole(AUCTION_LAUNCHER) nonReentrant notDeprecated sync returns (uint256 auctionId) {
        // auction launcher can:
        //   - select a sell limit within the approved basket weight range
        //   - select a buy limit within the approved basket weight range
        //   - raise starting price by up to 100x
        //   - raise ending price arbitrarily (can cause auction not to clear, same end result as closing auction)

        RebalanceDetails storage sellDetails = rebalance.details[address(sellToken)];
        RebalanceDetails storage buyDetails = rebalance.details[address(buyToken)];

        // startRebalance invariant: if any of the tokens have a 0 price, they must all have a 0 price
        if (sellDetails.prices.high != 0) {
            // D27{buyTok/sellTok} = D27 * D27{UoA/sellTok} / D27{UoA/buyTok}
            uint256 oldStartPrice = (D27 * sellDetails.prices.high + buyDetails.prices.low - 1) / buyDetails.prices.low;
            uint256 oldEndPrice = (D27 * sellDetails.prices.low + buyDetails.prices.high - 1) / buyDetails.prices.high;

            // allow up to 100x price increase
            require(
                startPrice >= oldStartPrice && startPrice <= 100 * oldStartPrice && endPrice >= oldEndPrice,
                Folio__InvalidPrices()
            );
        }

        // for upgraded Folios, pick up on the next auction index from the old array
        nextAuctionId = nextAuctionId != 0 ? nextAuctionId : auctions_DEPRECATED.length;
        auctionId = nextAuctionId++;

        AuctionLib.AuctionArgs memory args = AuctionLib.AuctionArgs({
            auctionId: auctionId,
            sellToken: sellToken,
            buyToken: buyToken,
            sellLimit: sellLimit,
            buyLimit: buyLimit,
            startPrice: startPrice,
            endPrice: endPrice,
            auctionBuffer: 0
        });

        // many more checks, including confirming sellToken is in surplus and buyToken is in deficit
        AuctionLib.openAuction(rebalance, auctions, auctionEnds, totalSupply(), auctionLength, args);
    }

function openAuctionUnrestricted(
        IERC20 sellToken,
        IERC20 buyToken
    ) external nonReentrant notDeprecated sync returns (uint256 auctionId) {
        require(block.timestamp >= rebalance.restrictedUntil, Folio__AuctionCannotBeOpenedWithoutRestriction());

        // open an auction on spot limits + full price range

        RebalanceDetails storage sellDetails = rebalance.details[address(sellToken)];
        RebalanceDetails storage buyDetails = rebalance.details[address(buyToken)];

        // startRebalance invariant: if any of the tokens have a 0 price, they must all have a 0 price
        require(buyDetails.prices.low != 0, Folio__AuctionCannotBeOpenedWithoutRestriction());

        // D27{buyTok/sellTok} = D27 * D27{UoA/sellTok} / D27{UoA/buyTok}
        uint256 startPrice = (D27 * sellDetails.prices.high + buyDetails.prices.low - 1) / buyDetails.prices.low;
        uint256 endPrice = (D27 * sellDetails.prices.low + buyDetails.prices.high - 1) / buyDetails.prices.high;

        // for upgraded Folios, pick up on the next auction index from the old array
        nextAuctionId = nextAuctionId != 0 ? nextAuctionId : auctions_DEPRECATED.length;
        auctionId = nextAuctionId++;

        AuctionLib.AuctionArgs memory args = AuctionLib.AuctionArgs({
            auctionId: auctionId,
            sellToken: sellToken,
            buyToken: buyToken,
            sellLimit: sellDetails.limits.spot,
            buyLimit: buyDetails.limits.spot,
            startPrice: startPrice,
            endPrice: endPrice,
            auctionBuffer: RESTRICTED_AUCTION_BUFFER
        });

        // many more checks, including confirming sellToken is in surplus and buyToken is in deficit
        AuctionLib.openAuction(rebalance, auctions, auctionEnds, totalSupply(), auctionLength, args);
    }

function getBid(
        uint256 auctionId,
        uint256 timestamp,
        uint256 maxSellAmount
    ) external view returns (uint256 sellAmount, uint256 bidAmount, uint256 price) {
        Auction storage auction = auctions[auctionId];

        require(auction.rebalanceNonce == rebalance.nonce, Folio__AuctionNotOngoing());

        // checks auction is ongoing and that sellAmount is below maxSellAmount
        (sellAmount, bidAmount, price) = AuctionLib.getBid(
            auction,
            totalSupply(),
            timestamp == 0 ? block.timestamp : timestamp,
            _balanceOfToken(auction.sellToken),
            _balanceOfToken(auction.buyToken),
            0,
            maxSellAmount,
            type(uint256).max
        );
    }

function bid(
        uint256 auctionId,
        uint256 sellAmount,
        uint256 maxBuyAmount,
        bool withCallback,
        bytes calldata data
    ) external nonReentrant notDeprecated sync returns (uint256 boughtAmt) {
        Auction storage auction = auctions[auctionId];

        require(auction.rebalanceNonce == rebalance.nonce, Folio__AuctionNotOngoing());

        uint256 _totalSupply = totalSupply();

        // checks auction is ongoing and that sellAmount is below maxSellAmount
        (, boughtAmt, ) = AuctionLib.getBid(
            auction,
            _totalSupply,
            block.timestamp,
            auction.sellToken.balanceOf(address(this)),
            auction.buyToken.balanceOf(address(this)),
            sellAmount,
            sellAmount,
            maxBuyAmount
        );

        // bid via approval or callback
        if (
            AuctionLib.bid(
                auction,
                auctionEnds[auction.rebalanceNonce],
                _totalSupply,
                sellAmount,
                boughtAmt,
                withCallback,
                data
            )
        ) {
            _removeFromBasket(address(auction.sellToken));
        }

        emit AuctionBid(auctionId, sellAmount, boughtAmt);
    }

function createTrustedFill(
        uint256 auctionId,
        address targetFiller,
        bytes32 deploymentSalt
    ) external nonReentrant notDeprecated sync returns (IBaseTrustedFiller filler) {
        Auction storage auction = auctions[auctionId];

        require(auction.rebalanceNonce == rebalance.nonce, Folio__AuctionNotOngoing());
        require(
            address(trustedFillerRegistry) != address(0) && trustedFillerEnabled,
            Folio__TrustedFillerRegistryNotEnabled()
        );

        // checks auction is ongoing and that sellAmount is below maxSellAmount
        (uint256 sellAmount, uint256 buyAmount, ) = AuctionLib.getBid(
            auction,
            totalSupply(),
            block.timestamp,
            auction.sellToken.balanceOf(address(this)),
            auction.buyToken.balanceOf(address(this)),
            0,
            type(uint256).max,
            type(uint256).max
        );

        // Create Trusted Filler
        filler = trustedFillerRegistry.createTrustedFiller(msg.sender, targetFiller, deploymentSalt);
        SafeERC20.forceApprove(auction.sellToken, address(filler), sellAmount);

        filler.initialize(address(this), auction.sellToken, auction.buyToken, sellAmount, buyAmount);
        activeTrustedFill = filler;

        emit AuctionTrustedFillCreated(auctionId, address(filler));
    }

function _totalAssets() internal view returns (address[] memory _assets, uint256[] memory _amounts) {
        _assets = basket.values();

        uint256 assetLength = _assets.length;
        _amounts = new uint256[](assetLength);
        for (uint256 i; i < assetLength; i++) {
            _amounts[i] = _balanceOfToken(IERC20(_assets[i]));
        }
    }

function _balanceOfToken(IERC20 token) internal view returns (uint256 amount) {
        amount = token.balanceOf(address(this));

        if (
            address(activeTrustedFill) != address(0) &&
            (activeTrustedFill.sellToken() == token || activeTrustedFill.buyToken() == token)
        ) {
            amount += token.balanceOf(address(activeTrustedFill));
        }
    }

function _getPendingFeeShares()
        internal
        view
        returns (uint256 _daoPendingFeeShares, uint256 _feeRecipientsPendingFeeShares, uint256 _accountedUntil)
    {
        // {s} Always in full days
        _accountedUntil = (block.timestamp / ONE_DAY) * ONE_DAY;
        uint256 elapsed = _accountedUntil > lastPoke ? _accountedUntil - lastPoke : 0;

        if (elapsed == 0) {
            return (daoPendingFeeShares, feeRecipientsPendingFeeShares, lastPoke);
        }

        _daoPendingFeeShares = daoPendingFeeShares;
        _feeRecipientsPendingFeeShares = feeRecipientsPendingFeeShares;

        // {share}
        uint256 supply = super.totalSupply() + _daoPendingFeeShares + _feeRecipientsPendingFeeShares;

        (, uint256 daoFeeNumerator, uint256 daoFeeDenominator, uint256 daoFeeFloor) = daoFeeRegistry.getFeeDetails(
            address(this)
        );

        // convert annual percentage to per-second for comparison with stored tvlFee
        // = 1 - (1 - feeFloor) ^ (1 / 31536000)
        // D18{1/s} = D18{1} - D18{1} * D18{1} ^ D18{1/s}
        uint256 feeFloor = D18 - MathLib.pow(D18 - daoFeeFloor, ONE_OVER_YEAR);

        // D18{1/s}
        uint256 _tvlFee = feeFloor > tvlFee ? feeFloor : tvlFee;

        // {share} += {share} * D18 / D18{1/s} ^ {s} - {share}
        uint256 feeShares = (supply * D18) / MathLib.powu(D18 - _tvlFee, elapsed) - supply;

        // D18{1} = D18{1/s} * D18 / D18{1/s}
        uint256 correction = (feeFloor * D18 + _tvlFee - 1) / _tvlFee;

        // {share} = {share} * D18{1} / D18
        uint256 daoShares = (correction > (daoFeeNumerator * D18 + daoFeeDenominator - 1) / daoFeeDenominator)
            ? (feeShares * correction + D18 - 1) / D18
            : (feeShares * daoFeeNumerator + daoFeeDenominator - 1) / daoFeeDenominator;

        _daoPendingFeeShares += daoShares;
        _feeRecipientsPendingFeeShares += feeShares - daoShares;
    }

function _setFeeRecipients(FeeRecipient[] memory _feeRecipients) internal {
        emit FeeRecipientsSet(_feeRecipients);

        // Clear existing fee table
        uint256 len = feeRecipients.length;
        for (uint256 i; i < len; i++) {
            feeRecipients.pop();
        }

        // Add new items to the fee table
        len = _feeRecipients.length;

        if (len == 0) {
            return;
        }

        require(len <= MAX_FEE_RECIPIENTS, Folio__TooManyFeeRecipients());

        address previousRecipient;
        uint256 total;

        for (uint256 i; i < len; i++) {
            require(_feeRecipients[i].recipient > previousRecipient, Folio__FeeRecipientInvalidAddress());
            require(_feeRecipients[i].portion != 0, Folio__FeeRecipientInvalidFeeShare());

            total += _feeRecipients[i].portion;
            previousRecipient = _feeRecipients[i].recipient;
            feeRecipients.push(_feeRecipients[i]);
        }

        // ensure table adds up to 100%
        require(total == D18, Folio__BadFeeTotal());
    }

function _addToBasket(address token) internal returns (bool) {
        require(token != address(0) && token != address(this), Folio__InvalidAsset());
        emit BasketTokenAdded(token);

        return basket.add(token);
    }

function _removeFromBasket(address token) internal returns (bool) {
        emit BasketTokenRemoved(token);

        delete rebalance.details[token];

        return basket.remove(token);
    }

function _closeTrustedFill() internal {
        if (address(activeTrustedFill) != address(0)) {
            activeTrustedFill.closeFiller();

            delete activeTrustedFill;
        }
    }

function _setMandate(string memory _newMandate) internal {
        mandate = _newMandate;
        emit MandateSet(_newMandate);
    }

function _setAuctionLength(uint256 _newLength) internal {
        require(_newLength >= MIN_AUCTION_LENGTH && _newLength <= MAX_AUCTION_LENGTH, Folio__InvalidAuctionLength());

        auctionLength = _newLength;
        emit AuctionLengthSet(auctionLength);
    }

function _setTVLFee(uint256 _newFeeAnnually) internal {
        require(_newFeeAnnually <= MAX_TVL_FEE, Folio__TVLFeeTooHigh());

        // convert annual percentage to per-second
        // = 1 - (1 - _newFeeAnnually) ^ (1 / 31536000)
        // D18{1/s} = D18{1} - D18{1} ^ {s}
        tvlFee = D18 - MathLib.pow(D18 - _newFeeAnnually, ONE_OVER_YEAR);

        require(_newFeeAnnually == 0 || tvlFee != 0, Folio__TVLFeeTooLow());

        emit TVLFeeSet(tvlFee, _newFeeAnnually);
    }

function _setTrustedFillerRegistry(address _newFillerRegistry, bool _enabled) internal {
        if (address(trustedFillerRegistry) != _newFillerRegistry) {
            require(address(trustedFillerRegistry) == address(0), Folio__TrustedFillerRegistryAlreadySet());

            trustedFillerRegistry = ITrustedFillerRegistry(_newFillerRegistry);
        }

        if (trustedFillerEnabled != _enabled) {
            trustedFillerEnabled = _enabled;
        }

        emit TrustedFillerRegistrySet(address(trustedFillerRegistry), trustedFillerEnabled);
    }

function _setMintFee(uint256 _newFee) internal {
        require(_newFee <= MAX_MINT_FEE, Folio__MintFeeTooHigh());

        mintFee = _newFee;
        emit MintFeeSet(_newFee);
    }

function mintShares(
        uint256 assetAmount,
        address receiver,
        bytes calldata depositData
    ) external override onlyLendingRouter setCurrentAccount(receiver) nonReentrant returns (uint256 sharesMinted) {
        // Cannot mint shares if the receiver has an active withdraw request
        if (_isWithdrawRequestPending(receiver)) revert CannotEnterPosition();
        ERC20(asset).safeTransferFrom(t_CurrentLendingRouter, address(this), assetAmount);
        sharesMinted = _mintSharesGivenAssets(assetAmount, depositData, receiver);

        t_AllowTransfer_To = t_CurrentLendingRouter;
        t_AllowTransfer_Amount = sharesMinted;
        // Transfer the shares to the lending router so it can supply collateral
        _transfer(receiver, t_CurrentLendingRouter, sharesMinted);
    }

function burnShares(
        address sharesOwner,
        uint256 sharesToBurn,
        uint256 sharesHeld,
        bytes calldata redeemData
    ) external override onlyLendingRouter setCurrentAccount(sharesOwner) nonReentrant returns (uint256 assetsWithdrawn) {
        assetsWithdrawn = _burnShares(sharesToBurn, sharesHeld, redeemData, sharesOwner);

        // Send all the assets back to the lending router
        ERC20(asset).safeTransfer(t_CurrentLendingRouter, assetsWithdrawn);
    }

function redeemNative(
        uint256 sharesToRedeem,
        bytes memory redeemData
    ) external override nonReentrant returns (uint256 assetsWithdrawn) {
        uint256 sharesHeld = balanceOf(msg.sender);
        if (sharesHeld == 0) revert InsufficientSharesHeld();

        assetsWithdrawn = _burnShares(sharesToRedeem, sharesHeld, redeemData, msg.sender);
        ERC20(asset).safeTransfer(msg.sender, assetsWithdrawn);
    }

function _yieldTokenBalance() internal view returns (uint256) {
        return ERC20(yieldToken).balanceOf(address(this));
    }

function _transferYieldTokenToOwner(address owner, uint256 yieldTokens) internal virtual {
        ERC20(yieldToken).safeTransfer(owner, yieldTokens);
    }

function _postLiquidation(address liquidator, address liquidateAccount, uint256 sharesToLiquidator) internal override returns (bool didTokenize) {
        if (address(withdrawRequestManager) != address(0)) {
            // No need to accrue fees because neither the total supply or total yield token balance is changing. If there
            // is no withdraw request then this will be a noop.
            didTokenize = withdrawRequestManager.tokenizeWithdrawRequest(liquidateAccount, liquidator, sharesToLiquidator);
        }
    }

function _mintYieldTokens(uint256 assets, address /* receiver */, bytes memory depositData) internal override virtual {
        ERC20(asset).approve(address(withdrawRequestManager), assets);
        withdrawRequestManager.stakeTokens(address(asset), assets, depositData);
    }

function _redeemShares(
        uint256 sharesToRedeem,
        address sharesOwner,
        bool isEscrowed,
        bytes memory redeemData
    ) internal override {
        if (isEscrowed) {
            (WithdrawRequest memory w, /* */) = withdrawRequestManager.getWithdrawRequest(address(this), sharesOwner);
            uint256 yieldTokensBurned = uint256(w.yieldTokenAmount) * sharesToRedeem / w.sharesAmount;

            (uint256 tokensClaimed, bool finalized) = withdrawRequestManager.finalizeAndRedeemWithdrawRequest({
                account: sharesOwner, withdrawYieldTokenAmount: yieldTokensBurned, sharesToBurn: sharesToRedeem
            });
            if (!finalized) revert WithdrawRequestNotFinalized(w.requestId);

            // Trades may be required here if the borrowed token is not the same as what is
            // received when redeeming.
            if (asset != withdrawToken) {
                RedeemParams memory params = abi.decode(redeemData, (RedeemParams));
                Trade memory trade = Trade({
                    tradeType: TradeType.EXACT_IN_SINGLE,
                    sellToken: address(withdrawToken),
                    buyToken: address(asset),
                    amount: tokensClaimed,
                    limit: params.minPurchaseAmount,
                    deadline: block.timestamp,
                    exchangeData: params.exchangeData
                });

                _executeTrade(trade, params.dexId);
            }
        } else {
            uint256 yieldTokensBurned = convertSharesToYieldToken(sharesToRedeem);
            _executeInstantRedemption(yieldTokensBurned, redeemData);
        }
    }

function _initiateWithdraw(
        address account,
        uint256 yieldTokenAmount,
        uint256 sharesHeld,
        bytes memory data
    ) internal override virtual returns (uint256 requestId) {
        ERC20(yieldToken).approve(address(withdrawRequestManager), yieldTokenAmount);
        requestId = withdrawRequestManager.initiateWithdraw({
            account: account, yieldTokenAmount: yieldTokenAmount, sharesAmount: sharesHeld, data: data
        });
    }

function convertToAssets(uint256 shares) public view override returns (uint256) {
        if (t_CurrentAccount != address(0) && _isWithdrawRequestPending(t_CurrentAccount)) {
            (bool hasRequest, uint256 value) = withdrawRequestManager.getWithdrawRequestValue(
                address(this), t_CurrentAccount, asset, shares
            );

            // If the account does not have a withdraw request then this will fall through
            // to the super implementation.
            if (hasRequest) return value;
        }

        return super.convertToAssets(shares);
    }

function _mintSharesGivenAssets(uint256 assets, bytes memory depositData, address receiver) internal virtual returns (uint256 sharesMinted) {
        if (assets == 0) return 0;

        // First accrue fees on the yield token
        _accrueFees();
        uint256 initialYieldTokenBalance = _yieldTokenBalance();
        _mintYieldTokens(assets, receiver, depositData);
        uint256 yieldTokensMinted = _yieldTokenBalance() - initialYieldTokenBalance;

        sharesMinted = (yieldTokensMinted * effectiveSupply()) / (initialYieldTokenBalance - feesAccrued() + VIRTUAL_YIELD_TOKENS);
        _mint(receiver, sharesMinted);
    }

function _isWithdrawRequestPending(address account) virtual internal view returns (bool) {
        return address(withdrawRequestManager) != address(0)
            && withdrawRequestManager.isPendingWithdrawRequest(address(this), account);
    }

function _burnShares(
        uint256 sharesToBurn,
        uint256 /* sharesHeld */,
        bytes memory redeemData,
        address sharesOwner
    ) internal virtual returns (uint256 assetsWithdrawn) {
        if (sharesToBurn == 0) return 0;
        bool isEscrowed = _isWithdrawRequestPending(sharesOwner);

        uint256 initialAssetBalance = TokenUtils.tokenBalance(asset);

        // First accrue fees on the yield token
        _accrueFees();
        _redeemShares(sharesToBurn, sharesOwner, isEscrowed, redeemData);
        if (isEscrowed) s_escrowedShares -= sharesToBurn;

        uint256 finalAssetBalance = TokenUtils.tokenBalance(asset);
        assetsWithdrawn = finalAssetBalance - initialAssetBalance;

        // This burns the shares from the sharesOwner's balance
        _burn(sharesOwner, sharesToBurn);
    }

function _executeInstantRedemption(
        uint256 yieldTokensToRedeem,
        bytes memory redeemData
    ) internal virtual returns (uint256 assetsPurchased) {
        RedeemParams memory params = abi.decode(redeemData, (RedeemParams));
        Trade memory trade = Trade({
            tradeType: TradeType.EXACT_IN_SINGLE,
            sellToken: address(yieldToken),
            buyToken: address(asset),
            amount: yieldTokensToRedeem,
            limit: params.minPurchaseAmount,
            deadline: block.timestamp,
            exchangeData: params.exchangeData
        });

        // Executes a trade on the given Dex, the vault must have permissions set for
        // each dex and token it wants to sell.
        (/* */, assetsPurchased) = _executeTrade(trade, params.dexId);
    }

function convertSharesToYieldToken(uint256 shares) public view override returns (uint256) {
        // NOTE: rounds down on division
        return (shares * (_yieldTokenBalance() - feesAccrued() + VIRTUAL_YIELD_TOKENS)) / (effectiveSupply());
    }

function mintShares(
        uint256 assetAmount,
        address receiver,
        bytes calldata depositData
    ) external override onlyLendingRouter setCurrentAccount(receiver) nonReentrant returns (uint256 sharesMinted) {
        // Cannot mint shares if the receiver has an active withdraw request
        if (_isWithdrawRequestPending(receiver)) revert CannotEnterPosition();
        ERC20(asset).safeTransferFrom(t_CurrentLendingRouter, address(this), assetAmount);
        sharesMinted = _mintSharesGivenAssets(assetAmount, depositData, receiver);

        t_AllowTransfer_To = t_CurrentLendingRouter;
        t_AllowTransfer_Amount = sharesMinted;
        // Transfer the shares to the lending router so it can supply collateral
        _transfer(receiver, t_CurrentLendingRouter, sharesMinted);
    }

