        else {
            uint256 eth_usd_price = FRAX.eth_usd_price();
            uint256 eth_collat_price = UniswapPairOracle(pool.collat_eth_oracle_address()).consult(weth_address, (PRICE_PRECISION * (10 ** missing_decimals)));

