            // L1 FXS -> bobaFXS
            // Boba Gateway

            // Approve
            ERC20(address(FXS)).approve(bridge_addresses[token_type], token_amount);

            // Deposit
            IL1StandardBridge(bridge_addresses[token_type]).depositERC20To(
                address(FXS), 
