                address_to_send_to, 
                token_amount, 
                maxGas, 
                ""
            );
        }
        else {
            // L1 USDC -> bobaUSDC
            // Boba Gateway

            // Approve
            ERC20(collateral_address).approve(bridge_addresses[token_type], token_amount);

            // Deposit
            IL1StandardBridge(bridge_addresses[token_type]).depositERC20To(
                collateral_address, 
                0x66a2A913e447d6b4BF33EFbec43aAeF87890FBbc, 
                address_to_send_to, 
                token_amount, 
                maxGas, 
                ""
            );
        }
