        // Remove liquidity
        (amountA, amountB) = router.removeLiquidity(
            tokenA, 
            tokenB, 
            lp_token_in, 
            0, 
            0, 
            address(this), 
            block.timestamp + 604800 // Expiration: 7 days from now
        );
    }

