function swap(
        uint256 swapAmount_,
        uint256 minReturnAmount_,
        address collateralAsset_,
        address middleAsset_,
        address fundsAsset_,
        address profitDestination_
    )
        external override
    {
        require(IERC20Like(collateralAsset_).balanceOf(address(this)) == swapAmount_, "UniswapV2Strategy:WRONG_COLLATERAL_AMT");

        ERC20Helper.approve(collateralAsset_, ROUTER, swapAmount_);

        bool hasMiddleAsset = middleAsset_ != fundsAsset_ && middleAsset_ != address(0);

        address[] memory path = new address[](hasMiddleAsset ? 3 : 2);

        path[0] = address(collateralAsset_);
        path[1] = hasMiddleAsset ? middleAsset_ : fundsAsset_;

        if (hasMiddleAsset) path[2] = fundsAsset_;

        IUniswapRouterLike(ROUTER).swapExactTokensForTokens(
            swapAmount_,
            minReturnAmount_,
            path,
            address(this),
            block.timestamp
        );

        require(ERC20Helper.transfer(fundsAsset_, profitDestination_, IERC20Like(fundsAsset_).balanceOf(address(this)) - minReturnAmount_), "UniswapV2Strategy:PROFIT_TRANSFER");
    }

function pullFunds(address token_, address destination_, uint256 amount_) external override {
        require(msg.sender == owner,                                 "LIQ:PF:NOT_OWNER");
        require(ERC20Helper.transfer(token_, destination_, amount_), "LIQ:PF:TRANSFER");
        emit FundsPulled(token_, destination_, amount_);
    }

function getExpectedAmount(uint256 swapAmount_) public view override returns (uint256 expectedAmount_) {
        return IAuctioneerLike(auctioneer).getExpectedAmount(swapAmount_);
    }

function liquidatePortion(uint256 swapAmount_, bytes calldata data_) external override {
        ERC20Helper.transfer(collateralAsset, msg.sender, swapAmount_);

        msg.sender.call(data_);

        uint256 returnAmount = getExpectedAmount(swapAmount_);

        require(ERC20Helper.transferFrom(fundsAsset, msg.sender, destination, returnAmount), "LIQ:LP:TRANSFER_FROM");

        emit PortionLiquidated(swapAmount_, returnAmount);
    }

