function _plantOrRecallExcessFunds() internal {
        // check if the transmuter holds more funds than plantableThreshold
        uint256 bal = IERC20Burnable(Token).balanceOf(address(this));
        uint256 marginVal = plantableThreshold.mul(plantableMargin).div(100);
        if (bal > plantableThreshold.add(marginVal)) {
            uint256 plantAmt = bal - plantableThreshold;
            // if total funds above threshold, send funds to vault
            VaultWithIndirection.Data storage _activeVault = _vaults.last();
            _activeVault.deposit(plantAmt);
        } else if (bal < plantableThreshold.sub(marginVal)) {
            // if total funds below threshold, recall funds from vault
            // first check that there are enough funds in vault
            uint256 harvestAmt = plantableThreshold - bal;
            _recallExcessFundsFromActiveVault(harvestAmt);
        }
    }

function _recallExcessFundsFromActiveVault(uint256 _recallAmt) internal {
        VaultWithIndirection.Data storage _activeVault = _vaults.last();
        uint256 activeVaultVal = _activeVault.totalValue();
        if (activeVaultVal < _recallAmt) {
            _recallAmt = activeVaultVal;
        }
        if (_recallAmt > 0) {
            _recallFundsFromActiveVault(_recallAmt);
        }
    }

function harvest(uint256 _vaultId) external onlyKeeper() returns (uint256, uint256) {

        VaultWithIndirection.Data storage _vault = _vaults.get(_vaultId);

        (uint256 _harvestedAmount, uint256 _decreasedValue) = _vault.harvest(rewards);

        emit FundsHarvested(_harvestedAmount, _decreasedValue);

        return (_harvestedAmount, _decreasedValue);
    }

function migrateFunds(address migrateTo) external onlyGov() {
        require(migrateTo != address(0), "cannot migrate to 0x0");
        require(pause, "migrate: set emergency exit first");

        // leave enough funds to service any pending transmutations
        uint256 totalFunds = IERC20Burnable(Token).balanceOf(address(this));
        uint256 migratableFunds = totalFunds.sub(totalSupplyScTokens, "not enough funds to service stakes");
        IERC20Burnable(Token).approve(migrateTo, migratableFunds);
        ITransmuter(migrateTo).distribute(address(this), migratableFunds);
        emit MigrationComplete(migrateTo, migratableFunds);
    }

function increaseAllocations(uint256 amount) internal {
        if(totalSupplyScTokens > 0 && amount > 0) {
            totalDividendPoints = totalDividendPoints.add(
                amount.mul(pointMultiplier).div(totalSupplyScTokens)
            );
            unclaimedDividends = unclaimedDividends.add(amount);
        } else {
            buffer = buffer.add(amount);
        }
    }

function deposit(uint256 _wantAmt)
        external
        override
        onlyVault
        nonReentrantAndUnpaused
    {
        IERC20(wantToken).safeTransferFrom(
            address(msg.sender),
            address(this),
            _wantAmt
        );

        alpacaVault.deposit(_wantAmt);
        fairLaunch.deposit(address(this), poolId, alpacaVault.balanceOf(address(this)));
    }

function withdraw(uint256 _wantAmt)
        external
        override
        onlyVault
        nonReentrantAndUnpaused
    {
        uint256 ibAmt = wantAmtToIbAmount(_wantAmt);
        fairLaunch.withdraw(address(this), poolId, ibAmt);
        alpacaVault.withdraw(alpacaVault.balanceOf(address(this)));

        uint256 actualWantAmount = wantToken.balanceOf(address(this));
        wantToken.safeTransfer(
            address(msg.sender),
            actualWantAmount
        );
    }

function totalBalance() external override view returns (uint256) {
        uint256 ibBal = _ibDeposited();
        return alpacaVaultTotalToken().mul(ibBal).div(alpacaVault.totalSupply());
    }

function initialize(
        uint256 _poolId,
        address _fairLaunchAddress,
        address _alpacaToken,
        address _alpacaVault,
        address _wantAddress,
        address _wbnbAddress,
        address _uniRouterAddress,
        address _vault
    )
        external
        initializer
        onlyOwner
    {
        poolId = _poolId;
        fairLaunch = IFairLaunch(_fairLaunchAddress);
        alpacaToken = IERC20(_alpacaToken);
        alpacaVault = IAlpacaVault(_alpacaVault);

        wantToken = IERC20(_wantAddress);
        wbnbAddress = _wbnbAddress;

        if (_wantAddress == wbnbAddress) {
            wantIsWBNB = true;
            alpacaToWantPath = [_alpacaToken, wbnbAddress];
        } else {
            alpacaToWantPath = [_alpacaToken, wbnbAddress, _wantAddress];
        }

        uniRouterAddress = _uniRouterAddress;

        wantToken.safeApprove(_alpacaVault, uint256(-1));
        alpacaVault.safeApprove(_fairLaunchAddress, uint256(-1));
        alpacaToken.safeApprove(uniRouterAddress, uint256(-1));
        vault = _vault;
    }

function alpacaVaultTotalToken() public view returns (uint256) {
        uint256 reservePool = alpacaVault.reservePool();
        uint256 vaultDebtVal = alpacaVault.vaultDebtVal();
        if (now > alpacaVault.lastAccrueTime()) {
            uint256 interest = alpacaVault.pendingInterest(0);
            uint256 toReserve = interest.mul(IVaultConfig(alpacaVault.config()).getReservePoolBps()).div(10000);
            reservePool = reservePool.add(toReserve);
            vaultDebtVal = vaultDebtVal.add(interest);
        }
        return wantToken.balanceOf(address(alpacaVault)).add(vaultDebtVal).sub(reservePool);
    }

function _ibDeposited() internal view returns (uint256) {
        (uint256 ibBal,,,) = fairLaunch.userInfo(poolId, address(this));
        return ibBal;
    }

function wantAmtToIbAmount(uint256 _wantAmt) public view returns (uint256) {
        return _wantAmt.mul(alpacaVault.totalSupply()).div(alpacaVaultTotalToken());
    }

function _harvest(uint256 priceMin) internal {
        if (lastHarvestBlock == block.number) {
            return;
        }

        // Do not harvest if no token is deposited (otherwise, fairLaunch will fail)
        if (_ibDeposited() == 0) {
            return;
        }

        // Collect alpacaToken
        fairLaunch.harvest(poolId);

        uint256 earnedAlpacaBalance = alpacaToken.balanceOf(address(this));
        if (earnedAlpacaBalance == 0) {
            return;
        }

        if (alpacaToken != wantToken) {
            IPancakeRouter02(uniRouterAddress).swapExactTokensForTokens(
                earnedAlpacaBalance,
                earnedAlpacaBalance.mul(priceMin).div(1e18),
                alpacaToWantPath,
                address(this),
                now.add(600)
            );
        }

        alpacaVault.deposit(IERC20(wantToken).balanceOf(address(this)));
        fairLaunch.deposit(address(this), poolId, alpacaVault.balanceOf(address(this)));

        lastHarvestBlock = block.number;
    }

