function updateAndQuery()
        external
        override
        returns (bool updated, uint256 value)
    {
        uint256 timeElapsed = block.timestamp - lastUpdateTimestamp;
        if (timeElapsed < UPDATE_INTERVAL) {
            return (false, emaStored);
        }

        // save gas by loading storage variables to memory
        uint256 _lastIncomeIndex = lastIncomeIndex;
        uint256 _emaStored = emaStored;

        uint256 newIncomeIndex = moneyMarket.incomeIndex();
        if (newIncomeIndex < _lastIncomeIndex) {
            // Shouldn't revert (which would block execution)
            // Assume no interest was accrued and use the last index as the new one
            // which would push the EMA towards zero if there's e.g. an exploit
            // in the underlying yield protocol
            newIncomeIndex = _lastIncomeIndex;
        }
        uint256 incomingValue =
            (newIncomeIndex - _lastIncomeIndex).decdiv(_lastIncomeIndex) /
                timeElapsed;

        updated = true;
        value =
            (incomingValue *
                UPDATE_MULTIPLIER +
                _emaStored *
                ONE_MINUS_UPDATE_MULTIPLIER) /
            PRECISION;
        emaStored = value;
        lastIncomeIndex = newIncomeIndex;
        lastUpdateTimestamp = block.timestamp;
    }

function initialize(
        uint256 _emaInitial,
        uint256 _updateInterval,
        uint256 _smoothingFactor,
        uint256 _averageWindowInIntervals,
        address _moneyMarket
    ) external initializer {
        emaStored = _emaInitial;
        UPDATE_INTERVAL = _updateInterval;
        lastUpdateTimestamp = block.timestamp;

        uint256 updateMultiplier =
            _smoothingFactor / (_averageWindowInIntervals + 1);
        UPDATE_MULTIPLIER = updateMultiplier;
        ONE_MINUS_UPDATE_MULTIPLIER = PRECISION - updateMultiplier;

        moneyMarket = MoneyMarket(_moneyMarket);
        lastIncomeIndex = moneyMarket.incomeIndex();
    }

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns (bytes memory) {
        require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");

        bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
        require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
        require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
        require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");

        queuedTransactions[txHash] = false;

        bytes memory callData;

        if (bytes(signature).length == 0) {
            callData = data;
        } else {
            callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
        }

        // solium-disable-next-line security/no-call-value
        (bool success, bytes memory returnData) = target.call{value: value}(callData);
        require(success, "Timelock::executeTransaction: Transaction execution reverted.");

        emit ExecuteTransaction(txHash, target, value, signature, data, eta);

        return returnData;
    }

function sellInternal(address sellToken, address forToken, uint256 amount) internal returns (uint256) {
        PathItem memory item = pathes[sellToken][forToken];
        if (!(item.pair.length > 0 && item.path.length == item.pair.length + 1)) { //path illegal
            return 0;
        }
        uint256[] memory amounts = getAmountsOut(amount, item);
        for (uint256 i = 0; i < item.pair.length; i++) {
            (address input, address output) = (item.path[i], item.path[i + 1]);
            (address token0, ) = BabyLibrary.sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address to = i < item.path.length - 2 ? item.pair[i + 1] : address(this);
            IBabyPair(item.pair[i]).swap(amount0Out, amount1Out, to, new bytes(0));
        }
        return amounts[amounts.length - 1];
    }

function sell(address[] memory sellTokens, address forToken, uint256[] memory amounts) external {
        uint totalReceived = 0;
        for (uint i = 0; i < sellTokens.length; i ++) {
            uint received = sellInternal(sellTokens[i], forToken, amounts[i]);

            tokenInfos[sellTokens[i]].sended = tokenInfos[sellTokens[i]].sended.add(amounts[i]);
            tokenInfos[sellTokens[i]].lastPrice = received.mul(10 ** 18).div(amounts[i]);
            tokenInfos[sellTokens[i]].count += 1;

            totalReceived = totalReceived.add(received);
        }
        tokenInfos[forToken].received += totalReceived;
    }

function createIDO(
        IBEP20 idoToken,
        IBEP20 receiveToken,
        uint256 price,
        uint256 idoTotal,
        uint256 maxLimit,
        uint256 startTime,
        uint256 duration
    ) external onlyOwner {
        require(
            block.timestamp >
                IDODB[IDOIssue].startTime.add(IDODB[IDOIssue].duration),
            "ido is not over yet."
        );
        require(
            address(idoToken) != address(0),
            "idoToken address cannot be 0"
        );
        require(
            address(receiveToken) != address(0),
            "receiveToken address cannot be 0"
        );

        IDOIssue = IDOIssue.add(1);
        IDORecord storage ido = IDODB[IDOIssue];
        ido.issue = IDOIssue;
        ido.idoToken = idoToken;
        ido.receiveToken = receiveToken;
        ido.price = price;
        ido.maxLimit = maxLimit;
        ido.idoTotal = idoTotal;
        ido.startTime = startTime;
        ido.duration = duration;

        idoToken.safeTransferFrom(msg.sender, address(this), idoTotal);
        emit IDOCreate(
            IDOIssue,
            address(idoToken),
            address(receiveToken),
            price,
            maxLimit,
            idoTotal,
            startTime,
            duration
        );
    }

function removeIDO() external onlyOwner {
        require(
            IDODB[IDOIssue].startTime > block.timestamp,
            "There is no ido that can be deleted."
        );
        IDODB[IDOIssue].idoToken.safeTransfer(
            msg.sender,
            IDODB[IDOIssue].idoTotal
        );
        delete IDODB[IDOIssue];
        emit IDORemove(IDOIssue);
        IDOIssue = IDOIssue.sub(1);
    }

function chargeIDO(uint256 issue) external onlyOwner {
        IDORecord storage record = IDODB[issue];
        require(issue <= IDOIssue && issue > 0, "IDO that does not exist.");
        require(!isCharge[issue], "Cannot claim repeatedly.");
        require(
            block.timestamp > record.startTime.add(record.duration),
            "ido is not over yet."
        );

        uint256 receiveValue;
        uint256 backValue;

        isCharge[issue] = true;

        uint256 prop = record.receivedTotal.mul(1e36).div(
            record.idoTotal.mul(record.price)
        );
        if (prop >= 1e18) {
            receiveValue = record.idoTotal.mul(record.price).div(1e18);
            record.receiveToken.safeTransfer(msg.sender, receiveValue);
        } else {
            receiveValue = record.receivedTotal;
            record.receiveToken.safeTransfer(msg.sender, record.receivedTotal);
            backValue = record.idoTotal.sub(
                record.idoTotal.mul(prop).div(1e18)
            );
            record.idoToken.safeTransfer(msg.sender, backValue);
        }

        emit IDOCharge(issue, receiveValue, backValue);
    }

function stake(uint256 value) external {
        require(IDOIssue > 0, "IDO that does not exist.");
        IDORecord storage record = IDODB[IDOIssue];
        require(
            block.timestamp > record.startTime &&
                block.timestamp < record.startTime.add(record.duration),
            "IDO is not in progress."
        );
        require(
            record.payAmount[msg.sender].add(value) <= record.maxLimit,
            "Limit Exceeded"
        );

        record.payAmount[msg.sender] = record.payAmount[msg.sender].add(value);
        record.receivedTotal = record.receivedTotal.add(value);
        record.receiveToken.safeTransferFrom(msg.sender, address(this), value);
        emit Staked(IDOIssue, msg.sender, value);
    }

function available(address account, uint256 issue)
        public
        view
        returns (uint256 _idoAmount, uint256 _sendBack)
    {
        IDORecord storage record = IDODB[issue];
        require(issue <= IDOIssue && issue > 0, "IDO that does not exist.");

        uint256 prop = record.receivedTotal.mul(1e36).div(
            record.idoTotal.mul(record.price)
        );

        if (prop > 1e18) {
            _idoAmount = record.payAmount[account].mul(1e36).div(prop).div(
                record.price
            );

            _sendBack = record.payAmount[account].sub(
                _idoAmount.mul(record.price).div(1e18)
            );
        } else {
            _idoAmount = record.payAmount[account].mul(1e18).div(record.price);
        }
    }

function withdraw(uint256 issue) external {
        require(issue <= IDOIssue && issue > 0, "IDO that does not exist.");
        IDORecord storage record = IDODB[issue];
        require(
            block.timestamp > IDODB[issue].startTime.add(record.duration),
            "ido is not over yet."
        );
        require(!record.isWithdraw[msg.sender], "Cannot claim repeatedly.");

        uint256 idoAmount;
        uint256 sendBack;

        record.isWithdraw[msg.sender] = true;

        (idoAmount, sendBack) = available(msg.sender, issue);

        record.idoToken.safeTransfer(msg.sender, idoAmount);
        if (sendBack > 0) {
            record.receiveToken.safeTransfer(msg.sender, sendBack);
        }

        emit Withdraw(issue, msg.sender, idoAmount, sendBack);
    }

