function createSale(uint256 _editionId, uint128 _startTime, uint128 _endTime, uint16 _mintLimit, uint128 _priceInWei)
    public
    whenNotPaused
    onlyCreatorContractOrAdmin(_editionId)
    {
        uint256 editionSize = koda.getSizeOfEdition(_editionId);
        require(editionSize > 0, 'edition does not exist');
        require(_endTime > _startTime, 'sale end time must be after start time');
        require(_mintLimit > 0 && _mintLimit < editionSize, 'mint limit must be greater than 0 and smaller than edition size');

        uint256 saleId = saleIdCounter += 1;

        // Assign the sale to the sales and editionToSale mappings
        sales[saleId] = Sale({
        id : saleId,
        creator : koda.getCreatorOfEdition(_editionId),
        editionId : _editionId,
        startTime : _startTime,
        endTime : _endTime,
        mintLimit : _mintLimit,
        priceInWei : _priceInWei,
        paused : false
        });
        editionToSale[_editionId] = saleId;

        emit SaleCreated(saleId, _editionId);
    }

function _handleMint(uint256 _saleId, uint256 _editionId, uint16 _mintCount) internal {
        address _receiver;

        for (uint i = 0; i < _mintCount; i++) {
            (address receiver, address creator, uint256 tokenId) = koda.facilitateNextPrimarySale(_editionId);
            _receiver = receiver;

            // send token to buyer (assumes approval has been made, if not then this will fail)
            koda.safeTransferFrom(creator, _msgSender(), tokenId);
        }

        _handleEditionSaleFunds(_saleId, _editionId, _receiver);
    }

function canMint(uint256 _saleId, uint256 _tokenId, address _account, address _creator) public view returns (bool) {
        require(sales[_saleId].creator == _creator, 'sale id does not match creator address');

        if (koda.ownerOf(_tokenId) != _account) {
            return false;
        }

        if (koda.getCreatorOfToken(_tokenId) != _creator) {
            return false;
        }

        return true;
    }

function _handleEditionSaleFunds(uint256 _saleId, uint256 _editionId, address _receiver) internal {
        uint256 platformPrimarySaleCommission = saleCommission[_saleId] > 0 ? saleCommission[_saleId] : 15_00000;
        uint256 koCommission = (msg.value / modulo) * platformPrimarySaleCommission;
        if (koCommission > 0) {
            (bool koCommissionSuccess,) = platformAccount.call{value : koCommission}("");
            require(koCommissionSuccess, "commission payment failed");
        }

        (bool success,) = _receiver.call{value : msg.value - koCommission}("");
        require(success, "payment failed");
    }

function facilitateNextPrimarySale(address _from, uint256 _editionId, address _paymentToken, uint256 _paymentAmount, address _buyer) internal returns (uint256) {
        // get next token to sell along with the royalties recipient and the original creator
        (address receiver, address creator, uint256 tokenId) = koda.facilitateNextPrimarySale(_editionId);

        // split money
        handleEditionSaleFunds(receiver, _paymentToken, _paymentAmount);

        // send token to buyer (assumes approval has been made, if not then this will fail)
        koda.safeTransferFrom(_from, _buyer, tokenId);

        // FIXME we could in theory remove this
        //      - and use the current approach of KO where a bidder must pull back any funds once its sold out on primary
        //      - would probs shave a good bit of GAS (profile the options)
        //      - could be replaced with a open method when in that state, monies are returned to bidder (future proof building tools to cover this)

        //todo: sell out logic
        // if we are about to sellout - send any open offers back to the bidder
        //        if (tokenId == koda.maxTokenIdOfEdition(_editionId)) {
        //
        //            // send money back to top bidder if existing offer found
        //            Offer storage offer = editionOffers[_editionId];
        //            if (offer.offer > 0) {
        //                _refundBidder(offer.bidder, offer.offer);
        //            }
        //        }

        return tokenId;
    }

function handleEditionSaleFunds(address _receiver, address _paymentToken, uint256 _paymentAmount) internal {

        // TODO could we save gas here by maintaining a counter for KO platform funds and having a drain method?

        bool _isEthSale = _paymentToken == address(0);
        uint256 koCommission = (_paymentAmount / modulo) * platformPrimarySaleCommission;
        uint256 receiverCommission = _paymentAmount - koCommission;
        if (_isEthSale) {
            (bool koCommissionSuccess,) = platformAccount.call{value : koCommission}("");
            require(koCommissionSuccess, "Edition commission payment failed");

            (bool success,) = _receiver.call{value : receiverCommission}("");
            require(success, "Edition payment failed");
        } else {
            IERC20 paymentToken = IERC20(_paymentToken);
            paymentToken.transferFrom(_msgSender(), platformAccount, koCommission);
            paymentToken.transferFrom(_msgSender(), _receiver, receiverCommission);
        }
    }

