function parseData(
        bytes memory data
    )
        private
        pure
        returns (
            uint256,
            uint256
        )
    {
        Require.that(
            data.length == 64,
            FILE,
            "Call data invalid length"
        );

        uint256 aData;
        uint256 sData;

        /* solium-disable-next-line security/no-inline-assembly */
        assembly {
            aData := mload(add(data, 32))
            sData := mload(add(data, 64))
        }

        return (
            aData,
            sData
        );
    }

