function getTradeCost(
        uint256 inputMarketId,
        uint256 outputMarketId,
        Account.Info memory makerAccount,
        Account.Info memory /* takerAccount */,
        Types.Par memory oldInputPar,
        Types.Par memory newInputPar,
        Types.Wei memory inputWei,
        bytes memory /* data */
    )
        public
        // view
        onlySolo(msg.sender)
        returns (Types.AssetAmount memory)
    {
        // input validation
        Require.that(
            oldInputPar.isNegative(),
            FILE,
            "Balance must be negative"
        );
        Require.that(
            newInputPar.isPositive(),
            FILE,
            "Loans cannot be overpaid"
        );
        Require.that(
            inputWei.isPositive(),
            FILE,
            "Loans must be decreased"
        );

        // expiry time validation
        Require.that(
            Time.hasHappened(getExpiry(makerAccount, inputMarketId)),
            FILE,
            "Loan not yet expired"
        );

        // clear expiry if loan is fully repaid
        if (newInputPar.value == 0) {
            setExpiry(makerAccount, inputMarketId, 0);
        }

        // get maximum acceptable return value
        Types.Wei memory maxOutputWei = SOLO_MARGIN.getAccountWei(makerAccount, outputMarketId);
        Require.that(
            maxOutputWei.isPositive(),
            FILE,
            "Collateral must be positive"
        );

        // get return value
        Types.AssetAmount memory output = inputWeiToOutput(
            inputWei,
            inputMarketId,
            outputMarketId
        );
        Require.that(
            output.value <= maxOutputWei.value,
            FILE,
            "Collateral cannot be overtaken"
        );

        return output;
    }

function inputWeiToOutput(
        Types.Wei memory inputWei,
        uint256 inputMarketId,
        uint256 outputMarketId
    )
        private
        view
        returns (Types.AssetAmount memory)
    {
        Decimal.D256 memory spread = SOLO_MARGIN.getLiquidationSpread();
        uint256 nonSpreadValue = Math.getPartial(
            inputWei.value,
            SOLO_MARGIN.getMarketPrice(inputMarketId).value,
            SOLO_MARGIN.getMarketPrice(outputMarketId).value
        );
        return Types.AssetAmount({
            sign: false,
            denomination: Types.AssetDenomination.Wei,
            ref: Types.AssetReference.Delta,
            value: Decimal.mul(nonSpreadValue, spread)
        });
    }

function parseCallArgs(
        bytes memory data
    )
        private
        pure
        returns (
            uint256,
            uint32
        )
    {
        Require.that(
            data.length == 64,
            FILE,
            "Call data invalid length"
        );

        uint256 marketId;
        uint256 rawExpiry;

        /* solium-disable-next-line security/no-inline-assembly */
        assembly {
            marketId := mload(add(data, 32))
            rawExpiry := mload(add(data, 64))
        }

        return (
            marketId,
            Math.to32(rawExpiry)
        );
    }

function setExpiry(
        Account.Info memory account,
        uint256 marketId,
        uint32 time
    )
        private
    {
        g_expiries[account.owner][account.number][marketId] = time;

        emit ExpirySet(
            account.owner,
            account.number,
            marketId,
            time
        );
    }

function getExpiry(
        Account.Info memory account,
        uint256 marketId
    )
        private
        view
        returns (uint32)
    {
        return g_expiries[account.owner][account.number][marketId];
    }

function operate(
        Account.Info[] memory accounts,
        Actions.ActionArgs[] memory args
    )
        public
        payable
        nonReentrant
    {
        // create WETH from ETH
        if (msg.value != 0) {
            WETH.deposit.value(msg.value)();
        }

        // validate the input
        for (uint256 i = 0; i < args.length; i++) {
            // For a transfer both accounts must be owned by msg.sender
            if (args[i].actionType == Actions.ActionType.Transfer) {
                address accountTwoOwner = Actions.parseTransferArgs(
                    accounts,
                    args[i]
                ).accountTwo.owner;

                Require.that(
                    accountTwoOwner == msg.sender,
                    FILE,
                    "Sender must own account two",
                    accountTwoOwner
                );
            }

            // Can only operate on accounts owned by msg.sender
            Require.that(
                accounts[args[i].accountId].owner == msg.sender,
                FILE,
                "Sender must own account",
                accounts[args[i].accountId].owner
            );
        }

        SOLO_MARGIN.operate(accounts, args);

        // return all remaining WETH to the msg.sender as ETH
        uint256 remainingWeth = WETH.balanceOf(address(this));
        if (remainingWeth != 0) {
            WETH.withdraw(remainingWeth);
            msg.sender.transfer(remainingWeth);
        }
    }

function to128(
        uint256 x
    )
        internal
        pure
        returns (uint128)
    {
        uint128 r = uint128(x);
        Require.that(
            r == x,
            FILE,
            "Unsafe cast to uint128"
        );
        return r;
    }

function to96(
        uint256 x
    )
        internal
        pure
        returns (uint96)
    {
        uint96 r = uint96(x);
        Require.that(
            r == x,
            FILE,
            "Unsafe cast to uint96"
        );
        return r;
    }

function to32(
        uint256 x
    )
        internal
        pure
        returns (uint32)
    {
        uint32 r = uint32(x);
        Require.that(
            r == x,
            FILE,
            "Unsafe cast to uint32"
        );
        return r;
    }

function calculateNewIndex(
        Index memory index,
        Rate memory rate,
        Types.TotalPar memory totalPar,
        Decimal.D256 memory earningsRate
    )
        internal
        view
        returns (Index memory)
    {
        (
            Types.Wei memory supplyWei,
            Types.Wei memory borrowWei
        ) = totalParToWei(totalPar, index);

        // calculate the interest accrued by
        uint32 currentTime = Time.currentTime();
        uint256 borrowInterest = rate.value.mul(uint256(currentTime).sub(index.lastUpdate));

        // adjust the interest by the earningsRate, then prorate the interest across all suppliers
        uint256 supplyInterest;
        if (Types.isZero(supplyWei)) {
            supplyInterest = 0;
        } else {
            supplyInterest = Decimal.mul(borrowInterest, earningsRate);
            if (borrowWei.value < supplyWei.value) {
                supplyInterest = Math.getPartial(supplyInterest, borrowWei.value, supplyWei.value);
            }
        }
        assert(supplyInterest <= borrowInterest);

        return Index({
            borrow: Math.getPartial(index.borrow, borrowInterest, BASE).add(index.borrow).to96(),
            supply: Math.getPartial(index.supply, supplyInterest, BASE).add(index.supply).to96(),
            lastUpdate: currentTime
        });
    }

function newIndex()
        internal
        view
        returns (Index memory)
    {
        return Index({
            borrow: BASE,
            supply: BASE,
            lastUpdate: Time.currentTime()
        });
    }

