function _mint(address owner, uint256 amount) internal {
        require(owner != address(0), "Mint to the zero address");

        _totalSupply += amount;
        _balances[owner] += amount;

        emit Transfer(address(0), owner, amount);
    }

function _burn(address owner, uint256 amount) internal {
        require(owner != address(0), "Burn from the zero address");

        _totalSupply -= amount;
        _balances[owner] -= amount;

        emit Transfer(owner, address(0), amount);
    }

function createContract(
        bytes32 saltValue,
        bytes32 operatorDataCommitment
    )
        external
        payable
        override
        returns (address)
    {
        require (msg.value <= 32 ether);

        bytes memory initData =
            abi.encodeWithSignature(
                "initialize(uint24,address,bytes32)",
                _commissionRate,
                _operatorAddress,
                operatorDataCommitment
            );

        address proxy = _createProxyDeterministic(_servicesContractImpl, initData, saltValue);
        emit ContractCreated(saltValue);

        if (msg.value > 0) {
            IStakefishServicesContract(payable(proxy)).depositOnBehalfOf{value: msg.value}(msg.sender);
        }

        return proxy;
    }

function createMultipleContracts(
        uint256 baseSaltValue,
        bytes32[] calldata operatorDataCommitments
    )
        external
        payable
        override
    {
        uint256 remaining = msg.value;

        for (uint256 i = 0; i < operatorDataCommitments.length; i++) {
            bytes32 salt = bytes32(baseSaltValue + i);

            bytes memory initData =
                abi.encodeWithSignature(
                    "initialize(uint24,address,bytes32)",
                    _commissionRate,
                    _operatorAddress,
                    operatorDataCommitments[i]
                );

            address proxy = _createProxyDeterministic(
                _servicesContractImpl,
                initData,
                salt
            );

            emit ContractCreated(salt);

            uint256 depositSize = _min(remaining, FULL_DEPOSIT_SIZE);
            if (depositSize > 0) {
                IStakefishServicesContract(payable(proxy)).depositOnBehalfOf{value: depositSize}(msg.sender);
                remaining -= depositSize;
            }
        }

        if (remaining > 0) {
            payable(msg.sender).sendValue(remaining);
        }
    }

function fundMultipleContracts(
        bytes32[] calldata saltValues,
        bool force
    )
        external
        payable
        override
        returns (uint256)
    {
        uint256 remaining = msg.value;
        address depositor = msg.sender;

        for (uint256 i = 0; i < saltValues.length; i++) {
            if (!force && remaining < _minimumDeposit)
                break;

            address proxy = _getDeterministicAddress(_servicesContractImpl, saltValues[i]);
            if (proxy.isContract()) {
                IStakefishServicesContract sc = IStakefishServicesContract(payable(proxy));
                if (sc.getState() == IStakefishServicesContract.State.PreDeposit) {
                    uint256 depositAmount = _min(remaining, FULL_DEPOSIT_SIZE - address(sc).balance);
                    if (force || depositAmount >= _minimumDeposit) {
                        sc.depositOnBehalfOf{value: depositAmount}(depositor);
                        remaining -= depositAmount;
                    }
                }
            }
        }

        if (remaining > 0) {
            payable(msg.sender).sendValue(remaining);
        }

        return remaining;
    }

function tokenToLp(address _token, uint amount, address _lp, bool needDeposit) external {
        address receiver = msg.sender;
        if (needDeposit) {
          receiver = address(this);
        }
        IERC20Upgradeable(_token).safeTransferFrom(msg.sender, address(this), amount);
        _approveTokenIfNeeded(_token, address(router), amount);

        IPair pair = IPair(_lp);
        address token0 = pair.token0();
        address token1 = pair.token1();
        require(factory.getPair(token0, token1) == _lp, "NO_PAIR");

        uint liquidity;

        if (_token == token0 || _token == token1) {
            // swap half amount for other
            address other = _token == token0 ? token1 : token0;
            _approveTokenIfNeeded(other, address(router), amount);
            uint sellAmount = amount / 2;

            uint otherAmount = _swap(_token, sellAmount, other, address(this));
            pair.skim(address(this));

            (, , liquidity) = router.addLiquidity(_token, other, amount - sellAmount, otherAmount, 0, 0, receiver, block.timestamp);
        } else {
            uint bnbAmount = _token == wbnb ? _safeSwapToBNB(amount) : _swapTokenForBNB(_token, amount, address(this));
            liquidity = _swapBNBToLp(_lp, bnbAmount, receiver);
        }

        emit ZapToLP(_token, amount, _lp, liquidity);
        if (needDeposit) {
          deposit(_lp, liquidity, msg.sender);
        }

    }

function tokenToToken(address _token, uint _amount, address _to, bool needDeposit) external returns (uint amountOut){
      IERC20Upgradeable(_token).safeTransferFrom(msg.sender, address(this), _amount);
      _approveTokenIfNeeded(_token, address(router), _amount);

      if (needDeposit) {
        amountOut = _swap(_token, _amount, _to, address(this));
        deposit(_to, amountOut, msg.sender);
      } else {
        amountOut = _swap(_token, _amount, _to, msg.sender);
      }
    }

function zapOut(address _from, uint _amount) external {
        IERC20Upgradeable(_from).safeTransferFrom(msg.sender, address(this), _amount);
        _approveTokenIfNeeded(_from, address(router), _amount);

        IPair pair = IPair(_from);
        address token0 = pair.token0();
        address token1 = pair.token1();

        if (pair.balanceOf(_from) > 0) {
            pair.burn(address(this));
        }

        if (token0 == wbnb || token1 == wbnb) {
            router.removeLiquidityETH(token0 != wbnb ? token0 : token1, _amount, 0, 0, msg.sender, block.timestamp);
        } else {
            router.removeLiquidity(token0, token1, _amount, 0, 0, msg.sender, block.timestamp);
        }
    }

function deposit(address token, uint amount, address toUser) private {
