function addRewardInfo(uint256 _campaignID, uint256 _endBlock, uint256 _rewardPerBlock) external onlyOwner {
        RewardInfo[] storage rewardInfo = campaignRewardInfo[_campaignID];
        CampaignInfo storage campaign = campaignInfo[_campaignID];
        require(rewardInfo.length < rewardInfoLimit, "GrazingRange::addRewardInfo::reward info length exceeds the limit");
        require(rewardInfo.length == 0 || rewardInfo[rewardInfo.length - 1].endBlock >= block.number, "GrazingRange::addRewardInfo::reward period ended");
        require(rewardInfo.length == 0 || rewardInfo[rewardInfo.length - 1].endBlock < _endBlock, "GrazingRange::addRewardInfo::bad new endblock");
        uint256 startBlock = rewardInfo.length == 0 ?  campaign.startBlock : rewardInfo[rewardInfo.length - 1].endBlock;
        uint256 blockRange = _endBlock.sub(startBlock);
        uint256 totalRewards = _rewardPerBlock.mul(blockRange);
        campaign.rewardToken.safeTransferFrom(rewardHolder, address(this), totalRewards);
        campaign.totalRewards = campaign.totalRewards.add(totalRewards);
        rewardInfo.push(RewardInfo({
            endBlock: _endBlock,
            rewardPerBlock: _rewardPerBlock
        }));
        emit AddRewardInfo(_campaignID, rewardInfo.length-1, _endBlock, _rewardPerBlock);
    }

function _updateCampaign(uint256 _campaignID) internal {
        CampaignInfo storage campaign = campaignInfo[_campaignID];
        RewardInfo[] memory rewardInfo = campaignRewardInfo[_campaignID];
        if (block.number <= campaign.lastRewardBlock) {
            return;
        }
        if (campaign.totalStaked == 0) {
            // if there is no total supply, return and use the campaign's start block as the last reward block
            // so that ALL reward will be distributed.
            // however, if the first deposit is out of reward period, last reward block will be its block number
            // in order to keep the multiplier = 0
            if (block.number > _endBlockOf(_campaignID, block.number)) {
                campaign.lastRewardBlock = block.number;
            }
            return;
        }
        // @dev for each reward info
        for (uint256 i = 0; i < rewardInfo.length; ++i) {
            // @dev get multiplier based on current Block and rewardInfo's end block
            // multiplier will be a range of either (current block - campaign.lastRewardBlock)
            // or (reward info's endblock - campaign.lastRewardBlock) or 0
            uint256 multiplier = getMultiplier(campaign.lastRewardBlock, block.number, rewardInfo[i].endBlock);
            if (multiplier == 0) continue;
            // @dev if currentBlock exceed end block, use end block as the last reward block
            // so that for the next iteration, previous endBlock will be used as the last reward block
            if (block.number > rewardInfo[i].endBlock) {
                campaign.lastRewardBlock = rewardInfo[i].endBlock;
            } else {
                campaign.lastRewardBlock = block.number;
            }
            campaign.accRewardPerShare = campaign.accRewardPerShare.add(multiplier.mul(rewardInfo[i].rewardPerBlock).mul(1e12).div(campaign.totalStaked));
        }
    }

function deposit(uint256 _campaignID, uint256 _amount) external nonReentrant {
        CampaignInfo storage campaign = campaignInfo[_campaignID];
        UserInfo storage user = userInfo[_campaignID][msg.sender];
        _updateCampaign(_campaignID);
        if (user.amount > 0) {
            uint256 pending = user.amount.mul(campaign.accRewardPerShare).div(1e12).sub(user.rewardDebt);
            if (pending > 0) {
                campaign.rewardToken.safeTransfer(address(msg.sender), pending);
            }
        }
        if (_amount > 0) {
            campaign.stakingToken.safeTransferFrom(address(msg.sender), address(this), _amount);
            user.amount = user.amount.add(_amount);
            campaign.totalStaked = campaign.totalStaked.add(_amount);
        }
        user.rewardDebt = user.amount.mul(campaign.accRewardPerShare).div(1e12);
        emit Deposit(msg.sender, _amount, _campaignID);
    }

function _withdraw(uint256 _campaignID, uint256 _amount) internal {
        CampaignInfo storage campaign = campaignInfo[_campaignID];
        UserInfo storage user = userInfo[_campaignID][msg.sender];
        require(user.amount >= _amount, "GrazingRange::withdraw::bad withdraw amount");
        _updateCampaign(_campaignID);
        uint256 pending = user.amount.mul(campaign.accRewardPerShare).div(1e12).sub(user.rewardDebt);
        if (pending > 0) {
            campaign.rewardToken.safeTransfer(address(msg.sender), pending);
        }
        if (_amount > 0) {
            user.amount = user.amount.sub(_amount);
            campaign.stakingToken.safeTransfer(address(msg.sender), _amount);
            campaign.totalStaked = campaign.totalStaked.sub(_amount);
        }
        user.rewardDebt = user.amount.mul(campaign.accRewardPerShare).div(1e12);

        emit Withdraw(msg.sender, _amount, _campaignID);
    }

function emergencyWithdraw(uint256 _campaignID) external nonReentrant {
        CampaignInfo storage campaign = campaignInfo[_campaignID];
        UserInfo storage user = userInfo[_campaignID][msg.sender];
        uint256 _amount = user.amount;
        campaign.totalStaked = campaign.totalStaked.sub(_amount);
        user.amount = 0;
        user.rewardDebt = 0;
        campaign.stakingToken.safeTransfer(address(msg.sender), _amount);
        emit EmergencyWithdraw(msg.sender, _amount, _campaignID);
    }

function emergencyRewardWithdraw(uint256 _campaignID, uint256 _amount, address _beneficiary) external onlyOwner nonReentrant {
        CampaignInfo storage campaign = campaignInfo[_campaignID];
        uint256 currentStakingPendingReward = _pendingReward(_campaignID, campaign.totalStaked, 0);
        require(currentStakingPendingReward.add(_amount) <= campaign.totalRewards, "GrazingRange::emergencyRewardWithdraw::not enough reward token");
        campaign.totalRewards = campaign.totalRewards.sub(_amount);
        campaign.rewardToken.safeTransfer(_beneficiary, _amount);
    }

function _endBlockOf(uint256 _campaignID, uint256 _blockNumber) internal view returns (uint256) {
        RewardInfo[] memory rewardInfo = campaignRewardInfo[_campaignID];
        uint256 len = rewardInfo.length;
        if (len == 0) {
            return 0;
        }
        for (uint256 i = 0; i < len; ++i) {
            if (_blockNumber <= rewardInfo[i].endBlock) return rewardInfo[i].endBlock;
        }
        // @dev when couldn't find any reward info, it means that _blockNumber exceed endblock
        // so return the latest reward info.
        return rewardInfo[len-1].endBlock;
    }

function _pendingReward(uint256 _campaignID, uint256 _amount, uint256 _rewardDebt) internal view returns (uint256) {
        CampaignInfo memory campaign = campaignInfo[_campaignID];
        RewardInfo[] memory rewardInfo = campaignRewardInfo[_campaignID];
        uint256 accRewardPerShare = campaign.accRewardPerShare;
        if (block.number > campaign.lastRewardBlock && campaign.totalStaked != 0) {
            uint256 cursor = campaign.lastRewardBlock;
            for (uint256 i = 0; i < rewardInfo.length; ++i) {
                uint256 multiplier = getMultiplier(cursor, block.number, rewardInfo[i].endBlock);
                if (multiplier == 0) continue;
                cursor = rewardInfo[i].endBlock;
                accRewardPerShare = accRewardPerShare.add(multiplier.mul(rewardInfo[i].rewardPerBlock).mul(1e12).div(campaign.totalStaked));
            }
        }
        return _amount.mul(accRewardPerShare).div(1e12).sub(_rewardDebt);
    }

function executeTransaction(
    address target,
    uint value,
    string calldata signature,
    bytes calldata data,
    uint eta
  ) external payable nonReentrant returns (bytes memory) {
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");

    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");

    queuedTransactions[txHash] = false;

    bytes memory callData;

    if (bytes(signature).length == 0) {
      callData = data;
    } else {
      callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }

    // solium-disable-next-line security/no-call-value
    (bool success, bytes memory returnData) = target.call{value: value}(callData);
    require(success, _getRevertMsg(returnData));

    emit ExecuteTransaction(txHash, target, value, signature, data, eta);

    return returnData;
  }

function mint(address to) external lock returns (uint256 liquidity) {
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); // gas savings
    uint256 balance0 = IERC20(token0).balanceOf(address(this));
    uint256 balance1 = IERC20(token1).balanceOf(address(this));
    uint256 amount0 = balance0.sub(_reserve0);
    uint256 amount1 = balance1.sub(_reserve1);

    bool feeOn = _mintFee(_reserve0, _reserve1);
    uint256 _totalSupply = totalSupply; // gas savings, must be defined here since totalSupply can update in _mintFee
    if (_totalSupply == 0) {
      liquidity = Math.sqrt(amount0.mul(amount1)).sub(MINIMUM_LIQUIDITY);
      _mint(address(0), MINIMUM_LIQUIDITY); // permanently lock the first MINIMUM_LIQUIDITY tokens
    } else {
      liquidity = Math.min(amount0.mul(_totalSupply) / _reserve0, amount1.mul(_totalSupply) / _reserve1);
    }
    require(liquidity > 0, "WaultSwap: INSUFFICIENT_LIQUIDITY_MINTED");
    _mint(to, liquidity);

    _update(balance0, balance1, _reserve0, _reserve1);
    if (feeOn) kLast = uint256(reserve0).mul(reserve1); // reserve0 and reserve1 are up-to-date
    emit Mint(msg.sender, amount0, amount1);
  }

function burn(address to) external lock returns (uint256 amount0, uint256 amount1) {
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); // gas savings
    address _token0 = token0; // gas savings
    address _token1 = token1; // gas savings
    uint256 balance0 = IERC20(_token0).balanceOf(address(this));
    uint256 balance1 = IERC20(_token1).balanceOf(address(this));
    uint256 liquidity = balanceOf[address(this)];

    bool feeOn = _mintFee(_reserve0, _reserve1);
    uint256 _totalSupply = totalSupply; // gas savings, must be defined here since totalSupply can update in _mintFee
    amount0 = liquidity.mul(balance0) / _totalSupply; // using balances ensures pro-rata distribution
    amount1 = liquidity.mul(balance1) / _totalSupply; // using balances ensures pro-rata distribution
    require(amount0 > 0 && amount1 > 0, "WaultSwap: INSUFFICIENT_LIQUIDITY_BURNED");
    _burn(address(this), liquidity);
    _safeTransfer(_token0, to, amount0);
    _safeTransfer(_token1, to, amount1);
    balance0 = IERC20(_token0).balanceOf(address(this));
    balance1 = IERC20(_token1).balanceOf(address(this));

    _update(balance0, balance1, _reserve0, _reserve1);
    if (feeOn) kLast = uint256(reserve0).mul(reserve1); // reserve0 and reserve1 are up-to-date
    emit Burn(msg.sender, amount0, amount1, to);
  }

function swap(
    uint256 amount0Out,
    uint256 amount1Out,
    address to,
    bytes calldata data
  ) external lock {
    require(amount0Out > 0 || amount1Out > 0, "WaultSwap: INSUFFICIENT_OUTPUT_AMOUNT");
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); // gas savings
    require(amount0Out < _reserve0 && amount1Out < _reserve1, "WaultSwap: INSUFFICIENT_LIQUIDITY");

    uint256 balance0;
    uint256 balance1;
    {
      // scope for _token{0,1}, avoids stack too deep errors
      address _token0 = token0;
      address _token1 = token1;
      require(to != _token0 && to != _token1, "WaultSwap: INVALID_TO");
      if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out); // optimistically transfer tokens
      if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out); // optimistically transfer tokens
      if (data.length > 0) IWaultSwapCallee(to).waultSwapCall(msg.sender, amount0Out, amount1Out, data);
      balance0 = IERC20(_token0).balanceOf(address(this));
      balance1 = IERC20(_token1).balanceOf(address(this));
    }
    uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
    uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
    require(amount0In > 0 || amount1In > 0, "WaultSwap: INSUFFICIENT_INPUT_AMOUNT");
    {
      // scope for reserve{0,1}Adjusted, avoids stack too deep errors
      uint256 balance0Adjusted = balance0.mul(1000).sub(amount0In.mul(2));
      uint256 balance1Adjusted = balance1.mul(1000).sub(amount1In.mul(2));
      require(balance0Adjusted.mul(balance1Adjusted) >= uint256(_reserve0).mul(_reserve1).mul(1000**2), "WaultSwap: K");
    }

    _update(balance0, balance1, _reserve0, _reserve1);
    emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
  }

function skim(address to) external lock {
    address _token0 = token0; // gas savings
    address _token1 = token1; // gas savings
    _safeTransfer(_token0, to, IERC20(_token0).balanceOf(address(this)).sub(reserve0));
    _safeTransfer(_token1, to, IERC20(_token1).balanceOf(address(this)).sub(reserve1));
  }

function sync() external lock {
    _update(IERC20(token0).balanceOf(address(this)), IERC20(token1).balanceOf(address(this)), reserve0, reserve1);
  }

function _safeTransfer(
    address token,
    address to,
    uint256 value
  ) private {
    (bool success, bytes memory data) = token.call(abi.encodeWithSelector(SELECTOR, to, value));
    require(success && (data.length == 0 || abi.decode(data, (bool))), "WaultSwap: TRANSFER_FAILED");
  }

function _update(
    uint256 balance0,
    uint256 balance1,
    uint112 _reserve0,
    uint112 _reserve1
  ) private {
    require(balance0 <= uint112(-1) && balance1 <= uint112(-1), "WaultSwap: OVERFLOW");
    uint32 blockTimestamp = uint32(block.timestamp % 2**32);
    uint32 timeElapsed = blockTimestamp - blockTimestampLast; // overflow is desired
    if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
      // * never overflows, and + overflow is desired
      price0CumulativeLast += uint256(UQ112x112.encode(_reserve1).uqdiv(_reserve0)) * timeElapsed;
      price1CumulativeLast += uint256(UQ112x112.encode(_reserve0).uqdiv(_reserve1)) * timeElapsed;
    }
    reserve0 = uint112(balance0);
    reserve1 = uint112(balance1);
    blockTimestampLast = blockTimestamp;
    emit Sync(reserve0, reserve1);
  }

function _mintFee(uint112 _reserve0, uint112 _reserve1) private returns (bool feeOn) {
    address feeTo = IWaultSwapFactory(factory).feeTo();
    feeOn = feeTo != address(0);
    uint256 _kLast = kLast; // gas savings
    if (feeOn) {
      if (_kLast != 0) {
        uint256 rootK = Math.sqrt(uint256(_reserve0).mul(_reserve1));
        uint256 rootKLast = Math.sqrt(_kLast);
        if (rootK > rootKLast) {
          uint256 numerator = totalSupply.mul(rootK.sub(rootKLast));
          uint256 denominator = rootK.mul(2).add(rootKLast);
          uint256 liquidity = numerator / denominator;
          if (liquidity > 0) _mint(feeTo, liquidity);
        }
      }
    } else if (_kLast != 0) {
      kLast = 0;
    }
  }

function getReserves()
    public
    view
    returns (
      uint112 _reserve0,
      uint112 _reserve1,
      uint32 _blockTimestampLast
    )
  {
    _reserve0 = reserve0;
    _reserve1 = reserve1;
    _blockTimestampLast = blockTimestampLast;
  }

function _mint(address to, uint256 value) internal {
    totalSupply = totalSupply.add(value);
    balanceOf[to] = balanceOf[to].add(value);
    emit Transfer(address(0), to, value);
  }

function _burn(address from, uint256 value) internal {
    balanceOf[from] = balanceOf[from].sub(value);
    totalSupply = totalSupply.sub(value);
    emit Transfer(from, address(0), value);
  }

function createPair(address tokenA, address tokenB) external returns (address pair) {
    require(tokenA != tokenB, "WaultSwap: IDENTICAL_ADDRESSES");
    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0), "WaultSwap: ZERO_ADDRESS");
    require(getPair[token0][token1] == address(0), "WaultSwap: PAIR_EXISTS"); // single check is sufficient
    bytes memory bytecode = type(WaultSwapPair).creationCode;
    bytes32 salt = keccak256(abi.encodePacked(token0, token1));
    assembly {
      pair := create2(0, add(bytecode, 32), mload(bytecode), salt)
    }
    IWaultSwapPair(pair).initialize(token0, token1);
    getPair[token0][token1] = pair;
    getPair[token1][token0] = pair; // populate mapping in the reverse direction
    allPairs.push(pair);
    emit PairCreated(token0, token1, pair, allPairs.length);
  }

function add(
    uint256 _allocPoint,
    IERC20 _lpToken,
    bool _withUpdate
  ) public onlyOwner {
    if (_withUpdate) {
      massUpdatePools();
    }
    uint256 lastRewardBlock = block.number > startBlock ? block.number : startBlock;
    totalAllocPoint = totalAllocPoint.add(_allocPoint);
    poolInfo.push(
      PoolInfo({ lpToken: _lpToken, allocPoint: _allocPoint, lastRewardBlock: lastRewardBlock, accWexPerShare: 0 })
    );
  }

function pendingWex(uint256 _pid, address _user) external view returns (uint256) {
    PoolInfo storage pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][_user];
    uint256 accWexPerShare = pool.accWexPerShare;
    uint256 lpSupply = pool.lpToken.balanceOf(address(this));
    if (block.number > pool.lastRewardBlock && lpSupply != 0) {
      uint256 multiplier = getMultiplier(pool.lastRewardBlock, block.number);
      uint256 wexReward = multiplier.mul(wexPerBlock).mul(pool.allocPoint).div(totalAllocPoint);
      accWexPerShare = accWexPerShare.add(wexReward.mul(1e12).div(lpSupply));
    }
    return user.amount.mul(accWexPerShare).div(1e12).sub(user.rewardDebt).add(user.pendingRewards);
  }

function updatePool(uint256 _pid) public {
    PoolInfo storage pool = poolInfo[_pid];
    if (block.number <= pool.lastRewardBlock) {
      return;
    }
    uint256 lpSupply = pool.lpToken.balanceOf(address(this));
    if (lpSupply == 0) {
      pool.lastRewardBlock = block.number;
      return;
    }
    uint256 multiplier = getMultiplier(pool.lastRewardBlock, block.number);
    uint256 wexReward = multiplier.mul(wexPerBlock).mul(pool.allocPoint).div(totalAllocPoint);
    wex.mint(address(this), wexReward);
    pool.accWexPerShare = pool.accWexPerShare.add(wexReward.mul(1e12).div(lpSupply));
    pool.lastRewardBlock = block.number;
  }

function deposit(
    uint256 _pid,
    uint256 _amount,
    bool _withdrawRewards
  ) public {
    PoolInfo storage pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    updatePool(_pid);
    if (user.amount > 0) {
      uint256 pending = user.amount.mul(pool.accWexPerShare).div(1e12).sub(user.rewardDebt);

      if (pending > 0) {
        user.pendingRewards = user.pendingRewards.add(pending);

        if (_withdrawRewards) {
          safeWexTransfer(msg.sender, user.pendingRewards);
          emit Claim(msg.sender, _pid, user.pendingRewards);
          user.pendingRewards = 0;
        }
      }
    }
    if (_amount > 0) {
      pool.lpToken.safeTransferFrom(address(msg.sender), address(this), _amount);
      user.amount = user.amount.add(_amount);
    }
    user.rewardDebt = user.amount.mul(pool.accWexPerShare).div(1e12);
    emit Deposit(msg.sender, _pid, _amount);
  }

function withdraw(
    uint256 _pid,
    uint256 _amount,
    bool _withdrawRewards
  ) public {
    PoolInfo storage pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    require(user.amount >= _amount, "withdraw: not good");
    updatePool(_pid);
    uint256 pending = user.amount.mul(pool.accWexPerShare).div(1e12).sub(user.rewardDebt);
    if (pending > 0) {
      user.pendingRewards = user.pendingRewards.add(pending);

      if (_withdrawRewards) {
        safeWexTransfer(msg.sender, user.pendingRewards);
        emit Claim(msg.sender, _pid, user.pendingRewards);
        user.pendingRewards = 0;
      }
    }
    if (_amount > 0) {
      user.amount = user.amount.sub(_amount);
      pool.lpToken.safeTransfer(address(msg.sender), _amount);
    }
    user.rewardDebt = user.amount.mul(pool.accWexPerShare).div(1e12);
    emit Withdraw(msg.sender, _pid, _amount);
  }

function emergencyWithdraw(uint256 _pid) public {
    PoolInfo storage pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    pool.lpToken.safeTransfer(address(msg.sender), user.amount);
    emit EmergencyWithdraw(msg.sender, _pid, user.amount);
    user.amount = 0;
    user.rewardDebt = 0;
    user.pendingRewards = 0;
  }

function claim(uint256 _pid) public {
    PoolInfo storage pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    updatePool(_pid);
    uint256 pending = user.amount.mul(pool.accWexPerShare).div(1e12).sub(user.rewardDebt);
    if (pending > 0 || user.pendingRewards > 0) {
      user.pendingRewards = user.pendingRewards.add(pending);
      safeWexTransfer(msg.sender, user.pendingRewards);
      emit Claim(msg.sender, _pid, user.pendingRewards);
      user.pendingRewards = 0;
    }
    user.rewardDebt = user.amount.mul(pool.accWexPerShare).div(1e12);
  }

function safeWexTransfer(address _to, uint256 _amount) internal {
    uint256 wexBal = wex.balanceOf(address(this));
    if (_amount > wexBal) {
      wex.transfer(_to, wexBal);
    } else {
      wex.transfer(_to, _amount);
    }
  }

function massUpdatePools() public {
    uint256 length = poolInfo.length;
    for (uint256 pid = 0; pid < length; ++pid) {
      updatePool(pid);
    }
  }

function transferAllAlpaca() external override nonReentrant onlyOwner {
    SafeERC20.safeTransfer(IERC20(alpacaTokenAddress), userAddress, IERC20(alpacaTokenAddress).balanceOf(address(this)));
    IAlpacaToken(alpacaTokenAddress).transferAll(msg.sender);
  }

function init(IERC20 _dummyToken) external onlyOwner {
    dummyToken = _dummyToken;
    uint256 balance = dummyToken.balanceOf(msg.sender);
    dummyToken.safeTransferFrom(msg.sender, address(this), balance);
    dummyToken.safeApprove(address(FAIR_LAUNCH_V1), balance);
    FAIR_LAUNCH_V1.deposit(address(this), MASTER_PID, balance);
    emit LogInit();
  }

function addPool(uint256 allocPoint, IERC20 _stakeToken, ILocker _locker, uint256 _startBlock) external onlyOwner {
    require(!isDuplicatedPool(_stakeToken), "FairLaunchV2::addPool:: stakeToken dup");

    uint256 lastRewardBlock = block.number > _startBlock ? block.number : _startBlock;
    totalAllocPoint = totalAllocPoint.add(allocPoint);

    stakeTokens.push(_stakeToken);
    lockers.push(_locker);

    poolInfo.push(PoolInfo({
      allocPoint: allocPoint,
      lastRewardBlock: lastRewardBlock,
      accAlpacaPerShare: 0
    }));
    emit LogPoolAddition(stakeTokens.length.sub(1), allocPoint, _stakeToken, _locker);
  }

function pendingAlpaca(uint256 _pid, address _user) external view returns (uint256) {
    PoolInfo memory pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][_user];
    uint256 accAlpacaPerShare = pool.accAlpacaPerShare;
    uint256 stakeTokenSupply = stakeTokens[_pid].balanceOf(address(this));
    if (block.number > pool.lastRewardBlock && stakeTokenSupply != 0) {
      uint256 blocks = block.number.sub(pool.lastRewardBlock);
      uint256 alpacaReward = blocks.mul(alpacaPerBlock()).mul(pool.allocPoint).mul(ACC_ALPACA_PRECISION).div(totalAllocPoint);
      accAlpacaPerShare = accAlpacaPerShare.add(alpacaReward.div(stakeTokenSupply));
    }
    uint256 _pendingAlpaca = (user.amount.mul(accAlpacaPerShare) / ACC_ALPACA_PRECISION).sub(user.rewardDebt);
    return _pendingAlpaca;
  }

function alpacaPerBlock() public view returns (uint256 amount) {
    amount = uint256(FAIR_LAUNCH_V1.alpacaPerBlock())
      .mul(FAIR_LAUNCH_V1.poolInfo(MASTER_PID).allocPoint) / FAIR_LAUNCH_V1.totalAllocPoint();
  }

function updatePool(uint256 pid) public harvestFromFairLaunchV1 returns (PoolInfo memory pool) {
    pool = poolInfo[pid];
    if (block.number > pool.lastRewardBlock) {
      uint256 stakeTokenSupply = stakeTokens[pid].balanceOf(address(this));
      if (stakeTokenSupply > 0 && totalAllocPoint > 0) {
        uint256 blocks = block.number.sub(pool.lastRewardBlock);
        uint256 alpacaReward = blocks.mul(alpacaPerBlock()).mul(pool.allocPoint).mul(ACC_ALPACA_PRECISION).div(totalAllocPoint);
        pool.accAlpacaPerShare = pool.accAlpacaPerShare.add((alpacaReward.div(stakeTokenSupply)));
      }
      pool.lastRewardBlock = block.number;
      poolInfo[pid] = pool;
      emit LogUpdatePool(pid, pool.lastRewardBlock, stakeTokenSupply, pool.accAlpacaPerShare);
    }
  }

function deposit(address _for, uint256 pid, uint256 amount) external harvestFromFairLaunchV1 nonReentrant {
    PoolInfo memory pool = updatePool(pid);
    UserInfo storage user = userInfo[pid][_for];

    // Validation
    if (user.fundedBy != address(0)) require(user.fundedBy == msg.sender, "FairLaunchV2::deposit:: bad sof");

    // Effects
    user.amount = user.amount.add(amount);
    user.rewardDebt = user.rewardDebt.add(amount.mul(pool.accAlpacaPerShare) / ACC_ALPACA_PRECISION);
    if (user.fundedBy == address(0)) user.fundedBy = msg.sender;

    // Interactions
    stakeTokens[pid].safeTransferFrom(address(msg.sender), address(this), amount);

    emit Deposit(msg.sender, pid, amount, _for);
  }

function withdraw(address _for, uint256 pid, uint256 amount) external nonReentrant {
    PoolInfo memory pool = updatePool(pid);
    UserInfo storage user = userInfo[pid][_for];

    require(user.fundedBy == msg.sender, "FairLaunchV2::withdraw:: only funder");
    require(user.amount >= amount, "FairLaunchV2::withdraw:: not good");

    // Effects
    _harvest(_for, pid);

    user.rewardDebt = user.rewardDebt.sub(amount.mul(pool.accAlpacaPerShare) / ACC_ALPACA_PRECISION);
    user.amount = user.amount.sub(amount);
    if (user.amount == 0) user.fundedBy = address(0);

    // Interactions
    stakeTokens[pid].safeTransfer(msg.sender, amount);

    emit Withdraw(msg.sender, pid, amount, _for);
  }

function _harvest(address to, uint256 pid) internal harvestFromFairLaunchV1 {
    PoolInfo memory pool = poolInfo[pid];
    UserInfo storage user = userInfo[pid][to];
    uint256 accumulatedAlpaca = user.amount.mul(pool.accAlpacaPerShare).div(ACC_ALPACA_PRECISION);
    uint256 _pendingAlpaca = accumulatedAlpaca.sub(user.rewardDebt);
    if (_pendingAlpaca == 0) { return; }

    require(_pendingAlpaca <= ALPACA.balanceOf(address(this)), "FairLaunchV2::_harvest:: wtf not enough alpaca");

    // Effects
    user.rewardDebt = accumulatedAlpaca;

    // Interactions
    ILocker _locker = lockers[pid];
    if (address(_locker) != address(0)) {
      uint256 lockAmount = _locker.calLockAmount(_pendingAlpaca);
      ALPACA.safeApprove(address(_locker), lockAmount);
      _locker.lock(to, lockAmount);
      _pendingAlpaca = _pendingAlpaca.sub(lockAmount);
      ALPACA.safeApprove(address(_locker), 0);
    }

    ALPACA.safeTransfer(to, _pendingAlpaca);

    emit Harvest(msg.sender, pid, _pendingAlpaca);
  }

function emergencyWithdraw(uint256 pid, address to) external nonReentrant {
    UserInfo storage user = userInfo[pid][msg.sender];
    require(user.fundedBy == msg.sender, "FairLaunchV2::emergencyWithdraw:: only funder");
    uint256 amount = user.amount;
    user.amount = 0;
    user.rewardDebt = 0;
    user.fundedBy = address(0);
    // Note: transfer can fail or succeed if `amount` is zero.
    stakeTokens[pid].safeTransfer(to, amount);
    emit EmergencyWithdraw(msg.sender, pid, amount, to);
  }

function isDuplicatedPool(IERC20 _stakeToken) public view returns (bool) {
    uint256 length = poolInfo.length;
    for(uint256 _pid = 0; _pid < length; _pid++) {
      if(stakeTokens[_pid] == _stakeToken) return true;
    }
    return false;
  }

function prepareHodl() external override onlyEOA nonReentrant {
    require(_userRelayerMap[msg.sender] == address(0), "StronkAlpaca::prepareHodl: user has already prepared hodl");
    require(block.number >= hodlableStartBlock, "StronkAlpaca::prepareHodl: block.number not reach hodlableStartBlock");
    require(block.number < hodlableEndBlock, "StronkAlpaca::prepareHodl: block.number exceeds hodlableEndBlock");
    require(IAlpacaToken(alpacaTokenAddress).lockOf(msg.sender) > 0, "StronkAlpaca::preparehodl: user's lockAlpaca must be greater than zero");

    // create relayer contract
    StronkAlpacaRelayer relayer = new StronkAlpacaRelayer(alpacaTokenAddress, msg.sender);
    _userRelayerMap[msg.sender] = address(relayer);
    emit PrepareHodl(msg.sender, address(relayer));
  }

function hodl() external override onlyEOA nonReentrant {
    address relayerAddress = _userRelayerMap[msg.sender];

    require(relayerAddress != address(0), "StronkAlpaca::hodl: user has not preapare hodl yet");

    uint256 relayerAlpacaLockedBalance = IAlpacaToken(alpacaTokenAddress).lockOf(relayerAddress);
    StronkAlpacaRelayer relayer = StronkAlpacaRelayer(relayerAddress);

    relayer.transferAllAlpaca();
    _mint(msg.sender, relayerAlpacaLockedBalance);
    emit Hodl(msg.sender, address(relayer), relayerAlpacaLockedBalance);
  }

function unhodl() external override onlyEOA nonReentrant {
    require(
      block.number > IAlpacaToken(alpacaTokenAddress).endReleaseBlock(),
      "StronkAlpaca::unhodl: block.number have not reach alpacaToken.endReleaseBlock"
    );
    require(block.number > lockEndBlock, "StronkAlpaca::unhodl: block.number have not reach lockEndBlock");

    // unlock all the Alpaca token in case it never have been unlocked yet
    // Note: given that releasePeriodEnd has passed, so that locked token has been 100% released
    if (IAlpacaToken(alpacaTokenAddress).lockOf(address(this)) > 0) {
      IAlpacaToken(alpacaTokenAddress).unlock();
    }

    uint256 userStronkAlpacaBalance = balanceOf(msg.sender);
    // Transfer all userStronkAlpacaBalance to StronkContract and then burn
    SafeERC20.safeTransferFrom(IERC20(address(this)), msg.sender, address(this), userStronkAlpacaBalance);
    // StronkAlpaca burns all user's StronkAlpaca
    _burn(address(this), userStronkAlpacaBalance);

    // transfer Alpaca from Strong Alpaca to user
    SafeERC20.safeTransfer(IERC20(alpacaTokenAddress), msg.sender, userStronkAlpacaBalance);

    emit Unhodl(msg.sender, userStronkAlpacaBalance);
  }

function _mint(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: mint to the zero address");

        _beforeTokenTransfer(address(0), account, amount);

        _totalSupply = _totalSupply.add(amount);
        _balances[account] = _balances[account].add(amount);
        emit Transfer(address(0), account, amount);
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        _balances[account] = _balances[account].sub(amount, "ERC20: burn amount exceeds balance");
        _totalSupply = _totalSupply.sub(amount);
        emit Transfer(account, address(0), amount);
    }

function balanceOf(address account) public view override returns (uint256) {
        return _balances[account];
    }

function claim(
    uint index,
    address account,
    uint amount,
    bytes32[] calldata merkleProof
  ) external override {
    require(!isClaimed(index), 'MerkleDistributor::claim:: drop already claimed');

    // Verify the merkle proof.
    bytes32 node = keccak256(abi.encodePacked(index, account, amount));
    require(MerkleProof.verify(merkleProof, merkleRoot, node), 'MerkleDistributor::claim:: invalid proof');

    // Mark it claimed and send the token.
    _setClaimed(index);
    require(IERC20(token).transfer(account, amount), 'MerkleDistributor::claim:: transfer failed');

    emit Claimed(index, account, amount);
  }

