function isStable(address _worker) public view returns (bool) {
    IWorker02 worker = IWorker02(_worker);
    address[] memory path = worker.getPath();
    // @notice loop over the path for validating the price of each pair
    IPancakePair currentLP;
    uint256 maxPriceDiff = workers[_worker].maxPriceDiff;
    for (uint256 i = 1; i < path.length; i++) {
      // 1. Get the position's LP balance and LP total supply.
      currentLP = IPancakePair(factory.getPair(path[i - 1], path[i]));
      address token0 = currentLP.token0();
      address token1 = currentLP.token1();
      // 2. Check that reserves and balances are consistent (within 1%)
      (uint256 r0, uint256 r1, ) = currentLP.getReserves();
      uint256 t0bal = token0.balanceOf(address(currentLP));
      uint256 t1bal = token1.balanceOf(address(currentLP));
      require(t0bal.mul(100) <= r0.mul(101), "SingleAssetWorkerConfig::isStable:: bad t0 balance");
      require(t1bal.mul(100) <= r1.mul(101), "SingleAssetWorkerConfig::isStable:: bad t1 balance");
      // 3. Check that price is in the acceptable range
      (uint256 price, uint256 lastUpdate) = oracle.getPrice(token0, token1);
      require(lastUpdate >= now - 1 days, "SingleAssetWorkerConfig::isStable:: price too stale");
      uint256 spotPrice = r1.mul(1e18).div(r0);
      require(spotPrice.mul(10000) <= price.mul(maxPriceDiff), "SingleAssetWorkerConfig::isStable:: price too high");
      require(spotPrice.mul(maxPriceDiff) >= price.mul(10000), "SingleAssetWorkerConfig::isStable:: price too low");
    }
    return true;
  }

function isStable(address worker) public view returns (bool) {
    IPancakePair lp = IWorker(worker).lpToken();
    address token0 = lp.token0();
    address token1 = lp.token1();
    // 1. Check that reserves and balances are consistent (within 1%)
    (uint256 r0, uint256 r1, ) = lp.getReserves();
    uint256 t0bal = token0.balanceOf(address(lp));
    uint256 t1bal = token1.balanceOf(address(lp));
    require(t0bal.mul(100) <= r0.mul(101), "WorkerConfig::isStable:: bad t0 balance");
    require(t1bal.mul(100) <= r1.mul(101), "WorkerConfig::isStable:: bad t1 balance");
    // 2. Check that price is in the acceptable range
    (uint256 price, uint256 lastUpdate) = oracle.getPrice(token0, token1);
    require(lastUpdate >= now - 1 days, "WorkerConfig::isStable:: price too stale");
    uint256 lpPrice = r1.mul(1e18).div(r0);
    uint256 maxPriceDiff = workers[worker].maxPriceDiff;
    require(lpPrice <= price.mul(maxPriceDiff).div(10000), "WorkerConfig::isStable:: price too high");
    require(lpPrice >= price.mul(10000).div(maxPriceDiff), "WorkerConfig::isStable:: price too low");
    // 3. Done
    return true;
  }

function getPrice(address token0, address token1) external view override returns (uint256, uint256) {
    require(
      address(priceFeeds[token0][token1]) != address(0) || address(priceFeeds[token1][token0]) != address(0),
      "ChainLinkPriceOracle::getPrice:: no source"
    );
    if (address(priceFeeds[token0][token1]) != address(0)) {
      (, int256 price, , uint256 lastUpdate, ) = priceFeeds[token0][token1].latestRoundData();
      uint256 decimals = uint256(priceFeeds[token0][token1].decimals());
      return (uint256(price).mul(1e18) / (10**decimals), lastUpdate);
    }
    (, int256 price, , uint256 lastUpdate, ) = priceFeeds[token1][token0].latestRoundData();
    uint256 decimals = uint256(priceFeeds[token1][token0].decimals());
    return ((10**decimals).mul(1e18) / uint256(price), lastUpdate);
  }

function work(
    uint256 id,
    address user,
    uint256 debt,
    bytes calldata data
  ) external override onlyOperator nonReentrant {
    // 1. Remove shares on this position back to farming tokens
    _removeShare(id);
    // 2. Perform the worker strategy; sending a basetoken amount to the strategy.
    (address strat, bytes memory ext) = abi.decode(data, (address, bytes));
    require(okStrats[strat], "CakeMaxiWorker::work:: unapproved work strategy");
    baseToken.safeTransfer(strat, baseToken.myBalance());
    farmingToken.safeTransfer(strat, actualFarmingTokenBalance());
    IStrategy(strat).execute(user, debt, ext);
    // 3. Add farming token back to the farming pool. Thus, increasing an LP size of the current position's shares
    _addShare(id);
    // 5. Return any remaining BaseToken back to the operator.
    baseToken.safeTransfer(_msgSender(), baseToken.myBalance());
  }

function health(uint256 id) external view override returns (uint256) {
    IPancakePair currentLP;
    uint256[] memory amount;
    address[] memory reversedPath = getReversedPath();
    amount = new uint256[](reversedPath.length);
    amount[0] = shareToBalance(shares[id]);
    for (uint256 i = 1; i < reversedPath.length; i++) {
      /// 1. Get the current LP based on the specified paths.
      currentLP = IPancakePair(factory.getPair(reversedPath[i - 1], reversedPath[i]));
      /// 2. Get the pool's total supply of the token of path i-1 and the token of path i.
      (uint256 r0, uint256 r1, ) = currentLP.getReserves();
      (uint256 rOut, uint256 rIn) = currentLP.token0() == reversedPath[i] ? (r0, r1) : (r1, r0);
      /// 3. Convert all amount on the token of path i-1 to the token of path i.
      amount[i] = getMktSellAmount(amount[i - 1], rIn, rOut);
    }
    /// @notice return the last amount, since the last amount is the amount that we shall get in baseToken if we sell the farmingToken at the market price
    return amount[amount.length - 1];
  }

function liquidate(uint256 id) external override onlyOperator nonReentrant {
    // 1. Remove shares on this position back to farming tokens
    _removeShare(id);
    farmingToken.safeTransfer(address(liqStrat), actualFarmingTokenBalance());
    liqStrat.execute(address(0), 0, abi.encode(0));
    // 2. Return all available base token back to the operator.
    uint256 wad = baseToken.myBalance();
    baseToken.safeTransfer(_msgSender(), wad);
    emit Liquidate(id, wad);
  }

