function _readUniswapPool(
        uint256 quoteAmount,
        IUniswapV3Pool pool,
        uint8 isUniMultiplied
    ) internal view returns (uint256) {
        uint32[] memory secondAgos = new uint32[](2);

        secondAgos[0] = twapPeriod;
        secondAgos[1] = 0;

        (int56[] memory tickCumulatives, ) = pool.observe(secondAgos);
        int56 tickCumulativesDelta = tickCumulatives[1] - tickCumulatives[0];

        int24 timeWeightedAverageTick = int24(tickCumulativesDelta / int32(twapPeriod));

        // Always round to negative infinity
        if (tickCumulativesDelta < 0 && (tickCumulativesDelta % int56(int32(twapPeriod)) != 0))
            timeWeightedAverageTick--;

        // Computing the `quoteAmount` from the ticks obtained from Uniswap
        return _getQuoteAtTick(timeWeightedAverageTick, quoteAmount, isUniMultiplied);
    }

function increaseTWAPStore(uint16 newLengthStored) external {
        for (uint256 i = 0; i < circuitUniswap.length; i++) {
            circuitUniswap[i].increaseObservationCardinalityNext(newLengthStored);
        }
    }

function buySoldToken(
        IAgToken _agToken,
        uint256 targetSoldTokenQuantity,
        uint256 maxAmountToPayInAgToken
    ) external override whenNotPaused isValid(_agToken) {
        require(targetSoldTokenQuantity > 0, "4");
        // Computing the number of reference stablecoins to burn to get the desired quantity
        // of tokens sold by this contract
        uint256 amountToPayInReference = _computePriceFromQuantity(targetSoldTokenQuantity);

        uint256 amountToPayInAgToken;
        // The validity of the stablecoin has already been checked
        if (address(_agToken) == referenceCoin) {
            amountToPayInAgToken = amountToPayInReference;
        } else {
            // Converting a number of reference stablecoin to a number of desired stablecoin
            // using the oracle associated to each accepted stablecoin
            IOracle oracle = allowedStablecoins[_agToken];
            uint256 oracleValue = oracle.readLower();
            // There is no base problem here as it is a conversion between two Angle's agTokens
            // which are in base `BASE_TOKENS`
            amountToPayInAgToken = (amountToPayInReference * BASE_TOKENS) / oracleValue;
        }
        require(amountToPayInAgToken > 0 && amountToPayInAgToken <= maxAmountToPayInAgToken, "50");

        // Transferring the correct amount of agToken
        _agToken.transferFrom(msg.sender, address(this), amountToPayInAgToken);

        emit TokenSale(targetSoldTokenQuantity, address(_agToken), amountToPayInAgToken);
        // Updating the internal variables
        tokensSold += targetSoldTokenQuantity;

        // Transfering the sold tokens to the caller
        soldToken.safeTransfer(msg.sender, targetSoldTokenQuantity);
    }

function recoverERC20(
        address tokenAddress,
        address to,
        uint256 amountToRecover
    ) external onlyRole(GOVERNOR_ROLE) {
        if (tokenAddress == address(soldToken)) {
            // Updating the number of tokens to sell
            _changeTokensToSell(totalTokensToSell - amountToRecover);
            // No need to check the balance here
            soldToken.safeTransfer(to, amountToRecover);
        } else {
            IERC20(tokenAddress).safeTransfer(to, amountToRecover);
        }
        emit Recovered(tokenAddress, to, amountToRecover);
    }

function _changeTokensToSell(uint256 _totalTokensToSell) internal {
        require(_totalTokensToSell > tokensSold, "54");
        require(soldToken.balanceOf(address(this)) >= _totalTokensToSell - tokensSold, "56");
        totalTokensToSell = _totalTokensToSell;

        emit TokensToSellUpdated(_totalTokensToSell);
    }

function _computePriceFromQuantity(uint256 targetQuantity) internal view returns (uint256 value) {
        uint256 leftToSell = _getQuantityLeftToSell();
        require(targetQuantity < leftToSell, "55");

        // The global value to compute is (with `power = 2` here):
        // `startPrice * totalTokensToSell **(power) * (leftToSell ** (power - 1) - (leftToSell - targetQuantity) ** (power - 1)) /((power - 1) * BASE_TOKENS * leftToSell ** (power - 1) * (leftToSell - targetQuantity) ** (power - 1))`
        // If `totalTokensToSell` is `10**18 * (10**9)` (the maximum we could sell), then `totalTokensToSell ** power` is `(10**27)**power`
        // And `leftToSell ** (power - 1) ` is inferior to `totalTokensToSell ** power`
        // In this case the fact that power = 2 simplifies the computation
        // Computation can hence be done as follows progressively without doing all the multiplications first to avoid overflows
        value = (totalTokensToSell**2) / leftToSell;
        value = (value * startPrice) / BASE_TOKENS;
        value = (value * targetQuantity) / (leftToSell - targetQuantity);
    }

function addGovernor(address _governor) external override onlyGovernor zeroCheck(_governor) {
        require(!governorMap[_governor], "46");
        governorMap[_governor] = true;
        _governorList.push(_governor);
        // Propagates the changes to maintain consistency across all the contracts that are attached to this
        // `Core` contract
        for (uint256 i = 0; i < _stablecoinList.length; i++) {
            // Since a zero address check has already been performed in this contract, there is no need
            // to repeat this check in underlying contracts
            IStableMaster(_stablecoinList[i]).addGovernor(_governor);
        }

        emit GovernorRoleGranted(_governor);
    }

function removeGovernor(address _governor) external override onlyGovernor {
        // Checking if removing the governor will leave with at least more than one governor
        uint256 governorListLength = _governorList.length;
        require(governorListLength > 1, "47");
        // Removing the governor from the list of governors
        // We still need to check if the address provided was well in the list
        uint256 indexMet;
        for (uint256 i = 0; i < governorListLength - 1; i++) {
            if (_governorList[i] == _governor) {
                indexMet = 1;
                _governorList[i] = _governorList[governorListLength - 1];
                break;
            }
        }
        require(indexMet == 1 || _governorList[governorListLength - 1] == _governor, "48");
        _governorList.pop();
        // Once it has been checked that the given address was a correct address, we can proceed to other changes
        delete governorMap[_governor];
        // Maintaining consistency across all contracts
        for (uint256 i = 0; i < _stablecoinList.length; i++) {
            // We have checked in this contract that the mentionned `_governor` here was well a governor
            // There is no need to check this in the underlying contracts where this is going to be updated
            IStableMaster(_stablecoinList[i]).removeGovernor(_governor);
        }

        emit GovernorRoleRevoked(_governor);
    }

function setGuardian(address _newGuardian) external override onlyGuardian zeroCheck(_newGuardian) {
        require(!governorMap[_newGuardian], "39");
        require(guardian != _newGuardian, "49");
        address oldGuardian = guardian;
        guardian = _newGuardian;
        for (uint256 i = 0; i < _stablecoinList.length; i++) {
            IStableMaster(_stablecoinList[i]).setGuardian(_newGuardian, oldGuardian);
        }
        emit GuardianRoleChanged(oldGuardian, _newGuardian);
    }

function revokeGuardian() external override onlyGuardian {
        address oldGuardian = guardian;
        guardian = address(0);
        for (uint256 i = 0; i < _stablecoinList.length; i++) {
            IStableMaster(_stablecoinList[i]).revokeGuardian(oldGuardian);
        }
        emit GuardianRoleChanged(oldGuardian, address(0));
    }

function setCore(ICore newCore) external onlyGovernor zeroCheck(address(newCore)) {
        require(address(this) != address(newCore), "40");
        require(guardian == newCore.guardian(), "41");
        // The length of the lists are stored as cache variables to avoid duplicate reads in storage
        // Checking the consistency of the `_governorList` and of the `_stablecoinList`
        uint256 governorListLength = _governorList.length;
        address[] memory _newCoreGovernorList = newCore.governorList();
        uint256 stablecoinListLength = _stablecoinList.length;
        address[] memory _newStablecoinList = newCore.stablecoinList();
        require(
            governorListLength == _newCoreGovernorList.length && stablecoinListLength == _newStablecoinList.length,
            "42"
        );
        uint256 indexMet;
        for (uint256 i = 0; i < governorListLength; i++) {
            if (!governorMap[_newCoreGovernorList[i]]) {
                indexMet = 1;
                break;
            }
        }
        for (uint256 i = 0; i < stablecoinListLength; i++) {
            // The stablecoin lists should preserve exactly the same order of elements
            if (_stablecoinList[i] != _newStablecoinList[i]) {
                indexMet = 1;
                break;
            }
        }
        // Only performing one require, hence making it cheaper for a governance with a correct initialization
        require(indexMet == 0, "43");
        // Propagates the change
        for (uint256 i = 0; i < stablecoinListLength; i++) {
            IStableMaster(_stablecoinList[i]).setCore(address(newCore));
        }
        emit CoreChanged(address(newCore));
    }

function deployStableMaster(address agToken) external onlyGovernor zeroCheck(agToken) {
        address stableMaster = IAgToken(agToken).stableMaster();
        // Checking if `stableMaster` has not already been deployed
        require(!deployedStableMasterMap[stableMaster], "44");

        // Storing and initializing information about the stablecoin
        _stablecoinList.push(stableMaster);
        // Adding this `stableMaster` in the `deployedStableMasterMap`: it is not going to be possible
        // to revoke and then redeploy this contract
        deployedStableMasterMap[stableMaster] = true;

        IStableMaster(stableMaster).deploy(_governorList, guardian, agToken);

        emit StableMasterDeployed(address(stableMaster), agToken);
    }

function triggerSettlement(
        uint256 _oracleValue,
        uint256 _sanRate,
        uint256 _stocksUsers
    ) external override onlyRole(STABLEMASTER_ROLE) {
        require(startTimestamp == 0, "59");
        require(proportionalRatioGovLP != 0 && proportionalRatioGovUser != 0, "60");
        oracleValueHA = _oracleValue;
        sanRate = _sanRate;
        maxStablecoinsClaimable = _stocksUsers;
        startTimestamp = block.timestamp;
        amountToRedistribute = underlyingToken.balanceOf(address(this));
        emit SettlementTriggered(amountToRedistribute);
    }

function claimUser(
        address dest,
        uint256 amountAgToken,
        uint256 amountGovToken
    ) external onlyClaimPeriod whenNotPaused {
        require(dest != address(0), "0");
        require(totalUserClaimsWithGov + totalUserClaims + amountAgToken <= maxStablecoinsClaimable, "61");
        // Since this involves a `transferFrom`, it is normal to update the variables after the transfers are done
        // No need to use `safeTransfer` for agTokens and ANGLE tokens
        agToken.transferFrom(msg.sender, address(this), amountAgToken);
        if (amountGovToken > 0) {
            angle.transferFrom(msg.sender, address(this), amountGovToken);
            // From the `amountGovToken`, computing the portion of the initial claim that is going to be
            // treated as a preferable claim
            uint256 amountAgTokenGov = (amountGovToken * BASE_PARAMS) / proportionalRatioGovUser;
            amountAgTokenGov = amountAgTokenGov > amountAgToken ? amountAgToken : amountAgTokenGov;
            amountAgToken -= amountAgTokenGov;
            totalUserClaimsWithGov += amountAgTokenGov;
            userClaimsWithGov[dest].govTokens += amountGovToken;
            userClaimsWithGov[dest].claim += amountAgTokenGov;
            emit UserClaimGovUpdated(totalUserClaimsWithGov);
        }
        // The claims for users are stored in stablecoin value: conversion will be done later on at the end on
        // the claim period
        totalUserClaims += amountAgToken;
        userClaims[dest] += amountAgToken;
        emit UserClaimUpdated(totalUserClaims);
    }

function claimHA(uint256 perpetualID, uint256 amountGovToken) external onlyClaimPeriod whenNotPaused {
        require(perpetualManager.isApprovedOrOwner(msg.sender, perpetualID), "21");
        // Getting the owner of the perpetual
        // The zero address cannot own a perpetual
        address dest = perpetualManager.ownerOf(perpetualID);
        require(haClaimCheck[perpetualID] == 0, "64");
        // A HA cannot claim a given perpetual twice
        haClaimCheck[perpetualID] = 1;
        // Computing the amount of the claim from the perpetual
        (uint256 amountInC, uint256 reachMaintenanceMargin) = perpetualManager.getCashOutAmount(
            perpetualID,
            oracleValueHA
        );
        // If the perpetual is below the maintenance margin, then the claim of the HA is null
        if (reachMaintenanceMargin != 1 && amountInC > 0) {
            // Updating the contract's mappings accordingly
            _treatLPClaim(dest, amountGovToken, amountInC);
        }
    }

function claimSLP(
        address dest,
        uint256 amountSanToken,
        uint256 amountGovToken
    ) external onlyClaimPeriod whenNotPaused {
        require(dest != address(0), "0");
        sanToken.transferFrom(msg.sender, address(this), amountSanToken);
        // Computing the amount of the claim from the number of sanTokens sent
        uint256 amountInC = (amountSanToken * sanRate) / BASE_TOKENS;
        // Updating the contract's mappings accordingly
        _treatLPClaim(dest, amountGovToken, amountInC);
    }

function setAmountToRedistributeEach() external whenNotPaused {
        // Checking if it is the right time to call the function: claim period should be over
        require(startTimestamp != 0 && block.timestamp > claimTime + startTimestamp, "63");
        // This is what guarantees that this function can only be computed once
        require(baseAmountToEachComputed == 0, "62");
        baseAmountToEachComputed = 1;
        // Fetching the oracle value at which stablecoins will be converted to collateral
        oracleValueUsers = oracle.readLower();
        // The waterfall first gives everything that's possible to stable holders which had governance tokens
        // in the limit of what is owed to them
        // We need to convert the user claims expressed in stablecoin value to claims in collateral value
        uint256 totalUserClaimsWithGovInC = (totalUserClaimsWithGov * collatBase) / oracleValueUsers;
        uint256 totalUserClaimsInC = (totalUserClaims * collatBase) / oracleValueUsers;
        if (amountToRedistribute >= totalUserClaimsWithGovInC) {
            baseAmountToUserGov = uint64(BASE_PARAMS);
            amountToRedistribute -= totalUserClaimsWithGovInC;
        } else {
            baseAmountToUserGov = uint64((amountToRedistribute * BASE_PARAMS) / totalUserClaimsWithGovInC);
            amountToRedistribute = 0;
        }
        // Then it gives everything that remains to other stable holders (in the limit of what is owed to them)
        if (amountToRedistribute > totalUserClaimsInC) {
            baseAmountToUser = uint64(BASE_PARAMS);
            amountToRedistribute -= totalUserClaimsInC;
        } else {
            baseAmountToUser = uint64((amountToRedistribute * BASE_PARAMS) / totalUserClaimsInC);
            amountToRedistribute = 0;
        }
        // After that, LPs which had governance tokens claims are going to be treated: once again the contract
        // gives them everything it can in the limit of their claim
        if (amountToRedistribute > totalLpClaimsWithGov) {
            baseAmountToLpGov = uint64(BASE_PARAMS);
            amountToRedistribute -= totalLpClaimsWithGov;
        } else {
            baseAmountToLpGov = uint64((amountToRedistribute * BASE_PARAMS) / totalLpClaimsWithGov);
            amountToRedistribute = 0;
        }
        // And last, LPs claims without governance tokens are handled
        if (amountToRedistribute > totalLpClaims) {
            baseAmountToLp = uint64(BASE_PARAMS);
            amountToRedistribute -= totalLpClaims;
        } else {
            baseAmountToLp = uint64((amountToRedistribute * BASE_PARAMS) / totalLpClaims);
            amountToRedistribute = 0;
        }

        emit AmountToRedistributeAnnouncement(
            baseAmountToUserGov,
            baseAmountToUser,
            baseAmountToLpGov,
            baseAmountToLp,
            amountToRedistribute
        );
    }

function redeemCollateral(address user) external onlyBaseAmountsComputed whenNotPaused {
        // Converting the claims stored for each user in collateral value
        uint256 amountToGive = ((userClaimsWithGov[user].claim * collatBase * baseAmountToUserGov) /
            oracleValueUsers +
            (userClaims[user] * collatBase * baseAmountToUser) /
            oracleValueUsers +
            lpClaimsWithGov[user].claim *
            baseAmountToLpGov +
            lpClaims[user] *
            baseAmountToLp) / BASE_PARAMS;
        uint256 amountGovTokens = lpClaimsWithGov[user].govTokens + userClaimsWithGov[user].govTokens;
        // Deleting the amounts stored for each so that someone cannot come and claim twice
        delete userClaimsWithGov[user];
        delete userClaims[user];
        delete lpClaimsWithGov[user];
        delete lpClaims[user];
        if (amountToGive > 0) {
            underlyingToken.safeTransfer(user, amountToGive);
        }
        if (amountGovTokens > 0) {
            angle.transfer(user, amountGovTokens);
        }
    }

function setAmountToRedistribute(uint256 newAmountToRedistribute) external onlyRole(GOVERNOR_ROLE) onlyClaimPeriod {
        require(underlyingToken.balanceOf(address(this)) >= newAmountToRedistribute, "66");
        amountToRedistribute = newAmountToRedistribute;

        emit AmountRedistributeUpdated(amountToRedistribute);
    }

function recoverERC20(
        address tokenAddress,
        address to,
        uint256 amountToRecover
    ) external onlyRole(GOVERNOR_ROLE) onlyBaseAmountsComputed {
        if (tokenAddress == address(underlyingToken)) {
            require(amountToRedistribute >= amountToRecover, "66");
            amountToRedistribute -= amountToRecover;
            underlyingToken.safeTransfer(to, amountToRecover);
        } else {
            IERC20(tokenAddress).safeTransfer(to, amountToRecover);
        }
        emit Recovered(tokenAddress, to, amountToRecover);
    }

function _treatLPClaim(
        address dest,
        uint256 amountGovToken,
        uint256 amountInC
    ) internal {
        if (amountGovToken > 0) {
            angle.transferFrom(msg.sender, address(this), amountGovToken);
            uint256 amountInCGov = (amountGovToken * BASE_PARAMS) / proportionalRatioGovLP;
            amountInCGov = amountInCGov > amountInC ? amountInC : amountInCGov;
            amountInC -= amountInCGov;
            totalLpClaimsWithGov += amountInCGov;
            lpClaimsWithGov[dest].govTokens += amountGovToken;
            lpClaimsWithGov[dest].claim += amountInCGov;
            emit LPClaimGovUpdated(totalLpClaimsWithGov);
        }
        totalLpClaims += amountInC;
        lpClaims[dest] += amountInC;
        emit LPClaimUpdated(totalLpClaims);
    }

function _secureTransfer(address owner, uint256 amount) internal {
        uint256 curBalance = poolManager.getBalance();
        if (curBalance >= amount && amount > 0) {
            // Case where there is enough in reserves to reimburse the person
            _token.safeTransferFrom(address(poolManager), owner, amount);
        } else if (amount > 0) {
            // When there is not enough to reimburse the entire amount, the protocol reimburses
            // what it can using its reserves and the rest is paid in sanTokens at the current
            // exchange rate
            uint256 amountLeft = amount - curBalance;
            _token.safeTransferFrom(address(poolManager), owner, curBalance);
            _stableMaster.convertToSLP(amountLeft, owner);
        }
    }

function _getOraclePrice() internal view returns (uint256, uint256) {
        return oracle.readAll();
    }

function _computeHedgeRatio(uint256 currentHedgeAmount) internal view returns (uint64 ratio) {
        // Fetching info from the `StableMaster`: the amount to hedge is based on the `stocksUsers`
        // of the given collateral
        uint256 targetHedgeAmount = (_stableMaster.getStocksUsers() * targetHAHedge) / BASE_PARAMS;
        if (currentHedgeAmount < targetHedgeAmount)
            ratio = uint64((currentHedgeAmount * BASE_PARAMS) / targetHedgeAmount);
        else ratio = uint64(BASE_PARAMS);
    }

function _getReward(uint256 perpetualID, uint256 hedge) internal {
        _updateReward(perpetualID, hedge);
        uint256 reward = rewards[perpetualID];
        if (reward > 0) {
            rewards[perpetualID] = 0;
            address owner = _owners[perpetualID];
            // Attention here, there may be reentrancy attacks because of the following call
            // to an external contract done before other things are modified. Yet since the `rewardToken`
            // is mostly going to be a trusted contract controlled by governance (namely the ANGLE token), then
            // there is no point in putting an expensive `nonReentrant` modifier in the functions in `PerpetualManagerFront`
            // that allow indirect interactions with `_updateReward`. If new `rewardTokens` are set, we could think about
            // upgrading the `PerpetualManagerFront` contract
            rewardToken.safeTransfer(owner, reward);
            emit RewardPaid(owner, reward);
        }
    }

function setTargetAndLimitHAHedge(uint64 _targetHAHedge, uint64 _limitHAHedge)
        external
        override
        onlyRole(GUARDIAN_ROLE)
        onlyCompatibleFees(_targetHAHedge)
        onlyCompatibleFees(_limitHAHedge)
    {
        require(_targetHAHedge <= _limitHAHedge, "8");
        limitHAHedge = _limitHAHedge;
        targetHAHedge = _targetHAHedge;
        // Updating the value in the `stableMaster` contract
        _stableMaster.setTargetHAHedge(_targetHAHedge);
        emit TargetAndLimitHAHedgeUpdated(_targetHAHedge, _limitHAHedge);
    }

function notifyRewardAmount(uint256 reward) external override onlyRewardsDistribution {
        rewardPerTokenStored = _rewardPerToken();

        if (block.timestamp >= periodFinish) {
            // If the period is not done, then the reward rate changes
            rewardRate = reward / rewardsDuration;
        } else {
            uint256 remaining = periodFinish - block.timestamp;
            uint256 leftover = remaining * rewardRate;
            // If the period is not over, we compute the reward left and increase reward duration
            rewardRate = (reward + leftover) / rewardsDuration;
        }
        // Ensuring the provided reward amount is not more than the balance in the contract.
        // This keeps the reward rate in the right range, preventing overflows due to
        // very high values of `rewardRate` in the earned and `rewardsPerToken` functions;
        // Reward + leftover must be less than 2^256 / 10^18 to avoid overflow.
        uint256 balance = rewardToken.balanceOf(address(this));

        require(rewardRate <= balance / rewardsDuration, "22");

        lastUpdateTime = block.timestamp;
        // Change the duration
        periodFinish = block.timestamp + rewardsDuration;
        emit RewardAdded(reward);
    }

function recoverERC20(
        address tokenAddress,
        address to,
        uint256 tokenAmount
    ) external override onlyRewardsDistribution {
        require(tokenAddress != address(rewardToken), "20");
        IERC20(tokenAddress).safeTransfer(to, tokenAmount);
        emit Recovered(tokenAddress, to, tokenAmount);
    }

function openPerpetual(
        address owner,
        uint256 margin,
        uint256 committedAmount,
        uint256 maxOracleRate,
        uint256 minNetMargin
    ) external override whenNotPaused zeroCheck(owner) returns (uint256 perpetualID) {
        // Transaction will revert anyway if `margin` is zero
        require(committedAmount > 0, "27");

        // There could be a reentrancy attack as a call to an external contract is done before state variables
        // updates. Yet in this case, the call involves a transfer from the `msg.sender` to the contract which
        // eliminates the risk
        _token.safeTransferFrom(msg.sender, address(poolManager), margin);

        // Computing the oracle value
        // Only the highest oracle value (between Chainlink and Uniswap) we get is stored in the perpetual
        (, uint256 rateUp) = _getOraclePrice();
        // Checking if the oracle rate is not too big: a too big oracle rate could mean for a HA that the price
        // has become too high to make it interesting to open a perpetual
        require(rateUp <= maxOracleRate, "28");

        // Computing the total amount of stablecoins that this perpetual is going to hedge for the protocol
        uint256 totalHedgeAmountUpdate = (committedAmount * rateUp) / _collatBase;
        // Computing the net amount brought by the HAs to store in the perpetual
        uint256 netMargin = _getNetMargin(margin, totalHedgeAmountUpdate, committedAmount);
        require(netMargin >= minNetMargin, "29");
        // Checking if the perpetual is not too leveraged, even after computing the fees
        require((committedAmount * BASE_PARAMS) <= maxLeverage * netMargin, "30");

        // ERC721 logic
        _perpetualIDcount.increment();
        perpetualID = _perpetualIDcount.current();

        // In the logic of the staking contract, the `_updateReward` should be called
        // before the perpetual is opened
        _updateReward(perpetualID, 0);

        // Updating the total amount of stablecoins hedged by HAs and creating the perpetual
        totalHedgeAmount += totalHedgeAmountUpdate;

        perpetualData[perpetualID] = Perpetual(rateUp, block.timestamp, netMargin, committedAmount);

        // Following ERC721 logic, the function `_mint(...)` calls `_checkOnERC721Received` and could then be used as
        // a reentrancy vector. Minting should then only be done at the very end after updating all variables.
        _mint(owner, perpetualID);
        emit PerpetualOpened(perpetualID, rateUp, netMargin, committedAmount);
    }

function addToPerpetual(uint256 perpetualID, uint256 amount) external override whenNotPaused {
        // Loading perpetual data and getting the oracle price
        Perpetual memory perpetual = perpetualData[perpetualID];
        (uint256 rateDown, ) = _getOraclePrice();
        (, uint256 liquidated) = _checkLiquidation(perpetualID, perpetual, rateDown);
        if (liquidated == 0) {
            // Overflow check
            _token.safeTransferFrom(msg.sender, address(poolManager), amount);
            perpetualData[perpetualID].margin += amount;
            emit PerpetualUpdated(perpetualID, perpetual.margin + amount);
        }
    }

function forceClosePerpetuals(uint256[] memory perpetualIDs) external override whenNotPaused {
        // Getting the oracle prices
        // `rateUp` is used to compute the cost of manipulation of the covered amounts
        (uint256 rateDown, uint256 rateUp) = _getOraclePrice();

        // Fetching `stocksUsers` to check if perpetuals cover too much collateral
        uint256 stocksUsers = _stableMaster.getStocksUsers();
        uint256 targetHedgeAmount = (stocksUsers * targetHAHedge) / BASE_PARAMS;

        // `totalHedgeAmount` should be greater than the limit hedge amount
        require(totalHedgeAmount > (stocksUsers * limitHAHedge) / BASE_PARAMS, "34");
        uint256 liquidationFees;
        uint256 cashOutFees;

        // Array of pairs `(owner, netCashOutAmount)`
        Pairs[] memory outputPairs = new Pairs[](perpetualIDs.length);

        for (uint256 i = 0; i < perpetualIDs.length; i++) {
            uint256 perpetualID = perpetualIDs[i];
            address owner = _owners[perpetualID];
            if (owner != address(0)) {
                // Loading perpetual data and getting the oracle price
                Perpetual memory perpetual = perpetualData[perpetualID];
                // First checking if the perpetual should not be liquidated
                (uint256 cashOutAmount, uint256 liquidated) = _checkLiquidation(perpetualID, perpetual, rateDown);
                if (liquidated == 1) {
                    // This results in the perpetual being liquidated and the keeper being paid the same amount of fees as
                    // what would have been paid if the perpetual had been liquidated using the `liquidatePerpetualFunction`
                    // Computing the incentive for the keeper as a function of the `cashOutAmount` of the perpetual
                    // This incentivizes keepers to react fast
                    liquidationFees += _computeKeeperLiquidationFees(cashOutAmount);
                } else if (perpetual.entryTimestamp + lockTime <= block.timestamp) {
                    // It is impossible to force the closing a perpetual that was just created: in the other case, this
                    // function could be used to do some insider trading and to bypass the `lockTime` limit
                    // If too much collateral is hedged by HAs, then the perpetual can be cashed out
                    _closePerpetual(perpetualID, perpetual);
                    uint64 ratioPostCashOut;
                    // In this situation, `totalHedgeAmount` is the `currentHedgeAmount`
                    if (targetHedgeAmount > totalHedgeAmount) {
                        ratioPostCashOut = uint64((totalHedgeAmount * BASE_PARAMS) / targetHedgeAmount);
                    } else {
                        ratioPostCashOut = uint64(BASE_PARAMS);
                    }
                    // Computing how much the HA will get and the amount of fees paid at closing
                    (uint256 netCashOutAmount, uint256 fees) = _getNetCashOutAmount(
                        cashOutAmount,
                        perpetual.committedAmount,
                        ratioPostCashOut
                    );
                    cashOutFees += fees;
                    // Storing the owners of perpetuals that were forced cash out in a memory array to avoid
                    // reentrancy attacks
                    outputPairs[i] = Pairs(owner, netCashOutAmount);
                }

                // Checking if at this point enough perpetuals have been cashed out
                if (totalHedgeAmount <= targetHedgeAmount) break;
            }
        }

        uint64 ratio = (targetHedgeAmount == 0)
            ? 0
            : uint64((totalHedgeAmount * BASE_PARAMS) / (2 * targetHedgeAmount));
        // Computing the rewards given to the keeper calling this function
        // and transferring the rewards to the keeper
        // Using a cache value of `cashOutFees` to save some gas
        // The value below is the amount of fees that should go to the keeper forcing the closing of perpetuals
        // In the linear by part function, if `xKeeperFeesClosing` is greater than 0.5 (meaning we are not at target yet)
        // then keepers should get almost no fees
        cashOutFees = (cashOutFees * _piecewiseLinear(ratio, xKeeperFeesClosing, yKeeperFeesClosing)) / BASE_PARAMS;
        // The amount of fees that can go to keepers is capped by a parameter set by governance
        cashOutFees = cashOutFees < keeperFeesClosingCap ? cashOutFees : keeperFeesClosingCap;
        // A malicious attacker could take advantage of this function to take a flash loan, burn agTokens
        // to diminish the stocks users and then force close some perpetuals. We also need to check that assuming
        // really small burn transaction fees (of 0.05%), an attacker could make a profit with such flash loan
        // if current hedge is below the target hedge by making such flash loan.
        // The formula for the cost of such flash loan is:
        // `fees * (limitHAHedge - targetHAHedge) * stocksUsers / oracle`
        // In order to avoid doing multiplications after divisions, and to get everything in the correct base, we do:
        uint256 estimatedCost = (5 * (limitHAHedge - targetHAHedge) * stocksUsers * _collatBase) /
            (rateUp * 10000 * BASE_PARAMS);
        cashOutFees = cashOutFees < estimatedCost ? cashOutFees : estimatedCost;

        // Processing transfers after all calculations have been performed
        for (uint256 j = 0; j < perpetualIDs.length; j++) {
            if (outputPairs[j].netCashOutAmount > 0) {
                _secureTransfer(outputPairs[j].owner, outputPairs[j].netCashOutAmount);
            }
        }
        _secureTransfer(msg.sender, cashOutFees + liquidationFees);
    }

function initialize(IPoolManager poolManager_, IERC20 rewardToken_)
        external
        initializer
        zeroCheck(address(rewardToken_))
    {
        // Initializing contracts
        __Pausable_init();
        __AccessControl_init();

        // Creating references
        poolManager = poolManager_;
        _token = IERC20(poolManager_.token());
        _stableMaster = IStableMaster(poolManager_.stableMaster());
        rewardToken = rewardToken_;
        _collatBase = 10**(IERC20Metadata(address(_token)).decimals());
        // The references to the `feeManager` and to the `oracle` contracts are to be set when the contract is deployed

        // Setting up Access Control for this contract
        // There is no need to store the reference to the `PoolManager` address here
        // Once the `POOLMANAGER_ROLE` has been granted, no new addresses can be granted or revoked
        // from this role: a `PerpetualManager` contract can only have one `PoolManager` associated
        _setupRole(POOLMANAGER_ROLE, address(poolManager));
        // `PoolManager` is admin of all the roles. Most of the time, changes are propagated from it
        _setRoleAdmin(GUARDIAN_ROLE, POOLMANAGER_ROLE);
        _setRoleAdmin(POOLMANAGER_ROLE, POOLMANAGER_ROLE);
        // Pausing the contract because it is not functional till the collateral has really been deployed by the
        // `StableMaster`
        _pause();
    }

function _updateReward(uint256 perpetualID, uint256 hedge) internal {
        rewardPerTokenStored = _rewardPerToken();
        lastUpdateTime = _lastTimeRewardApplicable();
        // No need to check if the `perpetualID` exists here, it has already been checked
        // in the code before when this internal function is called
        rewards[perpetualID] = _earned(perpetualID, hedge);
        perpetualRewardPerTokenPaid[perpetualID] = rewardPerTokenStored;
    }

function _rewardPerToken() internal view returns (uint256) {
        if (totalHedgeAmount == 0) {
            return rewardPerTokenStored;
        }
        return
            rewardPerTokenStored +
            ((_lastTimeRewardApplicable() - lastUpdateTime) * rewardRate * BASE_TOKENS) /
            totalHedgeAmount;
    }

function _mint(address to, uint256 perpetualID) internal {
        _balances[to] += 1;
        _owners[perpetualID] = to;
        emit Transfer(address(0), to, perpetualID);
        require(_checkOnERC721Received(address(0), to, perpetualID, ""), "24");
    }

function _getNetMargin(
        uint256 margin,
        uint256 totalHedgeAmountUpdate,
        uint256 committedAmount
    ) internal view returns (uint256 netMargin) {
        // Checking if the HA has the right to open a perpetual with such amount
        // If HAs hedge more than the target amount, then new HAs will not be able to create perpetuals
        // The amount hedged by HAs after opening the perpetual is going to be:
        uint64 ratio = _computeHedgeRatio(totalHedgeAmount + totalHedgeAmountUpdate);
        require(ratio < uint64(BASE_PARAMS), "25");
        // Computing the net margin of HAs to store in the perpetual: it consists simply in deducing fees
        // Those depend on how much is already hedged by HAs compared with what's to hedge
        uint256 haFeesDeposit = (haBonusMalusDeposit * _piecewiseLinear(ratio, xHAFeesDeposit, yHAFeesDeposit)) /
            BASE_PARAMS;
        // Fees are rounded to the advantage of the protocol
        haFeesDeposit = committedAmount - (committedAmount * (BASE_PARAMS - haFeesDeposit)) / BASE_PARAMS;
        // Fees are computed based on the committed amount of the perpetual
        // The following reverts if fees are too big compared to the margin
        netMargin = margin - haFeesDeposit;
    }

function _getNetCashOutAmount(
        uint256 cashOutAmount,
        uint256 committedAmount,
        uint64 ratio
    ) internal view returns (uint256 netCashOutAmount, uint256 feesPaid) {
        feesPaid = (haBonusMalusWithdraw * _piecewiseLinear(ratio, xHAFeesWithdraw, yHAFeesWithdraw)) / BASE_PARAMS;
        // Rounding the fees at the protocol's advantage
        feesPaid = committedAmount - (committedAmount * (BASE_PARAMS - feesPaid)) / BASE_PARAMS;
        if (feesPaid >= cashOutAmount) {
            netCashOutAmount = 0;
            feesPaid = cashOutAmount;
        } else {
            netCashOutAmount = cashOutAmount - feesPaid;
        }
    }

function _closePerpetual(uint256 perpetualID, Perpetual memory perpetual) internal {
        // Handling the staking logic
        // Reward should always be updated before the `totalHedgeAmount`
        // Rewards are distributed to the perpetual which is liquidated
        uint256 hedge = perpetual.committedAmount * perpetual.entryRate;
        _getReward(perpetualID, hedge);
        delete perpetualRewardPerTokenPaid[perpetualID];

        // Updating `totalHedgeAmount` to represent the fact that less money is insured
        totalHedgeAmount -= hedge / _collatBase;

        _burn(perpetualID);
    }

function _computeKeeperLiquidationFees(uint256 cashOutAmount) internal view returns (uint256 keeperFees) {
        keeperFees = (cashOutAmount * keeperFeesLiquidationRatio) / BASE_PARAMS;
        keeperFees = keeperFees < keeperFeesLiquidationCap ? keeperFees : keeperFeesLiquidationCap;
    }

function _setRoleAdmin(bytes32 role, bytes32 adminRole) internal {
        emit RoleAdminChanged(role, getRoleAdmin(role), adminRole);
        _roles[role].adminRole = adminRole;
