                    name0: dPV.name,
                    symbol0: dPV.symbol,
                    decimals0: dPV.decimals,
                    token1: address(0),
                    name1: "",
                    symbol1: "",
                    decimals1: 0
                });
                index++;
            }
        }

        UserMiningInfo[] memory userInfos = new UserMiningInfo[](index);
        for (uint256 i = 0; i < index; i++) {
            userInfos[i] = infos[i];
        }

        return userInfos;
