function orderRemainingInCheckAllowanceAndBalance(
        uint256 _orderId
        ) external view
        returns (uint256)
    {
        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];
        if (!orderCanBeFilled(_orderId)) return 0;
        if (order.deposit) return state.remainingIn;

        return Math.min(
            state.remainingIn,
            Math.min(
                IERC20(order.tokenIn).balanceOf(order.poster),
                IERC20(order.tokenIn).allowance(order.poster,address(this))
                )
            );
    }

function cancelOrder(
        uint256 _orderId
        ) external
    {
        require(_orderId != 0 && _orderId <= orderCount, "Crossroad: Invalid order");

        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];

        require(order.poster == msg.sender, "Crossroad: Can't cancel another poster's order");
        require(state.status == OrderStatus.OPEN, "Crossroad: Order is not open");

        // mark as cancelled
        state.status = OrderStatus.CANCELLED;
        // remove from record keeping
        recordCloseOrder(order.poster, _orderId);

        emit OrderCancelled(_orderId);

        // update amounts
        uint256 _amountIn = state.remainingIn;
        uint256 _amountReward = state.remainingReward;

        state.remainingIn = 0;
        state.remainingOut = 0;
        state.remainingReward = 0;

        // refund any remaining deposit
        if (order.deposit)
        {
            if (order.tokenIn == address(0))
            {
                TransferHelper.safeTransferETH(order.poster,_amountIn);
            }
            else
            {
                IERC20(order.tokenIn).safeTransfer(order.poster,_amountIn);
            }
        }

        // refund any remaining reward
        IERC20(order.tokenReward).safeTransfer(order.poster,_amountReward);
    }

function fillOrderOutToken(
        uint256 _orderId,
        uint256 _amountOut,
        address _to,
        bool _callback,
        bytes calldata _callbackData
        ) external
    {
        require(_orderId != 0 && _orderId <= orderCount, "Crossroad: Invalid order");

        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];

        require(address(0) != order.tokenOut, "Crossroad: Wrong function call");

        uint256 _amountIn;
        uint256 _amountReward;
        (_amountIn,_amountOut,_amountReward) = processFillOrder(_orderId,order,state,_amountOut);

        // transfer token in to caller
        transferTokenInToCaller(_orderId,_amountIn,_to);

        // transfer reward to caller
        IERC20(order.tokenReward).safeTransfer(_to,_amountReward);

        // crossroad callback
        if (_callback)
        {
            ICrossroadCallee(_to).crossroadCall(
                msg.sender,
                _amountIn,
                _amountOut,
                _amountReward,
                _callbackData
                );
        }

        // transfer token out to poster
        IERC20(order.tokenOut).safeTransferFrom(_to,order.poster,_amountOut);
    }

function fillOrderOutBnb(
        uint256 _orderId,
        uint256 _amountOut,
        address _to,
        bool _callback,
        bytes calldata _callbackData
        ) external payable
    {
        require(_orderId != 0 && _orderId <= orderCount, "Crossroad: Invalid order");

        Order storage order = orders[_orderId];
        OrderState storage state = orderStates[_orderId];

        require(address(0) == order.tokenOut, "Crossroad: Wrong function call");

        uint256 _amountIn;
        uint256 _amountReward;
        (_amountIn,_amountOut,_amountReward) = processFillOrder(_orderId,order,state,_amountOut);

        // transfer token in to caller
        transferTokenInToCaller(_orderId,_amountIn,_to);

        // transfer reward to caller
        IERC20(order.tokenReward).safeTransfer(_to,_amountReward);

        // crossroad callback
        uint256 _totalValue = msg.value;
        if (_callback)
        {
            uint256 _prevBalanceBnb = address(this).balance;
            ICrossroadCallee(_to).crossroadCall(
                msg.sender,
                _amountIn,
                _amountOut,
                _amountReward,
                _callbackData
                );
            uint256 _currBalanceBnb = address(this).balance;

            _totalValue += _currBalanceBnb - _prevBalanceBnb;
        }
        require(_amountOut <= _totalValue, "Crossroad: Insufficient BNB paid");

        // refund excess BNB
        TransferHelper.safeTransferETH(msg.sender,_totalValue-_amountOut);

        // transfer token out to poster
        TransferHelper.safeTransferETH(order.poster,_amountOut);
    }

function payFee(
        uint256 _rewardAmount
        ) internal
    {
        IERC20(feeToken).safeTransferFrom(msg.sender,projectAddress,feeAmount);
        IERC20(feeToken).safeTransferFrom(msg.sender,address(this),_rewardAmount);
    }

function buyFee(
        uint256 _bnbAmount,
        uint256 _rewardAmount
        ) internal
    {
        uint256 _prevRewardBalance = IERC20(feeToken).balanceOf(address(this));

        // buy fee and reward
        // transfer fee to project
        uint256 _feeAndRewardAmount = feeAmount + _rewardAmount;
        ITokenAutoBuyer(feeAutoBuyer).buyTokenFixed{value: _bnbAmount}(_feeAndRewardAmount,address(this),msg.sender);
        IERC20(feeToken).safeTransfer(projectAddress,feeAmount);

        require(_prevRewardBalance + _rewardAmount <= IERC20(feeToken).balanceOf(address(this)), "Crossroad: Fee auto buyer error");
    }

function transferTokenInToCaller(
        uint256 _orderId,
        uint256 _amountIn,
        address _to
        ) internal
    {
        Order storage _order = orders[_orderId];

        if (_order.deposit)
        {
            if (_order.tokenIn == address(0))
            {
                TransferHelper.safeTransferETH(_to,_amountIn);
            }
            else
            {
                IERC20(_order.tokenIn).safeTransfer(_to,_amountIn);
            }
        }
        else
        {
            IERC20(_order.tokenIn).safeTransferFrom(_order.poster,_to,_amountIn);
        }
    }

function orderCanBeFilled(
        uint256 _orderId
        ) public view
        returns (bool)
    {
        return
            block.timestamp < orders[_orderId].expiryTime &&
            orderStates[_orderId].status == OrderStatus.OPEN
            ;
    }

function recordCloseOrder(
        address _poster,
        uint256 _orderId
        ) internal
    {
        // update global orders
        {
            openOrderCount -= 1;

            uint256 _nextOpenOrderId = nextOpenOrderIds[_orderId];
            uint256 _prevOpenOrderId = prevOpenOrderIds[_orderId];

            nextOpenOrderIds[_prevOpenOrderId] = _nextOpenOrderId;
            prevOpenOrderIds[_nextOpenOrderId] = _prevOpenOrderId;
        }

        // update poster orders
        {
            posterOpenOrderCounts[_poster] -= 1;

            mapping(uint256 => uint256) storage _nextOpenOrderIds = posterNextOpenOrderIds[_poster];
            mapping(uint256 => uint256) storage _prevOpenOrderIds = posterPrevOpenOrderIds[_poster];

            uint256 _nextOpenOrderId = _nextOpenOrderIds[_orderId];
            uint256 _prevOpenOrderId = _prevOpenOrderIds[_orderId];

            _nextOpenOrderIds[_prevOpenOrderId] = _nextOpenOrderId;
            _prevOpenOrderIds[_nextOpenOrderId] = _prevOpenOrderId;
        }
    }

function buyTokenFixed(
        uint256 _amountOut,
        address _outTarget,
        address _refundTarget
        ) external payable
        returns (uint256)
    {
        uint256 _amountInBusd = amountIn(lpDjinnBusd, false, _amountOut, SWAP_PERMILLION_PCS1);
        uint256 _amountInWbnb = amountIn(lpWbnbBusd, true, _amountInBusd, SWAP_PERMILLION_PCS2);

        require(_amountInWbnb <= msg.value, "DjinnAutoBuyer: Insufficient BNB");

        uint256 _amountRefund = msg.value.sub(_amountInWbnb);

        // execute swap and transfer djinn to sender
        IWETH(wbnbToken).deposit{value: _amountInWbnb}();
        IWETH(wbnbToken).transfer(lpWbnbBusd, _amountInWbnb);
        IUniswapPool(lpWbnbBusd).swap(0, _amountInBusd, lpDjinnBusd, new bytes(0));
        IUniswapPool(lpDjinnBusd).swap(_amountOut, 0, _outTarget, new bytes(0));

        // refund excess BNB
        TransferHelper.safeTransferETH(_refundTarget,_amountRefund);

        emit BoughtToken(_amountOut);
        return _amountRefund;
    }

function buyTokenFromBnb(
        address _outTarget
        ) external payable
    {
        uint256 _amountOutBusd = amountOut(lpWbnbBusd, true, msg.value, SWAP_PERMILLION_PCS2);
        uint256 _amountOutDjinn = amountOut(lpDjinnBusd, false, _amountOutBusd, SWAP_PERMILLION_PCS1);

        // execute swap and transfer djinn to sender
        IWETH(wbnbToken).deposit{value: msg.value}();
        IWETH(wbnbToken).transfer(lpWbnbBusd, msg.value);
        IUniswapPool(lpWbnbBusd).swap(0, _amountOutBusd, lpDjinnBusd, new bytes(0));
        IUniswapPool(lpDjinnBusd).swap(_amountOutDjinn, 0, _outTarget, new bytes(0));

        emit BoughtToken(_amountOutDjinn);
    }

function addLiquidityBnb(
        address _factory,
        address _tokenLp,
        address _token,
        uint _amountTokenDesired,
        uint _amountBnbDesired,
        uint _amountTokenMin,
        uint _amountBnbMin,
        address _to
        ) external payable returns (uint amountToken_, uint amountBnb_, uint liquidity_)
    {
        require(_amountBnbDesired <= msg.value, "LiquidityProxy: Insufficient BNB");

        factoryEnsurePairExistsInner(_factory,_token,WBNB);

        (amountToken_, amountBnb_) = getAddLiquidityAmountsInner(
            _tokenLp,
            _token,
            WBNB,
            _amountTokenDesired,
            _amountBnbDesired,
            _amountTokenMin,
            _amountBnbMin
            );
        IERC20(_token).safeTransferFrom(msg.sender, _tokenLp, amountToken_);
        IWETH(WBNB).deposit{value: amountBnb_}();
        IERC20(WBNB).safeTransfer(_tokenLp, amountBnb_);
        liquidity_ = IUniswapPool(_tokenLp).mint(_to);
        // refund excess bnb
        if (_amountBnbDesired > amountBnb_) TransferHelper.safeTransferETH(msg.sender, _amountBnbDesired - amountBnb_);
    }

function removeLiquidityBnb(
        address _tokenLp,
        address _token,
        uint _liquidity,
        uint _amountTokenMin,
        uint _amountBnbMin,
        address _to
        ) external payable returns (uint amountToken_, uint amountBnb_)
    {
        (amountToken_, amountBnb_) = removeLiquidity(
            _tokenLp,
            _token,
            WBNB,
            _liquidity,
            _amountTokenMin,
            _amountBnbMin,
            address(this)
            );
        IERC20(_token).safeTransfer(_to, amountToken_);
        IWETH(WBNB).withdraw(amountBnb_);
        TransferHelper.safeTransferETH(_to, amountBnb_);
    }

function run(uint256 _ix) {
        require(_ix < A.length);
        uint256 i;

        if (N[_ix][0] > 0) {
            // Static conversion

            StandardBurnableToken token = StandardBurnableToken(A[_ix][0]);
            // Token count multiplier
            uint256 mux = token.allowance(msg.sender, this) / N[_ix][0];
            require(mux > 0);

            // Burning run
            for (i = 0; i < A[_ix].length; ++i) {
                token = StandardBurnableToken(A[_ix][i]);
                token.burnFrom(msg.sender, mux * N[_ix][i]);
            }

            // Transfer up
            for (i = 0; i < B.length; ++i) {
                token = StandardBurnableToken(B[i]);
                require(token.transfer(msg.sender, M[i] * mux));
            }

        } else {
            // Dynamic conversion
            //   Let source token total supply is finite and decrease on each conversion,
            //   just convert finite supply of source to tokens on balance of ambix.
            //         dynamicRate = balance(sink) / total(source)

            // Is available for single source and single sink only
            require(A[_ix].length == 1 && B.length == 1);

            StandardBurnableToken source = StandardBurnableToken(A[_ix][0]);
            StandardBurnableToken sink = StandardBurnableToken(B[0]);

            uint256 scale = 10 ** 18 * sink.balanceOf(this) / source.totalSupply();

            uint256 allowance = source.allowance(msg.sender, this);
            require(allowance > 0);
            source.burnFrom(msg.sender, allowance);

            uint256 reward = scale * allowance / 10 ** 18;
            require(reward > 0);
            require(sink.transfer(msg.sender, reward));
        }
    }

function createLiability(
        bytes _ask,
        bytes _bid
    )
        external 
        onlyLighthouse
        returns (RobotLiability liability)
    {
        // Store in memory available gas
        uint256 gasinit = gasleft();

        // Create liability
        liability = new RobotLiability(robotLiabilityLib);
        emit NewLiability(liability);

        // Parse messages
        require(liability.call(abi.encodePacked(bytes4(0x82fbaa25), _ask))); // liability.ask(...)
        usedHashGuard(liability.askHash());

        require(liability.call(abi.encodePacked(bytes4(0x66193359), _bid))); // liability.bid(...)
        usedHashGuard(liability.bidHash());

        // Transfer lighthouse fee to lighthouse worker directly
        require(xrt.transferFrom(liability.promisor(),
                                 tx.origin,
                                 liability.lighthouseFee()));

        // Transfer liability security and hold on contract
        ERC20 token = liability.token();
        require(token.transferFrom(liability.promisee(),
                                   liability,
                                   liability.cost()));

        // Transfer validator fee and hold on contract
        if (address(liability.validator()) != 0 && liability.validatorFee() > 0)
            require(xrt.transferFrom(liability.promisee(),
                                     liability,
                                     liability.validatorFee()));

        // Accounting gas usage of transaction
        uint256 gas = gasinit - gasleft() + 110525; // Including observation error
        totalGasUtilizing       += gas;
        gasUtilizing[liability] += gas;
     }

function createLighthouse(
        uint256 _minimalFreeze,
        uint256 _timeoutBlocks,
        string  _name
    )
        external
        returns (address lighthouse)
    {
        // Name reservation check
        bytes32 subnode = keccak256(abi.encodePacked(lighthouseNode, keccak256(_name)));
        require(ens.resolver(subnode) == 0);

        // Create lighthouse
        lighthouse = new Lighthouse(lighthouseLib, _minimalFreeze, _timeoutBlocks);
        emit NewLighthouse(lighthouse, _name);
        isLighthouse[lighthouse] = true;

        bytes32 lighthouseNode
            // lighthouse.0.robonomics.eth
            = 0x1e42a8e8e1e8cf36e83d096dcc74af801d0a194a14b897f9c8dfd403b4eebeda;

        // Register subnode
        ens.setSubnodeOwner(lighthouseNode, keccak256(_name), this);

        // Register lighthouse address
        PublicResolver resolver = PublicResolver(ens.resolver(lighthouseNode));
        ens.setResolver(subnode, resolver);
        resolver.setAddr(subnode, lighthouse);
    }

function liabilityFinalized(
        uint256 _gas
    )
        external
        returns (bool)
    {
        require(gasUtilizing[msg.sender] > 0);

        uint256 gas = _gas - gasleft();
        totalGasUtilizing        += gas;
        gasUtilizing[msg.sender] += gas;
        require(xrt.mint(tx.origin, wnFromGas(gasUtilizing[msg.sender])));
        return true;
    }

function usedHashGuard(bytes32 _hash) internal {
        require(!usedHash[_hash]);
        usedHash[_hash] = true;
    }

function wnFromGas(uint256 _gas) public view returns (uint256) {
        // Current gas utilization epoch
        uint256 epoch = totalGasUtilizing / gasEpoch;

        // XRT emission with addition coefficient by gas utilzation epoch
        uint256 wn = _gas * gasPrice * 2**epoch / 3**epoch / auction.finalPrice();

        // Check to not permit emission decrease below wn=gas
        return wn < _gas ? _gas : wn;
    }

function finalize(
        bytes _result,
        bytes _signature,
        bool  _agree
    )
        external
        returns (bool)
    {
        uint256 gasinit = gasleft();
        require(!isFinalized);

        address resultSender = keccak256(abi.encodePacked(this, _result))
            .toEthSignedMessageHash()
            .recover(_signature);
        require(resultSender == promisor);

        if (validator == 0) {
            require(factory.isLighthouse(msg.sender));
            require(token.transfer(promisor, cost));
        } else {
            require(msg.sender == validator);

            isConfirmed = _agree;
            if (isConfirmed)
                require(token.transfer(promisor, cost));
            else
                require(token.transfer(promisee, cost));

            if (validatorFee > 0)
                require(factory.xrt().transfer(validator, validatorFee));
        }

        result = _result;
        isFinalized = true;

        require(factory.liabilityFinalized(gasinit));
        return true;
    }

function refill(uint256 _value) external {
        require(xrt.transferFrom(msg.sender, this, _value));
        require(_value >= minimalFreeze);

        if (balances[msg.sender] == 0) {
            indexOf[msg.sender] = members.length;
            members.push(msg.sender);
        }
        balances[msg.sender] += _value;
    }

function withdraw(uint256 _value) external {
        require(balances[msg.sender] >= _value);
        //SWC-107-Reentrancy: L24
        require(xrt.transfer(msg.sender, _value));
        balances[msg.sender] -= _value;

        // Drop member if quota go to zero
        if (quotaOf(msg.sender) == 0) {
            require(xrt.transfer(msg.sender, balances[msg.sender])); 
            balances[msg.sender] = 0;

            uint256 senderIndex = indexOf[msg.sender];
            uint256 lastIndex = members.length - 1;
            if (senderIndex < lastIndex)
                members[senderIndex] = members[lastIndex];
            members.length -= 1;
        }
    }

function setup(address _xrt, address _ambix, address _factory)
        public
        isOwner
        atStage(Stages.AuctionDeployed)
    {
        // Validate argument
        require(_xrt != 0 && _ambix != 0 && _factory != 0);
        xrt = XRT(_xrt);
        ambix = Ambix(_ambix);
        factory = LiabilityFactory(_factory);

        // Validate token balance
        require(xrt.balanceOf(this) == MAX_TOKENS_SOLD);

        stage = Stages.AuctionSetUp;
    }

function bid(address receiver)
        public
        payable
        isValidPayload
        timedTransitions
        atStage(Stages.AuctionStarted)
        returns (uint amount)
    {
        require(msg.value > 0);
        amount = msg.value;

        // If a bid is done on behalf of a user via ShapeShift, the receiver address is set.
        if (receiver == 0)
            receiver = msg.sender;

        // Prevent that more than 90% of tokens are sold. Only relevant if cap not reached.
        uint maxWei = (MAX_TOKENS_SOLD / 10**18) * calcTokenPrice() - totalReceived;
        uint maxWeiBasedOnTotalReceived = ceiling - totalReceived;
        if (maxWeiBasedOnTotalReceived < maxWei)
            maxWei = maxWeiBasedOnTotalReceived;

        // Only invest maximum possible amount.
        if (amount > maxWei) {
            amount = maxWei;
            // Send change back to receiver address. In case of a ShapeShift bid the user receives the change back directly.
            receiver.transfer(msg.value - amount);
        }

        // Forward funding to ether wallet
        wallet.transfer(amount);

        bids[receiver] += amount;
        totalReceived += amount;
        if (maxWei == amount)
            // When maxWei is equal to the big amount the auction is ended and finalizeAuction is triggered.
            finalizeAuction();
        BidSubmission(receiver, amount);
    }

function claimTokens(address receiver)
        public
        isValidPayload
        timedTransitions
        atStage(Stages.TradingStarted)
    {
        if (receiver == 0)
            receiver = msg.sender;
        uint tokenCount = bids[receiver] * 10**18 / finalPrice;
        bids[receiver] = 0;
        require(xrt.transfer(receiver, tokenCount));
    }

function finalizeAuction()
        private
    {
        stage = Stages.AuctionEnded;
        if (totalReceived == ceiling)
            finalPrice = calcTokenPrice();
        else
            finalPrice = calcStopPrice();
        uint soldTokens = totalReceived * 10**18 / finalPrice;

        // Auction contract transfers all unsold tokens to Ambix contract
        require(xrt.transfer(ambix, MAX_TOKENS_SOLD - soldTokens));

        endTime = now;
    }

function calcTokenPrice()
        constant
        public
        returns (uint)
    {
        return priceFactor * 10**18 / (block.number - startBlock + 7500) + 1;
    }

function calcStopPrice()
        constant
        public
        returns (uint)
    {
        return totalReceived * 10**18 / MAX_TOKENS_SOLD + 1;
    }

