        //only allow registered vaults to call
        require(IPoolRegistry(poolRegistry).vaultMap(poolId,_owner) == msg.sender, "!auth");

        balances[msg.sender] -= _amount;
        totalSupply -= _amount;
        emit Withdrawn(msg.sender, _amount);

