function addPool(uint256 allocPoint, IERC20 _stakeToken, ILocker _locker, uint256 _startBlock) external onlyOwner {
    require(!isDuplicatedPool(_stakeToken), "FairLaunchV2::addPool:: stakeToken dup");

    uint256 lastRewardBlock = block.number > _startBlock ? block.number : _startBlock;
    totalAllocPoint = totalAllocPoint.add(allocPoint);

    stakeTokens.push(_stakeToken);
    lockers.push(_locker);

    poolInfo.push(PoolInfo({
      allocPoint: allocPoint,
      lastRewardBlock: lastRewardBlock,
      accAlpacaPerShare: 0
    }));
    emit LogPoolAddition(stakeTokens.length.sub(1), allocPoint, _stakeToken, _locker);
  }

function pendingAlpaca(uint256 _pid, address _user) external view returns (uint256) {
    PoolInfo memory pool = poolInfo[_pid];
    UserInfo storage user = userInfo[_pid][_user];
    uint256 accAlpacaPerShare = pool.accAlpacaPerShare;
    uint256 stakeTokenSupply = stakeTokens[_pid].balanceOf(address(this));
    if (block.number > pool.lastRewardBlock && stakeTokenSupply != 0) {
      uint256 blocks = block.number.sub(pool.lastRewardBlock);
      uint256 alpacaReward = blocks.mul(alpacaPerBlock()).mul(pool.allocPoint).mul(ACC_ALPACA_PRECISION).div(totalAllocPoint);
      accAlpacaPerShare = accAlpacaPerShare.add(alpacaReward.div(stakeTokenSupply));
    }
    uint256 _pendingAlpaca = (user.amount.mul(accAlpacaPerShare) / ACC_ALPACA_PRECISION).sub(user.rewardDebt);
    return _pendingAlpaca;
  }

function alpacaPerBlock() public view returns (uint256 amount) {
    amount = uint256(FAIR_LAUNCH_V1.alpacaPerBlock())
      .mul(FAIR_LAUNCH_V1.poolInfo(MASTER_PID).allocPoint) / FAIR_LAUNCH_V1.totalAllocPoint();
  }

function updatePool(uint256 pid) public harvestFromFairLaunchV1 returns (PoolInfo memory pool) {
    pool = poolInfo[pid];
    if (block.number > pool.lastRewardBlock) {
      uint256 stakeTokenSupply = stakeTokens[pid].balanceOf(address(this));
      if (stakeTokenSupply > 0 && totalAllocPoint > 0) {
        uint256 blocks = block.number.sub(pool.lastRewardBlock);
        uint256 alpacaReward = blocks.mul(alpacaPerBlock()).mul(pool.allocPoint).mul(ACC_ALPACA_PRECISION).div(totalAllocPoint);
        pool.accAlpacaPerShare = pool.accAlpacaPerShare.add((alpacaReward.div(stakeTokenSupply)));
      }
      pool.lastRewardBlock = block.number;
      poolInfo[pid] = pool;
      emit LogUpdatePool(pid, pool.lastRewardBlock, stakeTokenSupply, pool.accAlpacaPerShare);
    }
  }

function deposit(address _for, uint256 pid, uint256 amount) external harvestFromFairLaunchV1 nonReentrant {
    PoolInfo memory pool = updatePool(pid);
    UserInfo storage user = userInfo[pid][_for];

    // Validation
    if (user.fundedBy != address(0)) require(user.fundedBy == msg.sender, "FairLaunchV2::deposit:: bad sof");

    // Effects
    user.amount = user.amount.add(amount);
    user.rewardDebt = user.rewardDebt.add(amount.mul(pool.accAlpacaPerShare) / ACC_ALPACA_PRECISION);
    if (user.fundedBy == address(0)) user.fundedBy = msg.sender;

    // Interactions
    stakeTokens[pid].safeTransferFrom(address(msg.sender), address(this), amount);

    emit Deposit(msg.sender, pid, amount, _for);
  }

function withdraw(address _for, uint256 pid, uint256 amount) external nonReentrant {
    PoolInfo memory pool = updatePool(pid);
    UserInfo storage user = userInfo[pid][_for];

    require(user.fundedBy == msg.sender, "FairLaunchV2::withdraw:: only funder");
    require(user.amount >= amount, "FairLaunchV2::withdraw:: not good");

    // Effects
    _harvest(_for, pid);

    user.rewardDebt = user.rewardDebt.sub(amount.mul(pool.accAlpacaPerShare) / ACC_ALPACA_PRECISION);
    user.amount = user.amount.sub(amount);
    if (user.amount == 0) user.fundedBy = address(0);

    // Interactions
    stakeTokens[pid].safeTransfer(msg.sender, amount);

    emit Withdraw(msg.sender, pid, amount, _for);
  }

function _harvest(address to, uint256 pid) internal harvestFromFairLaunchV1 {
    PoolInfo memory pool = poolInfo[pid];
    UserInfo storage user = userInfo[pid][to];
    uint256 accumulatedAlpaca = user.amount.mul(pool.accAlpacaPerShare).div(ACC_ALPACA_PRECISION);
    uint256 _pendingAlpaca = accumulatedAlpaca.sub(user.rewardDebt);
    if (_pendingAlpaca == 0) { return; }

    require(_pendingAlpaca <= ALPACA.balanceOf(address(this)), "FairLaunchV2::_harvest:: wtf not enough alpaca");

    // Effects
    user.rewardDebt = accumulatedAlpaca;

    // Interactions
    ILocker _locker = lockers[pid];
    if (address(_locker) != address(0)) {
      uint256 lockAmount = _locker.calLockAmount(_pendingAlpaca);
      ALPACA.safeApprove(address(_locker), lockAmount);
      _locker.lock(to, lockAmount);
      _pendingAlpaca = _pendingAlpaca.sub(lockAmount);
      ALPACA.safeApprove(address(_locker), 0);
    }

    ALPACA.safeTransfer(to, _pendingAlpaca);

    emit Harvest(msg.sender, pid, _pendingAlpaca);
  }

function emergencyWithdraw(uint256 pid, address to) external nonReentrant {
    UserInfo storage user = userInfo[pid][msg.sender];
    require(user.fundedBy == msg.sender, "FairLaunchV2::emergencyWithdraw:: only funder");
    uint256 amount = user.amount;
    user.amount = 0;
    user.rewardDebt = 0;
    user.fundedBy = address(0);
    // Note: transfer can fail or succeed if `amount` is zero.
    stakeTokens[pid].safeTransfer(to, amount);
    emit EmergencyWithdraw(msg.sender, pid, amount, to);
  }

function isDuplicatedPool(IERC20 _stakeToken) public view returns (bool) {
    uint256 length = poolInfo.length;
    for(uint256 _pid = 0; _pid < length; _pid++) {
      if(stakeTokens[_pid] == _stakeToken) return true;
    }
    return false;
  }

function prepareHodl() external override onlyEOA nonReentrant {
    require(_userRelayerMap[msg.sender] == address(0), "StronkAlpaca::prepareHodl: user has already prepared hodl");
    require(block.number >= hodlableStartBlock, "StronkAlpaca::prepareHodl: block.number not reach hodlableStartBlock");
    require(block.number < hodlableEndBlock, "StronkAlpaca::prepareHodl: block.number exceeds hodlableEndBlock");
    require(IAlpacaToken(alpacaTokenAddress).lockOf(msg.sender) > 0, "StronkAlpaca::preparehodl: user's lockAlpaca must be greater than zero");

    // create relayer contract
    StronkAlpacaRelayer relayer = new StronkAlpacaRelayer(alpacaTokenAddress, msg.sender);
    _userRelayerMap[msg.sender] = address(relayer);
    emit PrepareHodl(msg.sender, address(relayer));
  }

function hodl() external override onlyEOA nonReentrant {
    address relayerAddress = _userRelayerMap[msg.sender];

    require(relayerAddress != address(0), "StronkAlpaca::hodl: user has not preapare hodl yet");

    uint256 relayerAlpacaLockedBalance = IAlpacaToken(alpacaTokenAddress).lockOf(relayerAddress);
    StronkAlpacaRelayer relayer = StronkAlpacaRelayer(relayerAddress);

    relayer.transferAllAlpaca();
    _mint(msg.sender, relayerAlpacaLockedBalance);
    emit Hodl(msg.sender, address(relayer), relayerAlpacaLockedBalance);
  }

function unhodl() external override onlyEOA nonReentrant {
    require(
      block.number > IAlpacaToken(alpacaTokenAddress).endReleaseBlock(),
      "StronkAlpaca::unhodl: block.number have not reach alpacaToken.endReleaseBlock"
    );
    require(block.number > lockEndBlock, "StronkAlpaca::unhodl: block.number have not reach lockEndBlock");

    // unlock all the Alpaca token in case it never have been unlocked yet
    // Note: given that releasePeriodEnd has passed, so that locked token has been 100% released
    if (IAlpacaToken(alpacaTokenAddress).lockOf(address(this)) > 0) {
      IAlpacaToken(alpacaTokenAddress).unlock();
    }

    uint256 userStronkAlpacaBalance = balanceOf(msg.sender);
    // Transfer all userStronkAlpacaBalance to StronkContract and then burn
    SafeERC20.safeTransferFrom(IERC20(address(this)), msg.sender, address(this), userStronkAlpacaBalance);
    // StronkAlpaca burns all user's StronkAlpaca
    _burn(address(this), userStronkAlpacaBalance);

    // transfer Alpaca from Strong Alpaca to user
    SafeERC20.safeTransfer(IERC20(alpacaTokenAddress), msg.sender, userStronkAlpacaBalance);

    emit Unhodl(msg.sender, userStronkAlpacaBalance);
  }

function _mint(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: mint to the zero address");

        _beforeTokenTransfer(address(0), account, amount);

        _totalSupply = _totalSupply.add(amount);
        _balances[account] = _balances[account].add(amount);
        emit Transfer(address(0), account, amount);
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        _balances[account] = _balances[account].sub(amount, "ERC20: burn amount exceeds balance");
        _totalSupply = _totalSupply.sub(amount);
        emit Transfer(account, address(0), amount);
    }

function balanceOf(address account) public view override returns (uint256) {
        return _balances[account];
    }

function claim(
    uint index,
    address account,
    uint amount,
    bytes32[] calldata merkleProof
  ) external override {
    require(!isClaimed(index), 'MerkleDistributor::claim:: drop already claimed');

    // Verify the merkle proof.
    bytes32 node = keccak256(abi.encodePacked(index, account, amount));
    require(MerkleProof.verify(merkleProof, merkleRoot, node), 'MerkleDistributor::claim:: invalid proof');

    // Mark it claimed and send the token.
    _setClaimed(index);
    require(IERC20(token).transfer(account, amount), 'MerkleDistributor::claim:: transfer failed');

    emit Claimed(index, account, amount);
  }

